    def _flow_agent_text_matches_terms(self, context_text: str, terms: tuple[str, ...]) -> bool:
        normalized = self._normalize_skill_token(context_text)
        normalized_padded = f"_{normalized}_"
        compact = self._compact_match_text(context_text)
        for term in terms:
            term_text = str(term or "").strip()
            if not term_text:
                continue
            term_normalized = self._normalize_skill_token(term_text)
            term_compact = self._compact_match_text(term_text)
            if term_normalized and f"_{term_normalized}_" in normalized_padded:
                return True
            if term_compact and len(term_compact) >= 5 and term_compact in compact:
                return True
        return False

    def _flow_agent_product_rule_context_text(self, product_key: str) -> str:
        product_key = str(product_key or "").strip()
        suite = PRODUCT_SHOT_RULES.get(product_key) if product_key else None
        if not suite:
            return product_key
        return " ".join(
            str(part or "").strip()
            for part in (
                product_key,
                suite.get("display_name"),
                " ".join(str(alias or "") for alias in suite.get("aliases", ())[:12]),
            )
            if str(part or "").strip()
        )

    def _flow_agent_occasion_decor_rule(self, context_text: str, product_key: str = "") -> str:
        product_key = str(product_key or "").strip()
        context = " ".join(
            part
            for part in (
                str(context_text or "").strip(),
                self._flow_agent_product_rule_context_text(product_key),
            )
            if part
        )
        matched: List[Dict[str, Any]] = []
        for spec in self._flow_agent_occasion_decor_specs():
            spec_product_keys = {str(item or "").strip() for item in spec.get("product_keys", ()) if str(item or "").strip()}
            if product_key and product_key in spec_product_keys:
                matched.append(spec)
                continue
            if self._flow_agent_text_matches_terms(context, tuple(spec.get("terms", ()))):
                matched.append(spec)

        seen: set[str] = set()
        deduped: List[Dict[str, Any]] = []
        for spec in matched:
            key = str(spec.get("key") or "").strip()
            if not key or key in seen:
                continue
            seen.add(key)
            deduped.append(spec)

        if any(str(spec.get("key")) == "first_birthday" for spec in deduped):
            deduped = [spec for spec in deduped if str(spec.get("key")) != "birthday"]

        base_rule = (
            "Season and occasion decor adaptation rule: choose surrounding props by matching both the exact source product and the occasion/season detected from the Trello card, product rule, and user request. "
            "Decor must stay secondary, sparse, premium handmade Etsy style, and must never cover embroidery, print, seams, handles, cords, tie strings, edges, names, or the main product silhouette. "
            "Keep hero/detail shots cleaner than lifestyle shots; use only 1-3 subtle props when the shot does not explicitly ask for a decorated scene. "
            "Do not mix unrelated seasons in one image, do not force seasonal props when no occasion is present, and if the occasion conflicts with the visible product identity, the source product and Required shot plan win."
        )

        if not deduped:
            return (
                f"{base_rule} If no explicit occasion is detected, use neutral category-appropriate decor: craft tools for handmade/process shots, nursery props for baby products, wedding styling for wedding products, gift packaging for giftable accessories, and clean natural props that fit the visible product use."
            )

        labels = ", ".join(str(spec.get("label") or spec.get("key") or "").strip() for spec in deduped)
        decor_lines = "; ".join(str(spec.get("decor") or "").strip() for spec in deduped if str(spec.get("decor") or "").strip())
        return f"{base_rule} Detected occasion/season: {labels}. For matching shots, {decor_lines}. Keep the exact product unchanged; only adapt the surrounding decor, background, and props."

    def _flow_operator_occasion_decor_rule_for_trello_card(
        self,
        request: CreateJobRequest,
        card: Dict[str, Any],
        signals: Dict[str, Any] | None = None,
    ) -> str:
        signals = signals or self._flow_operator_card_product_signals(request, card)
        attachment_names = " ".join(
            str(item.get("name") or "").strip()
            for item in (card.get("_image_attachments") or [])[:6]
            if isinstance(item, dict) and str(item.get("name") or "").strip()
        )
        context = " ".join(
            str(part or "").strip()
            for part in (
                getattr(request, "title", ""),
                getattr(request, "prompt", ""),
                getattr(request, "prompt_notes", ""),
                getattr(request, "prompt_product", ""),
                getattr(request, "prompt_product_key", ""),
                signals.get("card_name") or card.get("name"),
                signals.get("attachment_names") or attachment_names,
                signals.get("card_description") or self._flow_operator_trello_card_description_note(card),
                signals.get("visual_product_rule_visible_product"),
            )
            if str(part or "").strip()
        )
        return self._flow_agent_occasion_decor_rule(context, str(signals.get("product_rule_key") or "").strip())

    def _flow_operator_product_rule_shot_suite(self, product_key: str) -> List[Dict[str, str]]:
        product_key = str(product_key or "").strip()
        suite = PRODUCT_SHOT_RULES.get(product_key)
        if not suite:
            return []
        display_name = str(suite.get("display_name") or product_key).strip()
        lock = str(suite.get("lock") or "").strip()
        allows_planned_prop_text = bool(suite.get("allow_planned_prop_text"))
        readable_prop_rule = (
            "The only allowed readable prop text is the exact short phrase explicitly required by the listed concept; "
            "it must stay on a separate secondary prop and never become product text or a text overlay."
            if allows_planned_prop_text
            else "Avoid readable tags or cards unless that readable text is visibly on the source product itself."
        )
        suffix = (
            f"Product/category lock: {lock}. "
            "The listed concept may change only the scene, pose, props, color options, or presentation; it must not change the source product form, construction, material, embroidery/print layout, or handmade identity. "
            f"Use clean clear white daylight, keep the product premium handmade, and avoid logos, watermarks, and UI text. {readable_prop_rule}"
        )
        shots: List[Dict[str, str]] = []
        for index, raw_shot in enumerate(suite.get("shots", ()), start=1):
            if len(raw_shot) < 3:
                continue
            kind, title, concept = (str(item or "").strip() for item in raw_shot[:3])
            banner_hook_rule = self._flow_operator_banner_wall_hook_rule_for_shot(product_key, kind, title, concept)
            banner_hook_text = f"{banner_hook_rule} " if banner_hook_rule else ""
            label_bits = [display_name, f"image {index}", title or kind]
            shots.append(
                {
                    "label": " ".join(part for part in label_bits if part),
                    "brief": f"{concept}. {banner_hook_text}{suffix}",
                    "must_include": f"{display_name}, {kind}, exact source product identity",
                }
            )

        supplemental = (
            (
                "Supplemental full product hero",
                f"Clean full-product ecommerce hero for {display_name}, showing the full object clearly with the source design placement and construction visible. {suffix}",
            ),
            (
                "Supplemental alternate angle",
                f"Alternate angle or side/detail view for {display_name}, revealing depth, edge finish, fabric/material texture, and scale while preserving the source product exactly. {suffix}",
            ),
            (
                "Supplemental craft macro",
                f"Premium macro detail of {display_name}, focusing on raised stitches, fabric weave, seams, edge finish, and handmade material quality. {suffix}",
            ),
            (
                "Supplemental gift-ready scene",
                f"Gift-ready presentation for {display_name} with minimal premium packaging or soft props; the product and its design must remain clearly visible. {suffix}",
            ),
            (
                "Supplemental lifestyle variant",
                f"Distinct lifestyle or room-context scene for {display_name}, different from the other shots, with natural interaction or display while the source design stays visible. {suffix}",
            ),
        )
        target = self._flow_operator_product_rule_target_count(product_key)
        fill_index = 0
        while shots and len(shots) < target:
            title, brief = supplemental[fill_index % len(supplemental)]
            shots.append(
                {
                    "label": f"{display_name} image {len(shots) + 1} {title}",
                    "brief": brief,
                    "must_include": f"{display_name}, exact source product identity, no category change",
                }
            )
            fill_index += 1
        return shots

    def _flow_operator_design_analysis_for_trello_card(self, request: CreateJobRequest, card: Dict[str, Any]) -> str:
        signals = self._flow_operator_card_product_signals(request, card)
        card_name = str(signals.get("card_name") or "").strip()
        card_url = str(signals.get("card_url") or "").strip()
        attachment_names = str(signals.get("attachment_names") or "").strip()
        product_rule_key = str(signals.get("product_rule_key") or "").strip()
        product_rule = PRODUCT_SHOT_RULES.get(product_rule_key) if product_rule_key else None
        visual_product_rule_key = str(signals.get("visual_product_rule_key") or "").strip()
        visual_visible_product = str(signals.get("visual_product_rule_visible_product") or "").strip()
        visual_confidence = signals.get("visual_product_rule_confidence")

        product_bits: List[str] = []
        if product_rule and not signals.get("is_apron"):
            product_bits.append(
                f"{str(product_rule.get('display_name') or product_rule_key)} category: {str(product_rule.get('lock') or '').strip()}"
            )
        elif signals.get("is_apron"):
            product_bits.append("apron silhouette, chest bib, waist tie, shoulder/neck straps, hem length, and fit")
        elif signals.get("is_pennant"):
            product_bits.append(
                "pennant/banner wall hanging product, flat hanging fabric panel, top dowel or rod, cord/string hanger, straight side seams, pointed V bottom, flat linen surface, embroidered motif/name placement, and wall decor scale"
            )
        elif signals.get("is_doll"):
            product_bits.append("doll body shape, face, hair/clothing/accessories, fabric texture, proportions, and collectible toy identity")
        elif signals.get("is_plush"):
            product_bits.append("plush toy silhouette, soft fabric pile, stitched seams, facial features, stuffing volume, and cuddly product scale")
        elif signals.get("is_hoop"):
            product_bits.append("embroidery hoop or embroidery frame shape, circular wooden hoop, stretched fabric, personalized name placement, stitched motif layout, thread texture, hanging/display scale, and handmade nursery/wedding decor cues")
        elif signals.get("is_pillowcase"):
            product_bits.append("baby pillowcase or cushion shape, soft fabric texture, pillow volume, name placement, embroidered motifs, nursery-safe styling, and giftable handmade cues")
        elif signals.get("is_child_shirt"):
            product_bits.append("children shirt silhouette, collar/sleeves/hem, print placement, fabric texture, size scale, and kid-safe styling")
        elif signals.get("is_shirt"):
            product_bits.append("shirt silhouette, front print placement, neckline, sleeves, fabric texture, fit, and apparel scale")
        if signals.get("is_embroidery"):
            product_bits.append("hand-embroidered thread texture, stitch direction, raised thread, motif placement, and handmade craft cues")
        if signals.get("is_baking"):
            product_bits.append("bright neutral bakery/kitchen context, baking tools, flour, pastry props, and clean food-safe styling")
        if not product_bits:
            product_bits.append(
                "the visible source object's exact product type, physical silhouette, outline, construction, base color, material texture, print/embroidery details, scale, and hero features without inferring a category from a generic filename"
            )

        visible_sources = ", ".join(part for part in [card_name, attachment_names] if part)
        source_hint = f" Visible Trello clues: {visible_sources}." if visible_sources else ""
        if card_url:
            source_hint += f" Source card: {card_url}."
        if visual_product_rule_key:
            try:
                confidence_text = f"{float(visual_confidence):.2f}"
            except (TypeError, ValueError):
                confidence_text = ""
            display = str(product_rule.get("display_name") or visual_product_rule_key).strip() if product_rule else visual_product_rule_key
            detail = f" as {display}"
            if visual_visible_product:
                detail += f" ({visual_visible_product})"
            if confidence_text:
                detail += f", confidence {confidence_text}"
            source_hint += f" Visual source classification{detail}; this overrides random or generic card filenames."
        inventory_text = str(card.get("_design_inventory_text") or "").strip()
        inventory_hint = (
            f" {self.DESIGN_INVENTORY_MARKER} (reproduce every item literally in every output; this is the design that must not change): {inventory_text}"
            if inventory_text
            else ""
        )
        return (
            "Before creating images, carefully analyze the selected Trello reference image for "
            + "; ".join(product_bits)
            + ". Keep those design features consistent across the whole image set."
            + source_hint
            + inventory_hint
        )

    def _flow_operator_missing_product_rule_detail(self, card: Dict[str, Any], signals: Dict[str, Any]) -> str:
        card_name = str(signals.get("card_name") or card.get("name") or "").strip()
        card_url = str(signals.get("card_url") or card.get("url") or "").strip()
        attachment_names = str(signals.get("attachment_names") or "").strip()
        visual_error = str(card.get("_visual_product_rule_error") or "").strip()
        if visual_error:
            reason = f"Visual classification failed: {visual_error}"
        elif not self._gemini_api_key():
            reason = "Gemini visual classification is not configured."
        elif not self._trello_credentials()[0] or not self._trello_credentials()[1]:
            reason = "Trello credentials are missing, so the source image could not be downloaded for visual classification."
        else:
            reason = "Gemini did not classify the source image into a known HAVI product rule with enough confidence."
        source = ", ".join(part for part in (card_name, attachment_names, card_url) if part) or "unknown Trello card"
        return (
            "Auto AI Trello chua xac dinh duoc HAVI product shot rule cho anh nguon, "
            "nen app bo qua card nay truoc khi gui Flow Agent de tranh tao bo anh sai rule. "
            f"Nguon: {source}. {reason}"
        )

    def _flow_operator_has_product_rule_or_category_signal(self, signals: Dict[str, Any]) -> bool:
        if str(signals.get("product_rule_key") or "").strip():
            return True
        return any(
            bool(signals.get(key))
            for key in (
                "is_apron",
                "is_pennant",
                "is_doll",
                "is_plush",
                "is_hoop",
                "is_pillowcase",
                "is_child_shirt",
                "is_shirt",
            )
        )

