    def _flow_operator_prompt_for_trello_card(
        self,
        request: CreateJobRequest,
        card: Dict[str, Any],
        index: int,
        shot: Dict[str, str] | None = None,
        design_analysis: str = "",
        image_count: int | None = None,
        existing_flow_count: int = 0,
    ) -> str:
        card_name = str(card.get("name") or "").strip()
        card_url = str(card.get("url") or "").strip()
        query = self._trello_auto_search_query(request)
        card_description_note = self._flow_operator_trello_card_description_note(card)
        user_instruction = self._flow_operator_relevant_user_instruction_for_trello_card(request, card)
        signals = self._flow_operator_card_product_signals(request, card)
        product_rule_key = str(signals.get("product_rule_key") or "").strip()
        product_rule = PRODUCT_SHOT_RULES.get(product_rule_key) if product_rule_key else None
        card_id = str(card.get("id") or card.get("shortLink") or "").strip()
        source_attachment_ids = [
            str(item or "").strip()
            for item in (
                card.get("_selected_attachment_ids")
                or getattr(request, "trello_source_attachment_ids", None)
                or getattr(request, "trello_attachment_ids", None)
                or []
            )
            if str(item or "").strip()
        ]
        product_hint = query or card_name or f"card Trello {index + 1}"
        design_analysis = design_analysis or self._flow_operator_design_analysis_for_trello_card(request, card)
        occasion_decor_rule = self._flow_operator_occasion_decor_rule_for_trello_card(request, card, signals)
        target_output_count = self._flow_operator_product_rule_target_count(product_rule_key)
        target_count = max(1, min(target_output_count, int(image_count or target_output_count)))
        existing_flow_count = max(0, min(target_output_count, int(existing_flow_count or 0)))
        all_shots = self._flow_operator_shot_suite_for_trello_card(request, card)
        shot_start = 0
        shots = all_shots[shot_start : shot_start + target_count]
        if len(shots) < target_count and all_shots:
            shots = [*shots, *all_shots[: target_count - len(shots)]]
        shots = shots or all_shots[:target_count]
        shot_summary = "; ".join(
            f"{shot_start + position + 1}. {item.get('label')}: {item.get('brief')}"
            for position, item in enumerate(shots)
            if item.get("label") or item.get("brief")
        )
        if existing_flow_count:
            resume_note = (
                f"This Trello card already has {existing_flow_count}/{target_output_count} Flow output image(s), but Auto now creates a fresh full {target_count}-image set by default. "
                "Do not create only the missing images, do not continue from the old output numbering, and do not reuse or reinterpret old outputs."
            )
        else:
            resume_note = ""
        allows_product_detail_collage = bool(
            signals.get("is_pennant")
            or product_rule_key
            in {
                "drawstring_bag",
                "passport_cover",
                "hair_bow",
                "baby_album",
                "baby_christmas_album",
                "christmas_album",
            }
        )
        allows_planned_multi_panel = bool(product_rule and product_rule.get("allow_planned_multi_panel_shots"))
        allows_planned_infographic_text = bool(product_rule and product_rule.get("allow_planned_infographic_text"))
        allows_planned_prop_text = bool(product_rule and product_rule.get("allow_planned_prop_text"))
        brief_parts = [
            "Use Google Flow Agent as the prompt writer and image-generation operator.",
            self._flow_agent_fresh_context_rule(),
            design_analysis,
            f"Use the selected Trello attachment from card '{card_name or card_url or index + 1}' as the exact source product reference.",
            (
                f"Current source lock: Trello card id {card_id}"
                + (f", selected attachment id(s) {', '.join(source_attachment_ids)}" if source_attachment_ids else "")
                + ". Do not use any other card, attachment, Flow project image, or previous Flow Agent task as the source."
            ) if card_id or source_attachment_ids else "",
            (
                "Critical source lock: the selected Trello attachment is the only authoritative product image. "
                "The source image wins over filename/card text: do not infer product type from generic names like tao_hinh/image/photo or from motif words such as animal, flower, or character. "
                "Ignore other Flow project/gallery images. Every generated output must keep the same product category, silhouette, physical shape, edge construction, motif/design placement, embroidery or print layout, fabric/material texture, base color family, and scale as the source. "
                "Do not turn the source into a tooth fairy pillow, pillow, cushion, blanket, hoop, dress, apron, banner, baby photo album, drawstring bag, passport cover, hair bow, Christmas stocking, plush, shirt, mug, or any other product category unless the source itself is exactly that category. "
                "Do not copy the source motif/name/design onto a different secondary product; props must remain plain and secondary. "
                "The only valid main product is the exact visible product object in the attached source image, with the same outline, construction, and design placement."
            ),
            self._flow_agent_design_replication_rule(),
            (
                "HAVI product shot rule lock: "
                f"{str(product_rule.get('display_name') or product_rule_key)} uses the fixed shot plan imported from HAVI_Shot_Types_All_Products.xlsx. "
                f"{str(product_rule.get('lock') or '').strip()}. "
                f"{('For any wall-hanging banner output, ' + self.BANNER_VISIBLE_WALL_HOOK_RULE + ' ') if product_rule_key == 'banner' else ''}"
                "The product may be styled in the listed scenes, but the product category, construction, material, embroidery/print layout, proportions, and premium handmade identity must not change."
            ) if product_rule and not signals.get("is_apron") else "",
            (
                "Pennant/banner category lock: the source is a flat hanging fabric pennant/banner wall decor product. "
                "Every main generated product must remain a pennant/banner with a top dowel or rod, cord/string hanger, straight side seams, pointed V bottom, flat linen/fabric panel, and the same embroidery layout. "
                f"For any wall-hanging banner output, {self.BANNER_VISIBLE_WALL_HOOK_RULE} "
                "Never create a pillow/cushion/blanket/shirt/hoop version of this design, and never place the source motif or name onto a pillow/cushion/blanket/shirt/hoop. "
                "If a nursery scene includes a pillow, cushion, toy, blanket, or fabric swatch, it must be a plain prop without the source embroidery/design. "
                "For the required process shot only, a round embroidery hoop is allowed as a temporary tool holding the pennant fabric while a person stitches it; it must not become a finished hoop product."
            ) if signals.get("is_pennant") else "",
            resume_note,
            f"First analyze the product, then write your own internal prompts and generate exactly {target_count} commercial product image(s) for {product_hint}.",
            f"Counting rule: the Trello card has one original source/reference image, and that source image is not a generated output. The default target for this run is always a fresh full set of {target_output_count} generated output images plus the 1 source image; do not subtract any existing output attachments from this run.",
            "Create a coherent image set, not one unrelated one-off image.",
            f"Required shot plan: {shot_summary}" if shot_summary else "Required shot plan: detail proof, full hero, lifestyle use, and flat lay or gift-ready scene.",
            occasion_decor_rule,
            "Lighting and color rule for every output: clean clear white neutral daylight, accurate whites, crisp bright product color, no yellow/orange/golden/tungsten/sepia/beige cast, and no warm color grading.",
            (
                "Product-specific notes from the Trello card description: "
                f"{card_description_note}"
            ) if card_description_note else "",
            (
                "Treat the Trello description as user-supplied product guidance for customization, product identity, style, scene restrictions, and do/don't rules; "
                "preserving the source product and avoiding tags, stickers, labels, barcodes, and price tags remain higher-priority constraints."
            ) if card_description_note else "",
            self._flow_agent_reference_prompt_style_guide(
                target_count,
                allow_detail_collage=allows_product_detail_collage,
                allow_planned_multi_panel=allows_planned_multi_panel,
            ),
            (
                "Infographic text exception: only the explicitly numbered infographic shot(s) in the Required shot plan may use the short headings and captions written in that plan. "
                "This does not permit logos, watermarks, price labels, brand tags, product-attached labels, or any extra text in other shots."
            ) if allows_planned_infographic_text else "",
            (
                "Planned prop text exception: only the exact short greeting explicitly required by the numbered shot plan may appear on its separate secondary greeting-card prop. "
                "It must not appear on the product, as an overlay, or in any other image; all logos, watermarks, tags, labels, and other added text remain forbidden."
            ) if allows_planned_prop_text else "",
            "Preserve the original product shape, print/design details, colors, fabric/material texture, and product identity in all images.",
            "Only change scene, styling, lighting, composition, model/background, and presentation around the source product.",
            "Do not change the source product into a different category; if the source is a tooth fairy pillow, it must remain the same tooth-shaped tooth fairy pillow with its ribbon; if the source is a pillow, it must remain a pillow; if it is a baby photo album, it must remain the same cotton linen baby album with its embroidered cover, book construction, and photo-pocket pages when open; if it is a birthday hat, it must remain the same linen birthday hat with its tie strings, pom-poms, ruffle trim if present, and embroidery placement; if it is a birthday crown, it must remain the same linen birthday crown with its pointed band, tie strings, pom-poms, ruffle trim if present, and embroidery placement; if it is a pennant/banner, it must remain a pennant/banner; if it is a round Christmas ornament, it must remain the same small hanging ornament with its exact round frame, clasp, cord, linen face, and embroidery; if it is a Punch Needle Christmas stocking, it must remain the same compact hanging stocking with its exact cuff, toe direction, heel curve, hanging loop, fabric color, motif placement, and raised wool loop texture; if it is a hoop, it must remain a hoop; if it is a drawstring bag, it must remain the same drawstring bag/pouch form with cords; if it is a passport cover, it must remain the same passport cover/passport holder form; if it is a hair bow, bow hair clip, or hair tie bow, it must remain the same hair accessory form with its bow shape, tails, center knot, and elastic/clip hardware; if it is apparel, it must remain the same apparel form.",
            (
                "All outputs must be true 1:1 square product photos. Only the explicitly numbered infographic, detail, or process shots in the Required shot plan may be single 1:1 multi-panel layouts; every other output must be a single standalone image. No landscape crop, portrait crop, contact sheet, grid, or extra multiple-frame canvas."
                if allows_planned_multi_panel
                else (
                    "All outputs must be true 1:1 square product photos. For pennants, image 7 is the only allowed four-panel close-up collage inside one square image; every other output must be a single standalone image. No landscape crop, portrait crop, contact sheet, grid, or extra multiple-frame canvas."
                    if signals.get("is_pennant")
                    else (
                        "All outputs must be true 1:1 square product photos. The explicitly numbered close-up detail collage shot is the only allowed four-panel image inside one square; every other output must be a single standalone image. No landscape crop, portrait crop, contact sheet, grid, or extra multiple-frame canvas."
                        if allows_product_detail_collage
                        else "All outputs must be true 1:1 square product photos; no landscape crop, portrait crop, contact sheet, grid, or multiple-frame canvas."
                    )
                )
            ),
            "Do not use Google Sheet prompts; do not ask the local app AI to write the final prompt.",
        ]
        if user_instruction:
            brief_parts.append(f"User automation instruction: {user_instruction}.")
        if card_url:
            brief_parts.append(f"Source card: {card_url}.")
        return " ".join(part for part in brief_parts if part)

    def _flow_agent_fresh_context_rule(self) -> str:
        return (
            "Fresh-task isolation: treat this message as a new isolated task. Ignore every previous Flow Agent chat message, "
            "approval brief, side-panel title, project memory, old card, prior output set, gallery thumbnail, and example from older runs. "
            "Do not carry over any product category, product name, motif, colorway, scene, or shot idea unless it is visible in the currently attached Trello source image or written on the current Trello card."
        )

    def _trello_ai_prompt_items_for_image_cards(
        self,
        cards: List[Dict[str, Any]],
        request: CreateJobRequest,
        max_items: int,
    ) -> List[Dict[str, Any]]:
        query = self._trello_auto_search_query(request)
        matched_cards = cards
        if query:
            matched_cards = [card for card in cards if self._trello_card_matches_query(card, query)]
            if not matched_cards:
                if len(cards) == 1:
                    matched_cards = cards
                else:
                    return []
        expanded: List[Dict[str, Any]] = []
        for card in matched_cards:
            if len(expanded) >= max_items:
                break
            card_id = str(card.get("id") or card.get("shortLink") or "").strip()
            if not card_id:
                continue
            card_list_id = self._normalize_trello_id(str(card.get("idList") or request.trello_list_id or ""))
            card_name = str(card.get("name") or "").strip()
            card_url = str(card.get("url") or "").strip()
            selected_attachment_ids = self._trello_locked_source_attachment_ids_for_card(card, request.trello_attachment_ids)
            self._flow_operator_enrich_card_with_visual_product_rule(request, card)
            signals = self._flow_operator_card_product_signals(request, card)
            if not self._flow_operator_has_product_rule_or_category_signal(signals):
                card["_auto_trello_skip_code"] = "missing_product_rule"
                card["_auto_trello_skip_reason"] = self._flow_operator_missing_product_rule_detail(card, signals)
                continue
            card.pop("_auto_trello_skip_code", None)
            card.pop("_auto_trello_skip_reason", None)
            design_analysis = self._flow_operator_design_analysis_for_trello_card(request, card)
            all_shots = self._flow_operator_shot_suite_for_trello_card(request, card)
            target_output_count = self._flow_operator_product_rule_target_count(str(signals.get("product_rule_key") or "").strip())
            raw_existing_flow_count = max(0, int(card.get("_flow_output_count") or 0))
            min_outputs = self._trello_source_qa_min_good_images()
            if raw_existing_flow_count >= target_output_count:
                card["_auto_trello_skip_code"] = "complete_output_set"
                card["_auto_trello_skip_reason"] = (
                    f"Card da co {raw_existing_flow_count}/{target_output_count} anh output theo rule; Auto bo qua."
                )
                continue
            if raw_existing_flow_count >= min_outputs:
                # "Upload what we have, never regenerate to fill the gap": a card that already holds a
                # usable partial set is finished and moved to review instead of getting a second full set.
                card["_auto_trello_skip_code"] = "complete_output_set"
                card["_auto_trello_skip_reason"] = (
                    f"Card da co {raw_existing_flow_count}/{target_output_count} anh output; theo chinh sach khong tao bu, "
                    "Auto coi nhu du va chuyen card sang Content Review."
                )
                self._move_partial_output_card_to_review_sync(request, card, raw_existing_flow_count, target_output_count)
                continue
            existing_flow_count = max(0, min(target_output_count, int(card.get("_flow_output_count") or 0)))
            image_count = target_output_count
            shot_start = 0
            shots = all_shots[shot_start : shot_start + image_count]
            if len(shots) < image_count and all_shots:
                shots = [*shots, *all_shots[: image_count - len(shots)]]
            shots = shots or all_shots[:image_count]
            shot_labels = [str(shot.get("label") or "").strip() for shot in shots if str(shot.get("label") or "").strip()]
            prompt = self._flow_operator_prompt_for_trello_card(
                request,
                card,
                len(expanded) + 1,
                design_analysis=design_analysis,
                image_count=image_count,
                existing_flow_count=existing_flow_count,
            )
            expanded.append(
                {
                    "row": 0,
                    "active": True,
                    "used": False,
                    "prompt": prompt,
                    "product": query or card_name,
                    "product_key": query or str(card.get("shortLink") or card_id).strip(),
                    "product_name": card_name,
                    "index": str(len(expanded) + 1),
                    "notes": (
                        f"{design_analysis} Flow Agent will write the final prompts and generate "
                        f"{image_count} fresh image(s). Google Sheet prompt not required."
                    ),
                    "trello_card_id": card_id,
                    "trello_list_id": card_list_id,
                    "trello_attachment_ids": selected_attachment_ids,
                    "trello_source_card_id": card_id,
                    "trello_source_attachment_ids": selected_attachment_ids,
                    "trello_card_name": card_name,
                    "trello_card_url": card_url,
                    "ai_suggested_title": str(card.get("_ai_suggested_title") or "").strip(),
                    "ai_title_status": str(card.get("_ai_title_status") or "").strip(),
                    "ai_title_error": str(card.get("_ai_title_error") or "").strip(),
                    "ai_title_backup_path": str(card.get("_ai_title_backup_path") or "").strip(),
                    "trello_match_mode": "flow_agent",
                    "trello_search_query": query,
                    "shot_label": "Flow Agent image set",
                    "shot_labels": shot_labels,
                    "design_analysis": design_analysis,
                    "flow_agent_instruction": True,
                    "flow_agent_image_count": image_count,
                    "flow_agent_existing_output_count": existing_flow_count,
                    "generated_by_ai": False,
                    "generated_by_flow_agent": True,
                }
            )
        return expanded

    def _trello_query_aliases(self, query: str) -> List[str]:
        aliases = [str(query or "").strip()]
        normalized = self._normalize_skill_token(query)
        compact = self._compact_match_text(query)
        tokens = set(self._tokenize_match_words(query))
        is_child_shirt_query = (
            ("ao" in tokens or "shirt" in tokens or "tshirt" in tokens or "tee" in tokens)
            and (
                bool({"tre", "em", "kid", "kids", "baby", "child", "children", "youth", "toddler"} & tokens)
                or "treem" in compact
            )
        )
        alias_groups = [
            (("tap_de", "tapde", "apron"), ("apron", "baking apron", "kitchen apron", "tap de")),
            (("theu", "embroider", "embroidery"), ("embroidered", "embroidery", "hand embroidered", "handmade")),
            (("gau", "gau_bong", "gaubong"), ("bear", "teddy bear", "plush", "stuffed toy")),
            (("bup_be", "bupbe", "doll", "baby_doll", "babydoll", "bda"), ("doll", "baby doll", "BDA", "doll dress", "baby doll dress")),
            (("ao_tre_em", "aotreem"), ("kids shirt", "children shirt", "baby shirt", "youth tee")),
            (("ao", "shirt", "tshirt"), ("shirt", "tshirt", "tee")),
        ]
        for triggers, values in alias_groups:
            if is_child_shirt_query and triggers == ("ao", "shirt", "tshirt"):
                continue
            if any(trigger in normalized or trigger in compact for trigger in triggers):
                aliases.extend(values)
        product_rule_key = self._flow_operator_product_rule_key_from_text(query)
        if product_rule_key:
            aliases.extend(str(alias) for alias in PRODUCT_SHOT_RULES.get(product_rule_key, {}).get("aliases", ()))
        unique: List[str] = []
        seen: set[str] = set()
        for alias in aliases:
            cleaned = re.sub(r"\s+", " ", str(alias or "").strip())
            key = self._compact_match_text(cleaned)
            if not cleaned or key in seen:
                continue
            seen.add(key)
            unique.append(cleaned)
        return unique

    def _trello_prompt_items_for_keyword_image_cards(
        self,
        cards: List[Dict[str, Any]],
        items: List[Dict[str, Any]],
        request: CreateJobRequest,
        max_items: int,
    ) -> List[Dict[str, Any]]:
        query = self._trello_auto_search_query(request)
        if not query or not cards or not items:
            return []

        matched_cards = [card for card in cards if self._trello_card_matches_query(card, query)]
        if not matched_cards:
            return []
        explicit_card_id = self._normalize_trello_card_id(request.trello_card_id)
        if len(matched_cards) > 1 and not explicit_card_id:
            names = ", ".join(str(card.get("name") or card.get("url") or card.get("id") or "").strip() for card in matched_cards[:5])
            raise RuntimeError(
                "Auto Trello tìm thấy nhiều card cùng khớp từ khóa. "
                f"Hãy dán đúng link card Trello hoặc đổi tên card rõ hơn trước khi chạy: {names}"
            )

        expanded: List[Dict[str, Any]] = []
        used_pairs: set[tuple[str, int, str]] = set()
        for card in matched_cards:
            card_id = str(card.get("id") or card.get("shortLink") or "").strip()
            if not card_id:
                continue
            card_list_id = self._normalize_trello_id(str(card.get("idList") or ""))
            selected_attachment_ids = self._trello_locked_source_attachment_ids_for_card(card, request.trello_attachment_ids)
            item = self._best_prompt_item_for_trello_keyword_card(card, items, used_pairs, query)
            if not item:
                card_name = str(card.get("name") or card.get("url") or card_id).strip()
                raise RuntimeError(
                    "Auto Trello đã tìm thấy card ảnh nhưng chưa tìm thấy prompt Active khớp card/từ khóa. "
                    f"Card: {card_name}. Hãy thêm Product_Key/Product_Name/Notes khớp trong sheet hoặc thêm Trello_Card/Card_URL."
                )
            used_pairs.add((card_id, int(item.get("row") or 0), str(item.get("index") or "")))
            expanded.append(
                {
                    **item,
                    "trello_card_id": card_id,
                    "trello_list_id": card_list_id,
                    "trello_attachment_ids": selected_attachment_ids,
                    "trello_source_card_id": card_id,
                    "trello_source_attachment_ids": selected_attachment_ids,
                    "trello_card_name": str(card.get("name") or "").strip(),
                    "trello_card_url": str(card.get("url") or "").strip(),
                    "trello_match_mode": "keyword",
                    "trello_search_query": query,
                }
            )
            if len(expanded) >= max_items:
                break
        return expanded

    def _trello_auto_search_query(self, request: CreateJobRequest) -> str:
        generic_titles = {
            "auto_image_from_trello_card",
            "automation_image_from_sheet_row",
            "auto_trello_quet_card_co_anh",
            "auto_trello_ai_chay_den_het_ready_for_ai",
            "auto_trello_flow_agent_chay_den_het_ready_for_ai",
            "auto_ai_trello_cho_san_pham_moi_lien_tuc",
            "ready_for_ai",
            "phan_ready_for_ai",
            "trello_search_ready_for_ai",
            "trello_search_phan_ready_for_ai",
        }
        for value in (
            request.prompt_product_key,
            request.prompt_product,
            request.prompt_notes,
            request.title,
        ):
            cleaned = str(value or "").strip()
            if cleaned and self._normalize_skill_token(cleaned) in generic_titles:
                continue
            if cleaned:
                return cleaned[:80]
        return ""

    def _trello_card_matches_query(self, card: Dict[str, Any], query: str) -> bool:
        query_aliases = [self._compact_match_text(alias) for alias in self._trello_query_aliases(query)]
        query_aliases = [alias for alias in query_aliases if alias]
        if not query_aliases:
            return False
        haystack_values = [
            card.get("name"),
            card.get("desc"),
        ]
        for attachment in card.get("_image_attachments") or []:
            if isinstance(attachment, dict):
                haystack_values.append(attachment.get("name"))
        haystack_raw = " ".join(str(value or "") for value in haystack_values)
        haystack = self._compact_match_text(haystack_raw)
        haystack_tokens = set(self._tokenize_match_words(haystack_raw))
        for alias in query_aliases:
            if len(alias) < 4:
                if alias in haystack_tokens:
                    return True
                continue
            if alias in haystack or haystack in alias:
                return True
        return False

    def _best_prompt_item_for_trello_keyword_card(
        self,
        card: Dict[str, Any],
        items: List[Dict[str, Any]],
        used_pairs: set[tuple[str, int, str]],
        query: str,
    ) -> Dict[str, Any]:
        card_id = str(card.get("id") or card.get("shortLink") or "").strip()
        for item in items:
            item_key = (card_id, int(item.get("row") or 0), str(item.get("index") or ""))
            if item_key in used_pairs:
                continue
            hint = {"card_id": card_id, "card_name": str(card.get("name") or "").strip()}
            if self._prompt_batch_item_matches_trello_source(item, hint):
                return item
        for item in items:
            item_key = (card_id, int(item.get("row") or 0), str(item.get("index") or ""))
            if item_key not in used_pairs and self._prompt_batch_item_matches_query(item, query):
                return item
        return {}

    def _prompt_batch_item_matches_query(self, item: Dict[str, Any], query: str) -> bool:
        query_key = self._compact_match_text(query)
        if not query_key:
            return False
        query_groups = self._user_assistant_trello_query_groups(query)
        for value in (
            item.get("product_key"),
            item.get("product_name"),
            item.get("product"),
            item.get("notes"),
            item.get("trello_card_id"),
        ):
            candidate = self._compact_match_text(value)
            if candidate and (query_key in candidate or candidate in query_key):
                return True
            candidate_tokens = set(self._tokenize_match_words(value))
            if candidate_tokens and any(group and all(token in candidate_tokens for token in group) for group in query_groups):
                return True
        return False

    def _trello_image_cards_on_board(
        self,
        key: str,
        token: str,
        board_id: str,
        list_id: str = "",
    ) -> List[Dict[str, Any]]:
        board_id = self._normalize_trello_board_id(board_id)
        list_ids = {
            self._normalize_trello_id(item)
            for item in self._split_trello_list_values(list_id)
            if self._normalize_trello_id(item)
        }
        if not board_id or not list_ids:
            return []
        payload = self._trello_get_json(
            f"boards/{quote(board_id, safe='')}/cards",
            key,
            token,
            fields={
                "fields": "id,name,desc,shortLink,url,idList,closed",
                "filter": "open",
                "attachments": "true",
                "attachment_fields": "id,name,url,mimeType,date",
            },
        )
        cards = payload if isinstance(payload, list) else []
        image_cards: List[Dict[str, Any]] = []
        for card in cards:
            if not isinstance(card, dict) or card.get("closed"):
                continue
            card_id = str(card.get("id") or card.get("shortLink") or "").strip()
            if not card_id:
                continue
            if list_ids and self._normalize_trello_id(str(card.get("idList") or "")) not in list_ids:
                continue
            attachments = self._trello_card_attachments_or_fetch(card, key, token, card_id)
            image_attachments = [
                item for item in attachments if isinstance(item, dict) and self._trello_attachment_is_image(item)
            ]
            source_attachments, flow_outputs = self._trello_source_and_flow_output_attachments(image_attachments)
            if source_attachments:
                card["_image_attachments"] = source_attachments
                card["_selected_attachment_ids"] = [
                    self._normalize_trello_id(str(item.get("id") or ""))
                    for item in source_attachments[:1]
                    if str(item.get("id") or "").strip()
                ]
                card["_flow_output_count"] = len(flow_outputs)
                image_cards.append(card)
        return image_cards

    def _trello_first_image_card_on_board(
        self,
        key: str,
        token: str,
        board_id: str,
        list_id: str = "",
    ) -> Dict[str, Any]:
        cards = self._trello_image_cards_on_board(key, token, board_id, list_id)
        return cards[0] if cards else {}

    def _trello_attachment_is_image(self, attachment: Dict[str, Any]) -> bool:
        name = str(attachment.get("name") or "").lower()
        mime = str(attachment.get("mimeType") or "").lower()
        return mime.startswith("image/") or Path(name).suffix.lower() in {".jpg", ".jpeg", ".png", ".webp", ".gif"}

    def _trello_attachment_order_key(self, attachment: Dict[str, Any], index: int = 0) -> tuple[int, float, int]:
        parsed = _parse_iso_datetime(str(attachment.get("date") or ""))
        if parsed is None:
            return (1, 0.0, index)
        return (0, parsed.timestamp(), index)

    def _sort_trello_attachments_by_date(
        self,
        attachments: List[Dict[str, Any]],
        *,
        newest_first: bool = False,
    ) -> List[Dict[str, Any]]:
        indexed = list(enumerate(attachments))
        sorted_items = sorted(indexed, key=lambda pair: self._trello_attachment_order_key(pair[1], pair[0]))
        if newest_first:
            dated = [pair for pair in sorted_items if self._trello_attachment_order_key(pair[1], pair[0])[0] == 0]
            undated = [pair for pair in sorted_items if self._trello_attachment_order_key(pair[1], pair[0])[0] != 0]
            sorted_items = list(reversed(dated)) + undated
        return [item for _index, item in sorted_items]

    def _trello_attachment_is_flow_output(self, attachment: Dict[str, Any]) -> bool:
        name = str(attachment.get("name") or "").strip().lower()
        stem = Path(name).stem.lower()
        return (
            name.startswith("flow-")
            or name.startswith("flow_")
            or stem.startswith("flow-")
            or stem.startswith("flow_")
        )

    def _trello_generated_series_prefix(self, attachment: Dict[str, Any]) -> str:
        stem = Path(str(attachment.get("name") or "")).stem.strip().lower()
        if not stem:
            return ""
        normalized = re.sub(r"[\s-]+", "_", stem).strip("_")
        match = re.match(r"^(.+?)_(\d{1,3})$", normalized)
        if not match:
            return ""
        prefix = match.group(1).strip("_")
        if len(prefix) < 5 or not re.search(r"[a-z]", prefix):
            return ""
        generic_prefixes = {
            "anh",
            "back",
            "front",
            "image",
            "img",
            "photo",
            "reference",
            "ref",
            "side",
            "source",
        }
        if prefix in generic_prefixes:
            return ""
        tokens = [token for token in re.split(r"[_]+", prefix) if token]
        code_like_tokens = [
            token
            for token in tokens
            if token.isdigit() or re.fullmatch(r"[a-z]\d{1,4}", token)
        ]
        if len(code_like_tokens) >= 2:
            return ""
        return prefix

    def _trello_source_and_flow_output_attachments(
        self,
        image_attachments: List[Dict[str, Any]],
    ) -> tuple[List[Dict[str, Any]], List[Dict[str, Any]]]:
        images = [
            item
            for item in image_attachments
            if isinstance(item, dict) and self._trello_attachment_is_image(item)
        ]
        if not images:
            return [], []
        series_counts: Dict[str, int] = {}
        for item in images:
            prefix = self._trello_generated_series_prefix(item)
            if prefix:
                series_counts[prefix] = series_counts.get(prefix, 0) + 1
        has_plain_source_candidate = any(
            not self._trello_attachment_is_flow_output(item)
            and not self._trello_generated_series_prefix(item)
            for item in images
        )

        source_attachments: List[Dict[str, Any]] = []
        flow_outputs: List[Dict[str, Any]] = []
        for item in images:
            series_prefix = self._trello_generated_series_prefix(item)
            is_generated_series = bool(
                series_prefix
                and (
                    series_counts.get(series_prefix, 0) >= 2
                    or has_plain_source_candidate
                )
            )
            if self._trello_attachment_is_flow_output(item) or is_generated_series:
                flow_outputs.append(item)
            else:
                source_attachments.append(item)

        source_attachments = self._sort_trello_attachments_by_date(source_attachments)
        flow_outputs = self._sort_trello_attachments_by_date(flow_outputs)
        return source_attachments, flow_outputs

    def _trello_download_attachment_bytes(
        self,
        key: str,
        token: str,
        card_id: str,
        attachment: Dict[str, Any],
    ) -> tuple[bytes, str]:
        attachment_id = str(attachment.get("id") or "").strip()
        name = str(attachment.get("name") or "image.jpg").strip() or "image.jpg"
        mime = str(attachment.get("mimeType") or mimetypes.guess_type(name)[0] or "image/jpeg")
        if attachment_id:
            path = (
                f"cards/{quote(card_id, safe='')}/attachments/"
                f"{quote(attachment_id, safe='')}/download/{quote(name)}"
            )
            request = Request(self._trello_endpoint(path, key, token), method="GET")
            try:
                with urlopen(request, timeout=self.TRELLO_TIMEOUT_S) as response:
                    return response.read(), response.headers.get_content_type() if response.headers else mime
            except Exception:
                pass
        url = str(attachment.get("url") or "").strip()
        if not url:
            raise RuntimeError(f"Attachment Trello {name} không có URL để tải.")
        return self._read_remote_file(url)

    def _trello_request_json(
        self,
        path: str,
        key: str,
        token: str,
        *,
        fields: Dict[str, Any] | None = None,
        data: bytes | None = None,
        headers: Dict[str, str] | None = None,
        timeout_s: float | None = None,
    ) -> Any:
        payload = data
        request_headers = {"Accept": "application/json", **(headers or {})}
        if payload is None:
            payload = urlencode({k: v for k, v in (fields or {}).items() if str(v) != ""}).encode("utf-8")
            request_headers["Content-Type"] = "application/x-www-form-urlencoded"

        request = Request(
            self._trello_endpoint(path, key, token),
            data=payload,
            headers=request_headers,
            method="POST",
        )
        try:
            with urlopen(request, timeout=float(timeout_s or self.TRELLO_TIMEOUT_S)) as response:
                raw_payload = response.read().decode("utf-8", errors="replace")
                return json.loads(raw_payload) if raw_payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            detail = self._redact_trello_secret(detail or exc.reason, key, token)
            raise RuntimeError(f"Trello API lỗi {exc.code}: {detail}") from exc
        except URLError as exc:
            raise RuntimeError(self._redact_trello_secret(exc.reason or exc, key, token)) from exc

    def _trello_put_json(self, path: str, key: str, token: str, fields: Dict[str, Any] | None = None) -> Any:
        payload = urlencode({k: v for k, v in (fields or {}).items() if str(v) != ""}).encode("utf-8")
        request = Request(
            self._trello_endpoint(path, key, token),
            data=payload,
            headers={"Accept": "application/json", "Content-Type": "application/x-www-form-urlencoded"},
            method="PUT",
        )
        try:
            with urlopen(request, timeout=self.TRELLO_TIMEOUT_S) as response:
                raw_payload = response.read().decode("utf-8", errors="replace")
                return json.loads(raw_payload) if raw_payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            detail = self._redact_trello_secret(detail or exc.reason, key, token)
            raise RuntimeError(f"Trello API lá»—i {exc.code}: {detail}") from exc
        except URLError as exc:
            raise RuntimeError(self._redact_trello_secret(exc.reason or exc, key, token)) from exc

    def _trello_delete_json(self, path: str, key: str, token: str) -> Any:
        request = Request(
            self._trello_endpoint(path, key, token),
            headers={"Accept": "application/json"},
            method="DELETE",
        )
        try:
            with urlopen(request, timeout=self.TRELLO_TIMEOUT_S) as response:
                raw_payload = response.read().decode("utf-8", errors="replace")
                return json.loads(raw_payload) if raw_payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            detail = self._redact_trello_secret(detail or exc.reason, key, token)
            raise RuntimeError(f"Trello API lỗi {exc.code}: {detail}") from exc
        except URLError as exc:
            raise RuntimeError(self._redact_trello_secret(exc.reason or exc, key, token)) from exc

    def _trello_delete_attachment(self, key: str, token: str, card_id: str, attachment_id: str) -> Any:
        return self._trello_delete_json(
            f"cards/{quote(card_id, safe='')}/attachments/{quote(attachment_id, safe='')}",
            key,
            token,
        )

    def _trello_create_card(self, key: str, token: str, list_id: str, name: str, description: str) -> Dict[str, Any]:
        payload = self._trello_request_json(
            "cards",
            key,
            token,
            fields={
                "idList": list_id,
                "name": name,
                "desc": description,
                "pos": "top",
            },
        )
        return payload if isinstance(payload, dict) else {}

    def _trello_move_card_to_list(self, key: str, token: str, card_id: str, list_id: str) -> Dict[str, Any]:
        payload = self._trello_put_json(
            f"cards/{quote(card_id, safe='')}",
            key,
            token,
            fields={"idList": list_id, "pos": "top"},
        )
        return payload if isinstance(payload, dict) else {}

    def _trello_add_label_to_card(self, key: str, token: str, card_id: str, label_id: str) -> Dict[str, Any]:
        try:
            payload = self._trello_request_json(
                f"cards/{quote(card_id, safe='')}/idLabels",
                key,
                token,
                fields={"value": label_id},
            )
        except RuntimeError as exc:
            # Trello returns 400 "label is already on the card" when we re-tag a card.
            # Treat that as success so retries stay idempotent.
            if "already on the card" in str(exc).lower():
                return {"already_present": True}
            raise
        if isinstance(payload, list):
            return {"idLabels": payload}
        return payload if isinstance(payload, dict) else {}

    def _trello_attach_url(
        self,
        key: str,
        token: str,
        card_id: str,
        artifact_url: str,
        name: str,
        set_cover: bool,
    ) -> Dict[str, Any]:
        payload = self._trello_request_json(
            f"cards/{quote(card_id, safe='')}/attachments",
            key,
            token,
            fields={
                "name": name,
                "url": artifact_url,
                "setCover": "true" if set_cover else "false",
            },
        )
        if isinstance(payload, list):
            return payload[0] if payload else {}
        return payload if isinstance(payload, dict) else {}

    def _trello_attach_file_from_url(
        self,
        key: str,
        token: str,
        card_id: str,
        artifact_url: str,
        name: str,
        mime_type: str,
        set_cover: bool,
    ) -> Dict[str, Any]:
        file_bytes, detected_mime = self._read_remote_file(artifact_url)
        mime = detected_mime or mime_type or mimetypes.guess_type(name)[0] or "image/jpeg"
        return self._trello_attach_file_bytes(
            key,
            token,
            card_id,
            file_bytes,
            mime,
            name,
            set_cover,
        )

    def _trello_attach_file_bytes(
        self,
        key: str,
        token: str,
        card_id: str,
        file_bytes: bytes,
        mime_type: str,
        name: str,
        set_cover: bool,
    ) -> Dict[str, Any]:
        mime = mime_type or mimetypes.guess_type(name)[0] or "image/jpeg"
        body, content_type = self._multipart_form_data(
            fields={
                "name": name,
                "mimeType": mime,
                "setCover": "true" if set_cover else "false",
            },
            file_field="file",
            file_name=name,
            file_mime=mime,
            file_bytes=file_bytes,
        )
        payload = self._trello_request_json(
            f"cards/{quote(card_id, safe='')}/attachments",
            key,
            token,
            data=body,
            headers={"Content-Type": content_type},
            timeout_s=self.TRELLO_UPLOAD_TIMEOUT_S,
        )
        if isinstance(payload, list):
            return payload[0] if payload else {}
        return payload if isinstance(payload, dict) else {}

    # ── Flow image upsampler (POST /v1/flow/upsampleImage) ──────────────────
    # Match Flow's current 2K image upsample request first. Local resize is
    # opt-in only because it increases pixel count without adding real detail.

    def _test_jpeg_bytes(self, side: int, *, seed: int = 0) -> bytes:
        """Deterministic synthetic JPEG (gradient + stripes keyed by seed) for tests and probes."""
        from PIL import Image, ImageDraw

        image = Image.new("RGB", (side, side), ((seed * 53) % 255, (seed * 97) % 255, (seed * 151) % 255))
        draw = ImageDraw.Draw(image)
        band = side // 3
        for index in range(3):
            shade = (index * 70 + seed * 37) % 255
            draw.rectangle((index * band, 0, (index + 1) * band, side // 2), fill=(shade, 255 - shade, (shade * 2) % 255))
        cx, cy = side * (1 + seed % 4) // 6, side * (1 + (seed // 2) % 4) // 6
        radius = side // (3 + seed % 3)
        draw.ellipse((cx - radius, cy - radius, cx + radius, cy + radius), fill=((seed * 31) % 255, 40, 200))
        buffer = io.BytesIO()
        image.save(buffer, format="JPEG", quality=90)
        return buffer.getvalue()

    def _flow_ui_upscale_enabled(self) -> bool:
        """Download "2K Upscaled" from Flow's image editor for each generated image (user-approved 2026-09-09)."""
        value = os.getenv("FLOW_UI_UPSCALE_2K_ENABLED", "").strip().lower()
        if not value:
            return True
        return value not in {"0", "false", "no", "off"}

    FLOW_UI_CONTROLS_JS = """
        /* flow-ui-controls */
        () => [...document.querySelectorAll('button, [role="button"], [role="menuitem"], [role="menuitemradio"], [role="option"], mat-option, li')]
          .filter((el) => { const r = el.getBoundingClientRect(); const s = getComputedStyle(el);
            return r.width >= 14 && r.height >= 14 && s.display !== 'none' && s.visibility !== 'hidden' && r.bottom > 0 && r.top < innerHeight; })
          .map((el) => { const r = el.getBoundingClientRect();
            return { label: [el.textContent || '', el.getAttribute('aria-label') || '', el.getAttribute('title') || ''].join(' | ').replace(/\\s+/g, ' ').trim().slice(0, 100),
                     x: Math.round(r.left + r.width / 2), y: Math.round(r.top + r.height / 2) }; })
          .filter((it) => it.label)
    """
    FLOW_UI_TILE_SELECTOR = 'img[alt*="Tile displaying"]'
    FLOW_UI_2K_GIVE_UP_FAILURES = 3
    FLOW_UI_2K_DUPLICATE_DISTANCE = 0.005  # two downloads closer than this are the same image
    FLOW_UI_TILE_SRC_JS = """
        /* flow-ui-tile-src */
        (index) => {
          const img = document.querySelectorAll('img[alt*="Tile displaying"]')[index];
          return img ? (img.currentSrc || img.src || '') : '';
        }
    """
    FLOW_UI_TILE_CENTER_JS = """
        /* flow-ui-tile-center */
        (index) => {
          const tiles = [...document.querySelectorAll('img[alt*="Tile displaying"]')];
          const img = tiles[index];
          if (!img) return null;
          img.scrollIntoView({ block: 'center', inline: 'nearest' });
          const r = img.getBoundingClientRect();
          return { x: r.left + r.width / 2, y: r.top + r.height / 2, w: r.width, h: r.height, total: tiles.length };
        }
    """
    UI_2K_THUMB_SIZE = 24
    UI_2K_MATCH_MAX_DISTANCE = 0.04
    UI_2K_MATCH_MIN_MARGIN = 0.03
    # A true pair usually sits at 0.001-0.015, "same scene, other design" at ~0.10. Flow's upscaler sometimes
    # redraws details (Crown card 2026-09-11: 0.056), so a candidate that is clearly the best is still accepted.
    UI_2K_MATCH_LOOSE_DISTANCE = 0.08
    UI_2K_MATCH_LOOSE_MIN_MARGIN = 0.05

    def _image_thumb_signature(self, image_bytes: bytes) -> List[float]:
        """Tiny grayscale thumbnail used to pair a 1K artifact with its 2K download."""
        from PIL import Image

        with Image.open(io.BytesIO(image_bytes)) as image:
            thumb = image.convert("RGB").resize((self.UI_2K_THUMB_SIZE, self.UI_2K_THUMB_SIZE), Image.BILINEAR)
            return [channel / 255.0 for pixel in thumb.getdata() for channel in pixel]

    def _match_ui_upscaled_candidate(self, source_bytes: bytes, candidates: List[Dict[str, Any]]) -> Dict[str, Any] | None:
        """Return the unused candidate whose thumbnail is closest to the source, or None when nothing is close."""
        try:
            source_sig = self._image_thumb_signature(source_bytes)
        except Exception:
            return None
        best: Dict[str, Any] | None = None
        best_distance = 1.0
        second_distance = 1.0
        for candidate in candidates:
            if not isinstance(candidate, dict) or candidate.get("used"):
                continue
            sig = candidate.get("sig")
            if not sig:
                try:
                    sig = self._image_thumb_signature(bytes(candidate.get("bytes") or b""))
                    candidate["sig"] = sig
                except Exception:
                    continue
            if len(sig) != len(source_sig):
                continue
            distance = sum(abs(a - b) for a, b in zip(source_sig, sig)) / len(source_sig)
            if distance < best_distance:
                second_distance = best_distance
                best_distance = distance
                best = candidate
            elif distance < second_distance:
                second_distance = distance
        if best is None:
            return None
        margin = second_distance - best_distance
        if best_distance <= self.UI_2K_MATCH_MAX_DISTANCE and margin >= self.UI_2K_MATCH_MIN_MARGIN:
            return best
        if best_distance <= self.UI_2K_MATCH_LOOSE_DISTANCE and margin >= self.UI_2K_MATCH_LOOSE_MIN_MARGIN:
            return best  # not a textbook pair, but nothing else comes close
        return None  # too far, or two candidates look alike: refuse rather than risk uploading the wrong one

    async def _download_flow_ui_upscaled_set(self, client: Any, count: int, *, job_id: str = "") -> List[Dict[str, Any]]:
        """Open the newest grid images in Flow's editor and download their "2K Upscaled" versions.

        Returns [{"bytes", "name", "sig"}]; the loop stops after ``count`` downloads or at the first
        source upload (Trello attachments are named trello-*). Any per-image failure is logged and skipped.
        """
        wanted = max(1, min(int(count or 1), self.FLOW_AGENT_MAX_OUTPUT_COUNT + 2))
        page = await client._bm.page()
        project_id = str(getattr(client, "project_id", "") or "").strip()
        if project_id:
            # Always reload: the shared tab can hold a stale grid (an older card's set on top), and the
            # freshly loaded project lists media newest-first.
            await page.goto(self._project_url(project_id), wait_until="domcontentloaded", timeout=60_000)
            await asyncio.sleep(5.0)
        await self._wait_for_flow_app_ready(page, timeout_s=30.0)
        await self._dismiss_flow_top_banner(page)
        try:
            await page.keyboard.press("Escape")
        except Exception:
            pass
        await asyncio.sleep(1.0)
        results: List[Dict[str, Any]] = []
        failures = 0
        tiles = page.locator(self.FLOW_UI_TILE_SELECTOR)
        try:
            available = int(await tiles.count())
        except Exception:
            available = 0
        if job_id:
            await self.store.append_log(job_id, f"Dang tai ban 2K tu giao dien Flow cho {wanted} anh (grid co {available} anh).")
        download_root = self._download_root()
        download_root.mkdir(parents=True, exist_ok=True)
        # The grid is virtualised and re-mounts after the editor closes, so "tile index N" is not a stable
        # identity: remember the thumbnail src of every tile handled and skip repeats (2026-09-11).
        seen_srcs: set[str] = set()
        duplicates = 0
        # Ảnh nguồn (trello-*/erp-*) do các lượt Agent hỏng để lại nằm trên cùng lưới, và Flow tải thẳng
        # ảnh upload khi bấm Download (không có menu 2K). Chúng không phải lỗi: bỏ qua và nới thêm ô để
        # tới được ảnh tạo ra (ERP 2026-09-12: ba acc trả 0/12 vì 3 ô đầu đều là upload của lượt hỏng).
        skipped_uploads = 0
        upload_name_re = re.compile(r"^(erp|trello)-[\w.-]*\.(jpe?g|png|webp)", re.I)
        tile_index = -1
        while True:
            tile_index += 1
            if tile_index >= min(max(available, 0), wanted + 8 + skipped_uploads):
                break
            if len(results) >= wanted or failures >= self.FLOW_UI_2K_GIVE_UP_FAILURES:
                break
            try:
                tile_src = await page.evaluate(self.FLOW_UI_TILE_SRC_JS, tile_index)
                tile_src = tile_src if isinstance(tile_src, str) else ""
                if tile_src and tile_src in seen_srcs:
                    duplicates += 1
                    continue
                if tile_src:
                    seen_srcs.add(tile_src)
                center = await page.evaluate(self.FLOW_UI_TILE_CENTER_JS, tile_index)
                if not isinstance(center, dict) or float(center.get("w") or 0) < 40 or float(center.get("h") or 0) < 40:
                    raise RuntimeError(f"grid tile {tile_index + 1} is not rendered ({center})")
                await asyncio.sleep(0.6)
                center = await page.evaluate(self.FLOW_UI_TILE_CENTER_JS, tile_index) or center
                await page.mouse.click(float(center["x"]), float(center["y"]))
                await asyncio.sleep(3.0)
                controls = await page.evaluate(self.FLOW_UI_CONTROLS_JS)
                controls = controls if isinstance(controls, list) else []
                download_btn = next((it for it in controls if re.search(r"download media|^download\b", str(it.get("label") or ""), re.I)), None)
                if not download_btn:
                    # The first click right after a generation often only focuses the tile: click once more.
                    await asyncio.sleep(1.5)
                    center = await page.evaluate(self.FLOW_UI_TILE_CENTER_JS, tile_index) or center
                    await page.mouse.click(float(center["x"]), float(center["y"]))
                    await asyncio.sleep(3.0)
                    controls = await page.evaluate(self.FLOW_UI_CONTROLS_JS)
                    controls = controls if isinstance(controls, list) else []
                    download_btn = next((it for it in controls if re.search(r"download media|^download\b", str(it.get("label") or ""), re.I)), None)
                if not download_btn:
                    raise RuntimeError("no Download control in the image editor")
                # Ảnh upload thì Flow tải thẳng file gốc ngay khi bấm Download (không có menu): bắt lấy
                # download ấy để nhận ra ô upload.
                direct = None
                try:
                    async with page.expect_download(timeout=2500) as direct_info:
                        await page.mouse.click(float(download_btn["x"]), float(download_btn["y"]))
                    direct = await direct_info.value
                except Exception:
                    direct = None
                direct_name = str(getattr(direct, "suggested_filename", "") or "") if direct is not None else ""
                if direct is not None and not upload_name_re.search(direct_name):
                    # Not a source upload (e.g. a download that was still settling): ignore it, read the menu.
                    direct = None
                if direct is not None:
                    try:
                        await direct.cancel()
                    except Exception:
                        pass
                    skipped_uploads += 1
                    if job_id and skipped_uploads <= 2:
                        await self.store.append_log(
                            job_id,
                            f"O thu {tile_index + 1} tai thang file ({direct_name or 'khong ten'}): anh nguon upload, bo qua, khong tinh loi.",
                        )
                    await self._flow_ui_leave_image_editor(page)
                    continue
                await asyncio.sleep(0.5)
                menu = await page.evaluate(self.FLOW_UI_CONTROLS_JS)
                menu = menu if isinstance(menu, list) else []
                option = next((it for it in menu if re.search(r"\b2k\b", str(it.get("label") or ""), re.I) and re.search(r"upscal", str(it.get("label") or ""), re.I)), None)
                if not option:
                    # uploads and non-generated media only offer the original size: we are past this card's outputs
                    if job_id:
                        labels = [str(it.get("label") or "").strip() for it in menu if str(it.get("label") or "").strip()]
                        shot = await self._capture_flow_agent_debug_screenshot(page, "ui2k-menu") if failures == 0 else ""
                        await self.store.append_log(
                            job_id,
                            f"Menu tai anh thu {tile_index + 1} khong co muc 2K Upscaled; menu: {labels[:12]} {shot}",
                        )
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.5)
                    await self._flow_ui_leave_image_editor(page)
                    if any(re.search(r"original size", str(it.get("label") or ""), re.I) for it in menu):
                        break
                    failures += 1
                    continue
                async with page.expect_download(timeout=120_000) as download_info:
                    await page.mouse.click(float(option["x"]), float(option["y"]))
                download = await download_info.value
                file_name = str(getattr(download, "suggested_filename", "") or "")
                if file_name.lower().startswith("trello-"):
                    await self._flow_ui_leave_image_editor(page)
                    break
                destination = download_root / f"ui2k-{(job_id or 'job')[:8]}-{len(results) + 1}.jpeg"
                await download.save_as(str(destination))
                data = await asyncio.to_thread(destination.read_bytes)
                size = await asyncio.to_thread(self._image_size_from_bytes, data)
                if data and size and max(size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
                    try:
                        sig = await asyncio.to_thread(self._image_thumb_signature, data)
                    except Exception:
                        sig = None
                    is_duplicate = bool(sig) and any(
                        item.get("sig")
                        and sum(abs(a - b) for a, b in zip(sig, item["sig"])) / len(sig) < self.FLOW_UI_2K_DUPLICATE_DISTANCE
                        for item in results
                    )
                    if is_duplicate:
                        duplicates += 1
                    else:
                        results.append({"bytes": data, "name": file_name, "path": str(destination), "size": size, "sig": sig})
                else:
                    failures += 1
                    if job_id:
                        await self.store.append_log(
                            job_id,
                            f"Ban 2K tu Flow cho anh thu {tile_index + 1} tai ve nhung khong phai 2K ({file_name}, {size}); bo qua.",
                        )
                await self._flow_ui_leave_image_editor(page)
            except Exception as exc:
                failures += 1
                if job_id:
                    shot = await self._capture_flow_agent_debug_screenshot(page, "ui2k-fail") if failures == 1 else ""
                    await self.store.append_log(
                        job_id,
                        f"Ban 2K tu Flow cho anh thu {tile_index + 1} khong lay duoc: {' '.join(str(exc).split())[:300]} {shot}",
                    )
                try:
                    await page.keyboard.press("Escape")
                    await asyncio.sleep(0.5)
                    await self._flow_ui_leave_image_editor(page)
                except Exception:
                    pass
        if job_id:
            dup_note = f"; bo qua {duplicates} tile trung" if duplicates else ""
            await self.store.append_log(job_id, f"Da tai {len(results)}/{wanted} ban 2K tu giao dien Flow{dup_note}.")
        if failures >= self.FLOW_UI_2K_GIVE_UP_FAILURES and len(results) < wanted:
            raise FlowUiUpscaleUnavailableError(
                f"Flow khong tra ban 2K ({failures} anh khong tai duoc, moi {len(results)}/{wanted} anh co 2K); "
                "app giu card, khong upload anh 1K. Anh da tao van nam trong project Flow de lay 2K sau."
            )
        return results

    async def _flow_ui_leave_image_editor(self, page: Any) -> None:
        try:
            controls = await page.evaluate(self.FLOW_UI_CONTROLS_JS)
        except Exception:
            controls = []
        back = next(
            (it for it in (controls if isinstance(controls, list) else []) if re.search(r"arrow_back|back button|^done\b", str(it.get("label") or ""), re.I)),
            None,
        )
        try:
            if back:
                await page.mouse.click(float(back["x"]), float(back["y"]))
            else:
                await page.keyboard.press("Escape")
        except Exception:
            pass
        await asyncio.sleep(2.0)

    def _flow_upsample_api_enabled(self) -> bool:
        value = os.getenv("FLOW_UPSAMPLE_API_ENABLED", "").strip().lower()
        if not value:
            return True
        return value not in {"0", "false", "no", "off"}

    def _trello_fake_2k_resize_enabled(self) -> bool:
        value = os.getenv("TRELLO_FAKE_2K_RESIZE_ENABLED", "").strip().lower()
        return value in {"1", "true", "yes", "on"}

    def _flow_upsample_payloads(
        self,
        media_id: str,
        *,
        client_context: Dict[str, Any] | None = None,
    ) -> List[Dict[str, Any]]:
        payload: Dict[str, Any] = {
            "mediaId": media_id,
            "targetResolution": "UPSAMPLE_IMAGE_RESOLUTION_2K",
        }
        if client_context:
            payload["clientContext"] = client_context
        return [payload]

    def _flow_media_redirect_url(self, media_name: str) -> str:
        media = str(media_name or "").strip()
        if not media:
            return ""
        return f"https://labs.google/fx/api/trpc/media.getMediaUrlRedirect?name={quote(media)}"

    def _normal_flow_media_name(self, value: Any) -> str:
        raw = str(value or "").strip()
        if not raw or raw.startswith(("http://", "https://")):
            return ""
        match = re.search(
            r"[0-9a-fA-F]{8}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{4}-[0-9a-fA-F]{12}",
            raw,
        )
        return match.group(0) if match else ""

    def _extract_flow_media_names(self, payload: Any) -> List[str]:
        names: List[str] = []
        seen: set[str] = set()

        def visit(value: Any, parent_key: str = "") -> None:
            if isinstance(value, dict):
                for key, child in value.items():
                    key_text = str(key or "")
                    if key_text in {"mediaId", "mediaName", "name", "primaryMediaId"}:
                        if isinstance(child, str):
                            media_name = self._normal_flow_media_name(child)
                            if media_name and media_name not in seen:
                                seen.add(media_name)
                                names.append(media_name)
                        elif isinstance(child, dict):
                            visit(child, key_text)
                            for nested_key in ("mediaName", "name"):
                                media_name = self._normal_flow_media_name(child.get(nested_key))
                                if media_name and media_name not in seen:
                                    seen.add(media_name)
                                    names.append(media_name)
                    else:
                        visit(child, key_text)
            elif isinstance(value, list):
                for item in value:
                    visit(item, parent_key)

        visit(payload)
        return names

    def _extract_image_urls(self, payload: Any) -> List[str]:
        urls: List[str] = []
        seen: set[str] = set()
        url_keys = {"fifeUrl", "downloadUrl", "imageUrl", "url", "fifeUri", "uri"}

        def visit(value: Any, parent_key: str = "") -> None:
            if isinstance(value, dict):
                for key, child in value.items():
                    key_text = str(key or "")
                    if key_text in url_keys and "thumb" not in key_text.lower() and isinstance(child, str):
                        url = child.strip()
                        if url.startswith("/"):
                            url = f"https://labs.google{url}"
                        if url.startswith(("http://", "https://")) and url not in seen:
                            seen.add(url)
                            urls.append(url)
                    else:
                        visit(child, key_text)
            elif isinstance(value, list):
                for item in value:
                    visit(item, parent_key)

        visit(payload)
        return urls

    async def _download_flow_image_bytes(self, client: Any, url: str) -> tuple[bytes, str]:
        target = str(url or "").strip()
        if not target:
            return b"", ""
        try:
            response = await client._bm.context.request.get(target)
            status = int(getattr(response, "status", 0) or 0)
            if status and status != 200:
                log.warning("Flow 2K image download failed HTTP %s: %s", status, target)
                return b"", ""
            body = await response.body()
            headers = getattr(response, "headers", {}) or {}
            mime = str(headers.get("content-type") or "").split(";", 1)[0].strip()
            return bytes(body or b""), mime or mimetypes.guess_type(target)[0] or "image/jpeg"
        except Exception as exc:
            log.warning("Flow 2K image download failed: %s", self._flow_error_detail(exc))
            return b"", ""

    async def _flow_upsample_response_bytes(
        self,
        client: Any,
        payload: Any,
        *,
        fallback_media_id: str = "",
    ) -> tuple[bytes, str]:
        import base64 as _b64

        encoded_out = self._extract_encoded_image(payload)
        if encoded_out:
            try:
                return _b64.b64decode(encoded_out), "image/jpeg"
            except Exception as exc:
                log.warning("flow/upsampleImage: base64 decode failed: %s", exc)

        for url in self._extract_image_urls(payload):
            downloaded, mime = await self._download_flow_image_bytes(client, url)
            if downloaded:
                return downloaded, mime

        media_names = self._extract_flow_media_names(payload)
        fallback = self._normal_flow_media_name(fallback_media_id)
        if fallback and fallback not in media_names:
            media_names.append(fallback)
        for media_name in media_names:
            downloaded, mime = await self._download_flow_image_bytes(
                client,
                self._flow_media_redirect_url(media_name),
            )
            if downloaded:
                return downloaded, mime

        return b"", ""

    async def _flow_ui_click_text(
        self,
        page: Any,
        *,
        contains: tuple[str, ...] = (),
        startswith: tuple[str, ...] = (),
    ) -> bool:
        rect = await page.evaluate(
            """
            ({ contains, startswith }) => {
              const normalize = (value) => (value || '')
                .normalize('NFD')
                .replace(/[\\u0300-\\u036f]/g, '')
                .toLowerCase()
                .replace(/\\s+/g, ' ')
                .trim();
              const containsNeedles = contains.map(normalize).filter(Boolean);
              const startsWithNeedles = startswith.map(normalize).filter(Boolean);
              const visible = (el) => {
                if (!el || !(el instanceof Element)) return false;
                const style = window.getComputedStyle(el);
                const rect = el.getBoundingClientRect();
                return style.display !== 'none'
                  && style.visibility !== 'hidden'
                  && style.opacity !== '0'
                  && rect.width > 0
                  && rect.height > 0
                  && rect.bottom > 0
                  && rect.right > 0
                  && rect.top < window.innerHeight
                  && rect.left < window.innerWidth;
              };
              const nodes = [...document.querySelectorAll('button, [role="menuitem"], [role="option"], [role="button"]')];
              for (const node of nodes) {
                if (!visible(node)) continue;
                const text = normalize(node.innerText || node.textContent || node.getAttribute('aria-label') || '');
                if (!text) continue;
                const matched = containsNeedles.some((needle) => text.includes(needle))
                  || startsWithNeedles.some((needle) => text.startsWith(needle));
                if (!matched) continue;
                const rect = node.getBoundingClientRect();
                return { x: rect.left + rect.width / 2, y: rect.top + rect.height / 2 };
              }
              return null;
            }
            """,
            {"contains": list(contains), "startswith": list(startswith)},
        )
        if not isinstance(rect, dict):
            return False
        await page.mouse.click(float(rect["x"]), float(rect["y"]))
        return True

    async def _flow_ui_image_rect_for_media(self, page: Any, media_id: str) -> Dict[str, float]:
        media = self._normal_flow_media_name(media_id)
        if not media:
            return {}
        deadline = time.monotonic() + 45.0
        last_rect: Dict[str, float] = {}
        while time.monotonic() < deadline:
            rect = await page.evaluate(
                """
                (mediaId) => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const style = window.getComputedStyle(el);
                    const rect = el.getBoundingClientRect();
                    return style.display !== 'none'
                      && style.visibility !== 'hidden'
                      && rect.width >= 80
                      && rect.height >= 80
                      && rect.bottom > 0
                      && rect.right > 0
                      && rect.top < window.innerHeight
                      && rect.left < window.innerWidth;
                  };
                  const all = [...document.querySelectorAll('img[src], img[srcset]')]
                    .filter((img) => {
                      const src = img.currentSrc || img.src || img.getAttribute('src') || img.getAttribute('srcset') || '';
                      return src.includes(`name=${mediaId}`) || src.includes(`name%3D${mediaId}`);
                    });
                  if (!all.length) return null;
                  const scored = all
                    .filter(visible)
                    .map((img) => {
                      const rect = img.getBoundingClientRect();
                      return { img, area: rect.width * rect.height };
                    })
                    .sort((a, b) => b.area - a.area);
                  const chosen = scored.length ? scored[0].img : all[0];
                  chosen.scrollIntoView({ block: 'center', inline: 'center' });
                  const rect = chosen.getBoundingClientRect();
                  return {
                    x: rect.left,
                    y: rect.top,
                    width: rect.width,
                    height: rect.height,
                    visible: visible(chosen),
                  };
                }
                """,
                media,
            )
            if isinstance(rect, dict):
                last_rect = {
                    "x": float(rect.get("x") or 0),
                    "y": float(rect.get("y") or 0),
                    "width": float(rect.get("width") or 0),
                    "height": float(rect.get("height") or 0),
                }
                if rect.get("visible") and last_rect["width"] > 0 and last_rect["height"] > 0:
                    return last_rect
            await asyncio.sleep(1.0)
        return last_rect

    async def _upsample_image_via_flow_ui_download(self, client: Any, media_id: str) -> bytes:
        media = self._normal_flow_media_name(media_id)
        if not media:
            return b""
        page = await client._bm.page()
        project_id = str(getattr(client._api, "project_id", "") or "").strip()
        target_url = self._project_url(project_id) if project_id else str(getattr(client, "_project_url", "") or "")
        if target_url and target_url not in str(page.url or ""):
            await page.goto(target_url, wait_until="domcontentloaded", timeout=60_000)
            await asyncio.sleep(2.0)
        try:
            await page.wait_for_load_state("networkidle", timeout=30_000)
        except Exception:
            pass

        rect = await self._flow_ui_image_rect_for_media(page, media)
        if not rect:
            log.warning("Flow UI 2K download skipped: media tile not found for %s", media)
            return b""

        menu_x = rect["x"] + rect["width"] - 28
        menu_y = rect["y"] + 28
        await page.mouse.move(menu_x, menu_y)
        await asyncio.sleep(0.4)
        await page.mouse.click(menu_x, menu_y)
        await asyncio.sleep(0.5)
        if not await self._flow_ui_click_text(page, contains=("Tải xuống", "Tai xuong", "Download")):
            log.warning("Flow UI 2K download skipped: download menu item not found")
            return b""
        await asyncio.sleep(0.5)

        target_dir = DOWNLOADS_DIR / "_flow_2k_downloads"
        target_dir.mkdir(parents=True, exist_ok=True)
        target_path = target_dir / f"{media}-{uuid.uuid4().hex}.jpg"
        try:
            async with page.expect_download(timeout=120_000) as download_info:
                clicked = await self._flow_ui_click_text(page, startswith=("2K",))
                if not clicked:
                    raise RuntimeError("2K download option not found")
            download = await download_info.value
            await download.save_as(str(target_path))
            return await asyncio.to_thread(target_path.read_bytes)
        except Exception as exc:
            log.warning("Flow UI 2K download failed: %s", self._flow_error_detail(exc))
            return b""

    async def _upsample_image_via_flow(
        self,
        client: Any,
        jpeg_bytes: bytes,
        *,
        media_generation_id: str = "",
        workflow_id: str = "",
        prompt: str = "",
    ) -> bytes:
        """Call POST /v1/flow/upsampleImage and return the upscaled JPEG bytes.

        Returns the original bytes on any failure so the caller can still
        upload the source image.
        """
        if not jpeg_bytes:
            return jpeg_bytes
        media_id = self._normal_flow_media_name(media_generation_id)
        if not media_id:
            log.warning("flow/upsampleImage skipped: missing Flow media id")
            return jpeg_bytes
        try:
            client_context = await client._api._client_context()
        except Exception as exc:
            log.warning("flow/upsampleImage client context failed: %s", self._flow_error_detail(exc))
            client_context = {}

        payloads = self._flow_upsample_payloads(media_id, client_context=client_context)
        for attempt, payload in enumerate(payloads, start=1):
            try:
                data = await client._api._fetch(
                    "POST",
                    "flow/upsampleImage",
                    payload,
                )
            except Exception as exc:
                log.warning(
                    "flow/upsampleImage attempt %s media=%s failed: %s",
                    attempt,
                    media_id,
                    self._flow_error_detail(exc),
                )
                continue
            decoded, _mime = await self._flow_upsample_response_bytes(
                client,
                data,
                fallback_media_id=media_id,
            )
            if not decoded:
                log.warning(
                    "flow/upsampleImage: response missing image bytes/url/media field (keys=%s)",
                    list(data.keys()) if isinstance(data, dict) else type(data).__name__,
                )
                continue
            if decoded == jpeg_bytes:
                log.warning(
                    "flow/upsampleImage attempt %s media=%s returned original bytes",
                    attempt,
                    media_id,
                )
                continue
            decoded_size = self._image_size_from_bytes(decoded)
            if decoded_size and max(decoded_size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
                return decoded
            log.warning(
                "flow/upsampleImage attempt %s media=%s returned non-2K bytes (%sx%s)",
                attempt,
                media_id,
                decoded_size[0] if decoded_size else 0,
                decoded_size[1] if decoded_size else 0,
            )
        ui_downloaded = await self._upsample_image_via_flow_ui_download(client, media_id)
        if ui_downloaded and ui_downloaded != jpeg_bytes:
            ui_size = self._image_size_from_bytes(ui_downloaded)
            if ui_size and max(ui_size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
                return ui_downloaded
            log.warning(
                "Flow UI 2K download returned non-2K bytes (%sx%s)",
                ui_size[0] if ui_size else 0,
                ui_size[1] if ui_size else 0,
            )
        return jpeg_bytes

    def _extract_encoded_image(self, payload: Any) -> str:
        """Recursively find the first encoded image string in a JSON tree."""
        return self._extract_image_bytes_field(payload, {"encodedImage", "rawBytes", "imageBytes"})

    def _extract_image_bytes_field(self, payload: Any, field_names: set[str]) -> str:
        if isinstance(payload, dict):
            for key in field_names:
                candidate = payload.get(key)
                if isinstance(candidate, str) and candidate:
                    return candidate
            for value in payload.values():
                found = self._extract_image_bytes_field(value, field_names)
                if found:
                    return found
        elif isinstance(payload, list):
            for item in payload:
                found = self._extract_image_bytes_field(item, field_names)
                if found:
                    return found
        return ""

    def _image_size_from_bytes(self, image_bytes: bytes) -> tuple[int, int]:
        if not image_bytes:
            return (0, 0)
        try:
            from PIL import Image, ImageOps
        except Exception:
            return (0, 0)

        try:
            with Image.open(io.BytesIO(image_bytes)) as opened:
                image = ImageOps.exif_transpose(opened)
                return tuple(int(part) for part in image.size)
        except Exception:
            return (0, 0)

    def _ensure_image_long_edge_2k(
        self,
        image_bytes: bytes,
        mime_type: str = "",
    ) -> tuple[bytes, str, bool, tuple[int, int], tuple[int, int]]:
        """Return JPEG bytes whose long edge is at least 2048px.

        This local pass only changes the pixel dimensions. It is kept as an
        explicit opt-in fallback for users who want 2048px files even when Flow
        does not return true 2K image detail.
        """
        if not image_bytes:
            return image_bytes, mime_type or "image/jpeg", False, (0, 0), (0, 0)
        try:
            from PIL import Image, ImageOps
        except Exception:
            return image_bytes, mime_type or "image/jpeg", False, (0, 0), (0, 0)

        try:
            with Image.open(io.BytesIO(image_bytes)) as opened:
                image = ImageOps.exif_transpose(opened)
                source_size = tuple(int(part) for part in image.size)
                long_edge = max(source_size) if source_size else 0
                if long_edge >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
                    return image_bytes, mime_type or Image.MIME.get(opened.format, "image/jpeg"), False, source_size, source_size

                scale = self.TRELLO_UPSCALE_LONG_EDGE_PX / max(1, long_edge)
                target_size = (
                    max(1, int(round(source_size[0] * scale))),
                    max(1, int(round(source_size[1] * scale))),
                )
                resampling = getattr(getattr(Image, "Resampling", Image), "LANCZOS", Image.BICUBIC)
                resized = image.resize(target_size, resampling)

                if resized.mode in {"RGBA", "LA"} or (resized.mode == "P" and "transparency" in resized.info):
                    rgba = resized.convert("RGBA")
                    background = Image.new("RGB", rgba.size, (255, 255, 255))
                    background.paste(rgba, mask=rgba.getchannel("A"))
                    output_image = background
                else:
                    output_image = resized.convert("RGB")

                output = io.BytesIO()
                output_image.save(output, format="JPEG", quality=95, subsampling=0, optimize=True)
                return output.getvalue(), "image/jpeg", True, source_size, target_size
        except Exception as exc:
            log.warning("local 2K image upscaling failed: %s", exc)
            return image_bytes, mime_type or "image/jpeg", False, (0, 0), (0, 0)

    async def _upsample_artifact_bytes(
        self,
        artifact: JobArtifact,
        artifact_url: str,
        ui_candidates: List[Dict[str, Any]] | None = None,
    ) -> ImageUpscaleResult:
        """Fetch an artifact and prepare 2K bytes for Trello upload.

        Flow's own 2K upsampler is tried first. Local resize is disabled by
        default because it creates a larger but still blurry file.
        """
        local_path = str(artifact.local_path or "").strip()
        source_bytes: bytes = b""
        source_mime = str(artifact.mime_type or "").strip()
        if local_path and Path(local_path).expanduser().is_file():
            try:
                source_bytes = Path(local_path).expanduser().read_bytes()
                if not source_mime:
                    source_mime = mimetypes.guess_type(local_path)[0] or "image/jpeg"
            except Exception:
                source_bytes = b""
        if not source_bytes:
            source_bytes, detected_mime = await asyncio.to_thread(
                self._read_remote_file, artifact_url
            )
            source_mime = source_mime or detected_mime or "image/jpeg"
        if not source_bytes:
            return ImageUpscaleResult()

        workflow_id = str(artifact.workflow_id or "").strip()
        media_generation_id = str(artifact.media_name or "").strip()
        source_size = await asyncio.to_thread(self._image_size_from_bytes, source_bytes)
        if source_size and max(source_size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
            return ImageUpscaleResult()

        # Flow's own editor offers "2K Upscaled" per generated image (free); the set is fetched once
        # per card and paired with this artifact by thumbnail similarity, never by position.
        if ui_candidates:
            matched = await asyncio.to_thread(self._match_ui_upscaled_candidate, source_bytes, ui_candidates)
            if matched is not None:
                matched_bytes = bytes(matched.get("bytes") or b"")
                matched_size = await asyncio.to_thread(self._image_size_from_bytes, matched_bytes)
                if matched_bytes and matched_size and max(matched_size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
                    matched["used"] = True
                    return ImageUpscaleResult(
                        bytes=matched_bytes,
                        mime_type="image/jpeg",
                        source="flow_2k",
                        source_size=source_size,
                        target_size=matched_size,
                        used_flow=True,
                    )

        async def _go(client: Any) -> bytes:
            return await self._upsample_image_via_flow(
                client,
                source_bytes,
                media_generation_id=media_generation_id,
                workflow_id=workflow_id,
            )

        flow_upscaled: bytes = b""
        if self._flow_upsample_api_enabled():
            try:
                flow_upscaled = await self._with_client(_go, workflow_id=workflow_id)
            except Exception as exc:
                log.warning("Flow 2K upscaling client failed: %s", self._flow_error_detail(exc))

        flow_changed = bool(flow_upscaled and flow_upscaled != source_bytes)
        candidate_bytes = flow_upscaled if flow_changed else source_bytes
        candidate_mime = "image/jpeg" if flow_changed else source_mime
        candidate_size = await asyncio.to_thread(self._image_size_from_bytes, candidate_bytes)
        if flow_changed and candidate_size and max(candidate_size) >= self.TRELLO_UPSCALE_LONG_EDGE_PX:
            return ImageUpscaleResult(
                bytes=flow_upscaled,
                mime_type="image/jpeg",
                source="flow_2k",
                source_size=source_size,
                target_size=candidate_size,
                used_flow=True,
            )

        if self._trello_fake_2k_resize_enabled():
            ensured, ensured_mime, changed, resize_source_size, resize_target_size = await asyncio.to_thread(
                self._ensure_image_long_edge_2k,
                candidate_bytes,
                candidate_mime,
            )
            if changed:
                log.info("Locally resized Trello image from %sx%s to %sx%s", *resize_source_size, *resize_target_size)
                return ImageUpscaleResult(
                    bytes=ensured,
                    mime_type=ensured_mime,
                    source="local_resize",
                    source_size=resize_source_size,
                    target_size=resize_target_size,
                    used_flow=flow_changed,
                )

        reason = "Flow returned original bytes"
        if flow_changed:
            reason = (
                f"Flow returned {candidate_size[0]}x{candidate_size[1]} bytes"
                if candidate_size
                else "Flow returned unreadable image bytes"
            )
        elif not self._flow_upsample_api_enabled():
            reason = "Flow upsample API disabled"
        return ImageUpscaleResult(
            source="flow_unavailable",
            source_size=source_size,
            target_size=candidate_size or source_size,
            used_flow=flow_changed,
            failure_reason=reason,
        )

    async def _persist_held_artifact_files(self, job_id: str, artifacts: List[JobArtifact]) -> str:
        """Copy a held card's 1K files to downloads/held-2k/<job8>-N.<ext> so the 2K recovery can pair them later.

        The per-card files (visible-flow-N.jpg.jpg) are shared between jobs and overwritten by the next card.
        """
        folder = self._download_root() / "held-2k"
        copied = 0
        try:
            await asyncio.to_thread(folder.mkdir, parents=True, exist_ok=True)
            for index, artifact in enumerate(artifacts):
                local_path = str(getattr(artifact, "local_path", "") or "").strip()
                source = Path(local_path).expanduser() if local_path else None
                if source is None or not source.is_file():
                    continue
                suffix = source.suffix.lower() if source.suffix.lower() in (".jpg", ".jpeg", ".png", ".webp") else ".jpg"
                destination = folder / f"{(job_id or 'job')[:8]}-{index + 1}{suffix}"
                await asyncio.to_thread(shutil.copyfile, str(source), str(destination))
                copied += 1
        except Exception as exc:  # noqa: BLE001 - best effort, the hold itself must not fail
            await self.store.append_log(job_id, f"Khong sao luu duoc anh 1K cua card giu lai: {str(exc)[:120]}")
            return ""
        if copied and job_id:
            await self.store.append_log(job_id, f"Da sao luu {copied} anh 1K cua card vao {folder} de lay 2K sau.")
        return str(folder) if copied else ""

    async def _persist_flow_2k_artifact_file(
        self,
        job_id: str,
        artifact: JobArtifact,
        artifact_index: int,
        upscale: ImageUpscaleResult,
    ) -> None:
        if not upscale.bytes or upscale.source != "flow_2k":
            return
        try:
            job = self.store.get_job(job_id)
            if job is not None:
                file_name = self._download_name(job, artifact, artifact_index)
            else:
                file_name = f"{job_id}-{artifact_index + 1}.jpg"
            base_name = Path(file_name).name or f"{job_id}-{artifact_index + 1}.jpg"
            base_path = Path(base_name)
            destination = self._download_root() / f"{base_path.stem}-2k.jpg"
            destination.parent.mkdir(parents=True, exist_ok=True)
            await asyncio.to_thread(destination.write_bytes, upscale.bytes)

            artifact.local_path = str(destination)
            artifact.public_url = self._public_download_url(str(destination))
            artifact.mime_type = upscale.mime_type or "image/jpeg"
            if upscale.target_size and max(upscale.target_size) > 0:
                dimensions = dict(artifact.dimensions or {})
                dimensions.update(
                    {
                        "width": upscale.target_size[0],
                        "height": upscale.target_size[1],
                        "upscale_source": upscale.source,
                    }
                )
                artifact.dimensions = dimensions

            if job is not None and any(existing is artifact for existing in job.artifacts):
                await self.store.replace_artifacts(job_id, job.artifacts)
        except Exception as exc:
            log.warning("Could not persist Flow 2K artifact file: %s", exc)

    def _read_remote_file(self, url: str) -> tuple[bytes, str]:
        request = Request(url, headers={"User-Agent": "FlowWebUI/0.1"})
        try:
            with urlopen(request, timeout=self.TRELLO_TIMEOUT_S) as response:
                content_type = response.headers.get_content_type() if response.headers else ""
                return response.read(), content_type
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(f"Không tải được ảnh nguồn ({exc.code}): {detail or exc.reason}") from exc
        except URLError as exc:
            raise RuntimeError(str(exc.reason or exc)) from exc

    def _multipart_form_data(
        self,
        *,
        fields: Dict[str, Any],
        file_field: str,
        file_name: str,
        file_mime: str,
        file_bytes: bytes,
    ) -> tuple[bytes, str]:
        boundary = f"----flowweb{uuid.uuid4().hex}"
        body = bytearray()
        for key, value in fields.items():
            body.extend(f"--{boundary}\r\n".encode("utf-8"))
            body.extend(f'Content-Disposition: form-data; name="{key}"\r\n\r\n'.encode("utf-8"))
            body.extend(str(value).encode("utf-8"))
            body.extend(b"\r\n")
        body.extend(f"--{boundary}\r\n".encode("utf-8"))
        body.extend(
            (
                f'Content-Disposition: form-data; name="{file_field}"; filename="{file_name}"\r\n'
                f"Content-Type: {file_mime}\r\n\r\n"
            ).encode("utf-8")
        )
        body.extend(file_bytes)
        body.extend(b"\r\n")
        body.extend(f"--{boundary}--\r\n".encode("utf-8"))
        return bytes(body), f"multipart/form-data; boundary={boundary}"

    def _trello_attachment_summary(self, payload: Dict[str, Any]) -> Dict[str, Any]:
        return {
            "id": str(payload.get("id") or "").strip(),
            "name": str(payload.get("name") or "").strip(),
            "url": str(payload.get("url") or "").strip(),
        }

    async def _send_telegram_review_pack(
        self,
        job_id: str,
        request: CreateJobRequest,
        artifacts: List[JobArtifact],
    ) -> Dict[str, Any]:
        if request.type != "image" or not artifacts or not request.telegram_enabled:
            return {}

        token, chat_id = self._telegram_credentials(request.telegram_chat_id)
        if not token or not chat_id:
            return {"configured": False}

        sent = 0
        failed = 0
        messages: List[Dict[str, Any]] = []
        for index, artifact in enumerate(artifacts):
            photo_source = await self._telegram_photo_source(job_id, artifact, index)
            if not photo_source:
                failed += 1
                continue
            caption = self._telegram_review_caption(job_id, request, artifact, index)
            reply_markup = self._telegram_approval_reply_markup(job_id, index)
            try:
                message_payload = await asyncio.to_thread(
                    self._send_telegram_photo,
                    token,
                    chat_id,
                    photo_source,
                    caption,
                    reply_markup,
                )
                sent += 1
                messages.append(
                    {
                        "artifact_index": index,
                        "message_id": str(message_payload.get("message_id") or ""),
                        "chat_id": chat_id,
                        "status": "pending",
                    }
                )
            except Exception as exc:
                failed += 1
                await self.store.append_log(
                    job_id,
                    f"Không gửi được ảnh {index + 1} sang Telegram: {humanize_flow_error(str(exc))}",
                )

        if sent:
            await self.store.append_log(job_id, f"Đã gửi {sent} ảnh sang Telegram để duyệt.")
        return {
            "configured": True,
            "sent": sent,
            "failed": failed,
            "chat_id": chat_id,
            "pending_approvals": sent,
            "messages": messages,
        }

    async def _telegram_photo_source(self, job_id: str, artifact: JobArtifact, artifact_index: int) -> str:
        local_path = str(artifact.local_path or "").strip()
        if local_path and Path(local_path).expanduser().is_file():
            return local_path

        remote_url = str(artifact.url or artifact.public_url or "").strip()
        if not remote_url:
            return ""
        if not self._telegram_requires_file_upload(remote_url):
            return remote_url

        try:
            return await self._materialize_artifact_file(job_id, artifact, artifact_index)
        except Exception as exc:
            await self.store.append_log(
                job_id,
                f"Không tải được ảnh {artifact_index + 1} về máy trước khi gửi Telegram: {humanize_flow_error(str(exc))}",
            )
            return remote_url

    def _telegram_requires_file_upload(self, url: str) -> bool:
        parsed = urlparse(str(url or "").strip())
        return parsed.netloc.endswith("labs.google")

    async def _materialize_artifact_file(self, job_id: str, artifact: JobArtifact, artifact_index: int) -> str:
        local_path = str(artifact.local_path or "").strip()
        if local_path and Path(local_path).expanduser().is_file():
            return local_path

        source = str(artifact.url or artifact.public_url or "").strip()
        if not source:
            return ""

        job = self.store.get_job(job_id)
        if job is not None:
            file_name = self._download_name(job, artifact, artifact_index)
        else:
            file_name = f"{job_id}-{artifact_index + 1}.jpg"
        destination = self._download_root() / file_name
        destination.parent.mkdir(parents=True, exist_ok=True)

        async def _go(client: Any) -> str:
            saved = await client.download(source, destination)
            return str(saved)

        workflow_id = str(artifact.workflow_id or "").strip()
        if not workflow_id and job is not None and isinstance(job.input, dict):
            workflow_id = str(job.input.get("workflow_id") or "").strip()
        local_path = await self._with_client(_go, workflow_id=workflow_id)
        artifact.local_path = local_path
        artifact.public_url = self._public_download_url(local_path)
        if job is not None:
            await self.store.replace_artifacts(job_id, job.artifacts)
        return local_path

    def _telegram_credentials(self, requested_chat_id: str = "") -> tuple[str, str]:
        config = self.store.snapshot().integration_config
        token = str(config.telegram_bot_token or "").strip() or os.getenv("TELEGRAM_BOT_TOKEN", "").strip()
        chat_id = (
            str(requested_chat_id or "").strip()
            or str(config.telegram_chat_id or "").strip()
            or os.getenv("TELEGRAM_CHAT_ID", "").strip()
        )
        return token, chat_id

    def _telegram_review_caption(
        self,
        job_id: str,
        request: CreateJobRequest,
        artifact: JobArtifact,
        index: int,
    ) -> str:
        prompt = str(artifact.prompt or request.prompt or "").strip()
        if len(prompt) > 780:
            prompt = f"{prompt[:777]}..."
        parts = [
            f"Flow image #{index + 1}",
            f"Job: {job_id[:8]}",
        ]
        if prompt:
            parts.append(f"Prompt: {prompt}")
        parts.append("Bấm Duyệt hoặc Từ chối bên dưới. Sau đó quay lại app bấm Đồng bộ duyệt Telegram.")
        return "\n".join(parts)

    def _telegram_approval_reply_markup(self, job_id: str, artifact_index: int) -> Dict[str, Any]:
        safe_index = max(0, int(artifact_index))
        return {
            "inline_keyboard": [
                [
                    {
                        "text": "✅ Duyệt",
                        "callback_data": f"fw:approve:{job_id}:{safe_index}",
                    },
                    {
                        "text": "❌ Từ chối",
                        "callback_data": f"fw:reject:{job_id}:{safe_index}",
                    },
                ]
            ]
        }

    def _send_telegram_photo(
        self,
        token: str,
        chat_id: str,
        photo_url: str,
        caption: str,
        reply_markup: Dict[str, Any] | None = None,
    ) -> Dict[str, Any]:
        endpoint = self.TELEGRAM_API_URL_TEMPLATE.format(token=quote(token, safe=":"), method="sendPhoto")
        local_photo = Path(str(photo_url or "")).expanduser()
        if local_photo.is_file():
            fields: Dict[str, Any] = {
                "chat_id": chat_id,
                "caption": caption,
            }
            if reply_markup:
                fields["reply_markup"] = json.dumps(reply_markup, ensure_ascii=False)
            mime = mimetypes.guess_type(local_photo.name)[0] or "image/jpeg"
            body, content_type = self._multipart_form_data(
                fields=fields,
                file_field="photo",
                file_name=local_photo.name,
                file_mime=mime,
                file_bytes=local_photo.read_bytes(),
            )
            request = Request(
                endpoint,
                data=body,
                headers={"Content-Type": content_type},
                method="POST",
            )
        else:
            payload: Dict[str, Any] = {
                "chat_id": chat_id,
                "photo": photo_url,
                "caption": caption,
            }
            if reply_markup:
                payload["reply_markup"] = reply_markup
            body = json.dumps(payload).encode("utf-8")
            request = Request(
                endpoint,
                data=body,
                headers={"Content-Type": "application/json"},
                method="POST",
            )
        try:
            with urlopen(request, timeout=self.TELEGRAM_TIMEOUT_S) as response:
                payload = response.read().decode("utf-8", errors="replace")
                data = json.loads(payload) if payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(detail or str(exc)) from exc
        except URLError as exc:
            raise RuntimeError(str(exc.reason or exc)) from exc

        if not data.get("ok", False):
            raise RuntimeError(str(data.get("description") or "Telegram không nhận ảnh."))
        result = data.get("result")
        return result if isinstance(result, dict) else {}

    async def run_telegram_approval_sync_loop(self, interval_s: float = 5.0) -> None:
        interval = max(0.1, float(interval_s or 5.0))
        while True:
            try:
                await self.sync_telegram_approvals()
                self._last_telegram_approval_sync_error = ""
            except asyncio.CancelledError:
                raise
            except Exception as exc:
                self._last_telegram_approval_sync_error = humanize_flow_error(str(exc))
            await asyncio.sleep(interval)

    async def sync_telegram_approvals(self) -> Dict[str, Any]:
        async with self._telegram_approval_sync_lock:
            result = await self._sync_telegram_approvals_unlocked()
            if result.get("configured") is not False:
                result["last_error"] = self._last_telegram_approval_sync_error
            return result

    async def _sync_telegram_approvals_unlocked(self) -> Dict[str, Any]:
        token, _ = self._telegram_credentials("")
        if not token:
            return {"configured": False, "processed": 0, "approvals": []}

        updates = await asyncio.to_thread(self._telegram_get_updates, token)
        max_update_id = -1
        approvals: List[Dict[str, Any]] = []
        for update in updates:
            try:
                max_update_id = max(max_update_id, int(update.get("update_id", -1)))
            except Exception:
                pass
            callback = update.get("callback_query") if isinstance(update, dict) else None
            parsed = self._parse_telegram_approval_callback(callback or {})
            if not parsed:
                continue
            approval = await self._apply_telegram_approval(
                parsed["job_id"],
                parsed["artifact_index"],
                parsed["status"],
                callback or {},
            )
            if approval:
                approvals.append(approval)
                callback_id = str((callback or {}).get("id") or "").strip()
                if callback_id:
                    await asyncio.to_thread(
                        self._telegram_answer_callback_query,
                        token,
                        callback_id,
                        "Đã ghi nhận duyệt ảnh." if parsed["status"] == "approved" else "Đã ghi nhận từ chối ảnh.",
                    )

        if max_update_id >= 0:
            await asyncio.to_thread(self._telegram_get_updates, token, max_update_id + 1)

        return {
            "configured": True,
            "processed": len(approvals),
            "approvals": approvals,
        }

    def _telegram_get_updates(self, token: str, offset: int | None = None) -> List[Dict[str, Any]]:
        endpoint = self.TELEGRAM_API_URL_TEMPLATE.format(token=quote(token, safe=":"), method="getUpdates")
        payload: Dict[str, Any] = {
            "timeout": 0,
            "allowed_updates": ["callback_query"],
        }
        if offset is not None:
            payload["offset"] = offset
        body = json.dumps(payload).encode("utf-8")
        request = Request(
            endpoint,
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urlopen(request, timeout=self.TELEGRAM_TIMEOUT_S) as response:
                raw_payload = response.read().decode("utf-8", errors="replace")
                data = json.loads(raw_payload) if raw_payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(detail or str(exc)) from exc
        except URLError as exc:
            raise RuntimeError(str(exc.reason or exc)) from exc
        if not data.get("ok", False):
            raise RuntimeError(str(data.get("description") or "Telegram không trả callback."))
        result = data.get("result")
        return result if isinstance(result, list) else []

    def _telegram_answer_callback_query(self, token: str, callback_query_id: str, text: str) -> None:
        endpoint = self.TELEGRAM_API_URL_TEMPLATE.format(token=quote(token, safe=":"), method="answerCallbackQuery")
        body = json.dumps(
            {
                "callback_query_id": callback_query_id,
                "text": text,
                "show_alert": False,
            }
        ).encode("utf-8")
        request = Request(
            endpoint,
            data=body,
            headers={"Content-Type": "application/json"},
            method="POST",
        )
        try:
            with urlopen(request, timeout=self.TELEGRAM_TIMEOUT_S) as response:
                payload = response.read().decode("utf-8", errors="replace")
                data = json.loads(payload) if payload else {}
        except HTTPError as exc:
            detail = exc.read().decode("utf-8", errors="replace")
            raise RuntimeError(detail or str(exc)) from exc
        except URLError as exc:
            raise RuntimeError(str(exc.reason or exc)) from exc
        if not data.get("ok", False):
            raise RuntimeError(str(data.get("description") or "Telegram không xác nhận callback."))

    def _parse_telegram_approval_callback(self, callback: Dict[str, Any]) -> Dict[str, Any]:
        data = str(callback.get("data") or "").strip()
        parts = data.split(":")
        if len(parts) != 4 or parts[0] != "fw" or parts[1] not in {"approve", "reject"}:
            return {}
        try:
            artifact_index = int(parts[3])
        except ValueError:
            return {}
        if artifact_index < 0:
            return {}
        return {
            "status": "approved" if parts[1] == "approve" else "rejected",
            "job_id": parts[2],
            "artifact_index": artifact_index,
        }

    async def _apply_telegram_approval(
        self,
        job_id: str,
        artifact_index: int,
        status: str,
        callback: Dict[str, Any],
    ) -> Dict[str, Any]:
        job = self.store.get_job(job_id)
        if job is None or artifact_index < 0 or artifact_index >= len(job.artifacts):
            return {}

        result = dict(job.result or {})
        approvals = dict(result.get("telegram_approvals") or {})
        key = str(artifact_index)
        previous = approvals.get(key) if isinstance(approvals.get(key), dict) else {}
        previous_status = str(previous.get("status") or "").strip()
        if previous_status in {"approved", "rejected"}:
            if previous_status != status:
                reviewer = self._telegram_callback_reviewer(callback)
                reviewer_name = reviewer.get("name") or reviewer.get("username") or "Telegram user"
                previous_label = "đã duyệt" if previous_status == "approved" else "đã từ chối"
                await self.store.append_log(
                    job_id,
                    f"Bỏ qua phản hồi Telegram của {reviewer_name} vì ảnh {artifact_index + 1} {previous_label} trước đó.",
                )
            return previous
        reviewer = self._telegram_callback_reviewer(callback)
        message = callback.get("message") if isinstance(callback.get("message"), dict) else {}
        approval = {
            "artifact_index": artifact_index,
            "status": status,
            "reviewer": reviewer,
            "callback_query_id": str(callback.get("id") or "").strip(),
            "message_id": str(message.get("message_id") or "").strip(),
            "chat_id": str((message.get("chat") or {}).get("id") or "").strip()
            if isinstance(message.get("chat"), dict)
            else "",
            "updated_at": utc_now(),
        }
        approvals[key] = approval
        result["telegram_approvals"] = approvals
        summary = self._telegram_approval_summary(approvals, len(job.artifacts))
        result["telegram_approval_summary"] = summary
        approval_module_id = self._sync_automation_approval_execution(result, summary, len(job.artifacts))
        await self.store.patch_job(job_id, result=result)

        if previous.get("status") != status:
            label = "đã duyệt" if status == "approved" else "đã từ chối"
            reviewer_name = reviewer.get("name") or reviewer.get("username") or "Telegram user"
            await self.store.append_log(job_id, f"{reviewer_name} {label} ảnh {artifact_index + 1} trên Telegram.")
        if approval_module_id and summary.get("pending") == 0:
            await self._resume_automation_after_approval(job_id, approval_module_id)
        return approval

    def _telegram_callback_reviewer(self, callback: Dict[str, Any]) -> Dict[str, Any]:
        user = callback.get("from") if isinstance(callback.get("from"), dict) else {}
        first = str(user.get("first_name") or "").strip()
        last = str(user.get("last_name") or "").strip()
        username = str(user.get("username") or "").strip()
        return {
            "id": str(user.get("id") or "").strip(),
            "name": " ".join(part for part in [first, last] if part).strip(),
            "username": username,
        }

    def _telegram_approval_summary(self, approvals: Dict[str, Any], artifact_count: int) -> Dict[str, Any]:
        approved = 0
        rejected = 0
        pending = max(0, artifact_count)
        for value in approvals.values():
            if not isinstance(value, dict):
                continue
            if value.get("status") == "approved":
                approved += 1
            elif value.get("status") == "rejected":
                rejected += 1
        resolved = approved + rejected
        pending = max(0, artifact_count - resolved)
        return {
            "total": artifact_count,
            "approved": approved,
            "rejected": rejected,
            "pending": pending,
            "resolved": resolved,
            "status": "completed" if artifact_count and resolved >= artifact_count else "waiting",
        }

    def _sync_automation_approval_execution(
        self,
        result: Dict[str, Any],
        summary: Dict[str, Any],
        artifact_count: int,
    ) -> str:
        execution = result.get("automation_execution")
        if not isinstance(execution, dict) or not isinstance(execution.get("nodes"), list):
            return ""
        nodes = execution["nodes"]
        approval_node = next((node for node in nodes if node.get("type") == "approval"), None)
        if not approval_node:
            return ""
        now = utc_now()
        approval_node["status"] = "completed" if summary.get("pending") == 0 and artifact_count else "running"
        approval_node["output"] = {
            "awaiting_user_approval": summary.get("pending", 0) > 0,
            "telegram_approval_summary": summary,
        }
        if not approval_node.get("started_at"):
            approval_node["started_at"] = now
        if approval_node["status"] == "completed":
            approval_node["completed_at"] = now
        execution["current_module_id"] = approval_node.get("id", "") if approval_node["status"] == "running" else ""
        execution["completed"] = all(
            str(node.get("status") or "") in {"completed", "skipped", "disabled"}
            for node in nodes
        )
        return str(approval_node.get("id") or "")

    def _build_video_artifacts(
        self,
        video_jobs: List[Any],
        statuses: List[Any],
        request: CreateJobRequest,
        *,
        default_label: str = "",
    ) -> tuple[List[JobArtifact], List[str]]:
        artifacts: List[JobArtifact] = []
        missing_labels: List[str] = []

        for index, (job, status) in enumerate(zip(video_jobs, statuses)):
            label = default_label or f"Video {index + 1}"
            media_name = str(getattr(job, "media_name", "") or "").strip()
            url = self._video_status_url(status, media_name=media_name)
            if not url:
                missing_labels.append(label)
                continue

            artifacts.append(
                JobArtifact(
                    label=label,
                    media_name=media_name,
                    url=url,
                    workflow_id=getattr(job, "workflow_id", request.workflow_id),
                    mime_type="video/mp4",
                    prompt=request.prompt,
                )
            )

        return artifacts, missing_labels

    def _video_status_url(self, status: Any, *, media_name: str = "") -> str:
        candidates = (
            getattr(status, "fife_url", ""),
            getattr(status, "download_url", ""),
            getattr(status, "url", ""),
        )
        for candidate in candidates:
            value = str(candidate or "").strip()
            if value:
                return value
        raw_status = getattr(status, "_raw", {}) or {}
        raw_media = raw_status.get("media", []) if isinstance(raw_status, dict) else []
        for media_item in raw_media or []:
            if not isinstance(media_item, dict):
                continue
            video_payload = media_item.get("video", {})
            if not isinstance(video_payload, dict):
                continue
            generated = video_payload.get("generatedVideo", {})
            if isinstance(generated, dict):
                for key in ("fifeUrl", "downloadUrl", "url"):
                    value = str(generated.get(key) or "").strip()
                    if value:
                        return value
                output_video = generated.get("outputVideo", {})
                if isinstance(output_video, dict):
                    for key in ("fifeUrl", "downloadUrl", "url"):
                        value = str(output_video.get(key) or "").strip()
                        if value:
                            return value
        fallback_media_name = str(media_name or getattr(status, "media_name", "") or "").strip()
        if fallback_media_name:
            return f"https://labs.google/fx/api/trpc/media.getMediaUrlRedirect?name={quote(fallback_media_name)}"
        return ""

    def _is_audio_generation_failure(self, message: str) -> bool:
        lowered = str(message or "").strip().lower()
        if not lowered:
            return False
        return (
            "audio generation failed" in lowered
            or "return silent videos" in lowered
            or ("audio" in lowered and "failed" in lowered)
            or ("audio" in lowered and "silent" in lowered)
            or "phần tạo audio bị lỗi" in lowered
            or "âm thanh bị lỗi" in lowered
            or "video im lặng" in lowered
            or "model không audio" in lowered
        )

    def _audio_fallback_video_model(self, model: str) -> str:
        normalized = self._normalize_video_model(model)
        mapping = {
            "Veo 3.1 - Fast": "Veo 2 - Fast",
            "Veo 3.1 - Quality": "Veo 2 - Quality",
            "Veo 3.1 - Fast [Lower Priority]": "Veo 2 - Fast",
        }
        fallback = mapping.get(normalized, "")
        if fallback == normalized:
            return ""
        return fallback

    def _video_status_failure_detail(self, status: Any) -> str:
        raw_status = getattr(status, "_raw", {}) or {}
        if not isinstance(raw_status, dict):
            return ""

        preferred_fields = {
            "message",
            "messages",
            "detail",
            "details",
            "error",
            "errors",
            "errormessage",
            "failuremessage",
            "failurereason",
            "reason",
            "description",
            "statusmessage",
            "usermessage",
            "userfacingmessage",
            "localizedmessage",
            "displaymessage",
            "title",
        }
        seen: set[str] = set()
        audio_messages: list[str] = []
        preferred_messages: list[str] = []
        generic_messages: list[str] = []

        def add_message(target: list[str], value: str) -> None:
            normalized = " ".join(str(value or "").split()).strip()
            if not normalized:
                return
            lowered = normalized.lower()
            if lowered in seen:
                return
            if lowered in {
                "media_generation_status_failed",
                "media_generation_status_rejected",
                "failed",
                "rejected",
            }:
                return
            seen.add(lowered)
            target.append(normalized)

        def visit(node: Any) -> None:
            if isinstance(node, dict):
                for key, value in node.items():
                    key_lower = str(key or "").strip().lower()
                    if isinstance(value, str):
                        lowered = value.strip().lower()
                        if self._is_audio_generation_failure(value):
                            add_message(audio_messages, value)
                        elif key_lower in preferred_fields:
                            add_message(preferred_messages, value)
                        elif any(token in lowered for token in ("failed", "error", "rejected")):
                            add_message(generic_messages, value)
                    else:
                        visit(value)
            elif isinstance(node, list):
                for item in node:
                    visit(item)

        visit(raw_status)

        if audio_messages:
            return " ".join(audio_messages[:2])
        if preferred_messages:
            return preferred_messages[0]
        if generic_messages:
            return generic_messages[0]
        return ""

    async def _with_client(
        self,
        fn: Callable[[Any], Any],
        workflow_id: str = "",
        timeout_s: int = 0,
        job_id: str = "",
    ) -> Any:
        FlowClient, _, _, _, _ = self._flow_modules(client_only=True)
        config = self._normalized_config(self.store.snapshot().config)
        profiles = self._flow_profile_specs() if self._should_keep_flow_browser_open(config) else []
        if not config.project_id and not any(profile.project_id for profile in profiles):
            raise HTTPException(status_code=400, detail="Mã project là bắt buộc.")
        effective_timeout_s = max(30, int(timeout_s or config.generation_timeout_s))
        resolved_workflow_id = workflow_id or config.active_workflow_id or None

        if self._should_keep_flow_browser_open(config):
            async with self._browser_session_lock:
                attempts = max(1, len(profiles))
                last_quota_error: Exception | None = None
                attempted_source_profiles: set[str] = set()
                attempted_try_again_profiles: set[str] = set()
                for _ in range(attempts):
                    profile = self._current_flow_profile()
                    if self._flow_profile_is_quota_blocked(profile):
                        raise HTTPException(status_code=429, detail=self._flow_profiles_all_quota_blocked_detail())
                    profile_project_id = self._flow_profile_project_id(profile, config.project_id)
                    if not profile_project_id:
                        raise HTTPException(status_code=400, detail="Mã project là bắt buộc.")
                    try:
                        browser = await self._ensure_shared_browser(profile)
                        client = await self._build_client_from_shared_browser(
                            browser,
                            project_id=profile_project_id,
                            workflow_id=resolved_workflow_id,
                            timeout_s=effective_timeout_s,
                        )
                        result = await fn(client)
                        await self._reset_flow_profile_agent_try_again_errors(profile)
                        self._flow_profile_agent_failed_job_counts.pop(profile.key, None)
                        return result
                    except HTTPException:
                        raise
                    except Exception as exc:
                        if self._is_flow_agent_source_attachment_error(exc):
                            attempted_source_profiles.add(profile.key)
                            next_profile = self._next_unattempted_flow_profile(
                                profile,
                                attempted_source_profiles,
                            )
                            if next_profile is not None:
                                self._active_flow_profile_index = next_profile.index
                                continue
                        if self._is_flow_agent_quota_error(exc):
                            last_quota_error = exc
                            await self._mark_flow_profile_quota_limited(profile, exc)
                            next_profile = self._next_available_flow_profile(profile)
                            if next_profile is not None:
                                self._active_flow_profile_index = next_profile.index
                                continue
                            raise HTTPException(status_code=429, detail=self._flow_profiles_all_quota_blocked_detail()) from exc
                        if self._is_flow_agent_failed_message(exc):
                            # "The agent failed. Please try again." on every submit is the daily Agent limit
                            # (no quota text, credits untouched; seen on Acc13/14/15 2026-09-05..09).
                            count = self._record_flow_profile_agent_failed_job(profile)
                            threshold = self._flow_agent_failed_switch_threshold()
                            if count >= threshold:
                                last_quota_error = exc
                                await self._mark_flow_profile_quota_limited(profile, exc)
                                next_profile = self._next_available_flow_profile(profile)
                                await self._log_flow_profile_agent_failed_switch(job_id, profile, next_profile, count)
                                if next_profile is not None:
                                    self._active_flow_profile_index = next_profile.index
                                    continue
                                raise HTTPException(status_code=429, detail=self._flow_profiles_all_quota_blocked_detail()) from exc
                            if job_id:
                                await self.store.append_log(
                                    job_id,
                                    (
                                        f"Flow Agent failed trên {profile.label} ({count}/{threshold} card liên tiếp); "
                                        f"đủ {threshold} card app sẽ chặn acc này đến "
                                        f"{self._flow_profile_block_until_label(self._flow_profile_block_until())} giờ VN và đổi acc."
                                    ),
                                )
                            raise HTTPException(
                                status_code=self._flow_error_status(exc),
                                detail=(
                                    f"{self._flow_error_detail(exc)} "
                                    f"(Flow Agent failed {count}/{threshold} card liên tiếp trên {profile.label}; đủ {threshold} card sẽ đổi acc.)"
                                ),
                            ) from exc
                        if self._is_flow_agent_try_again_error(exc):
                            count = await self._record_flow_profile_agent_try_again_error(profile, exc)
                            threshold = self._flow_agent_try_again_threshold()
                            if count >= threshold:
                                last_quota_error = exc
                                await self._mark_flow_profile_quota_limited(profile, exc)
                                next_profile = self._next_available_flow_profile(profile)
                                if next_profile is not None:
                                    self._active_flow_profile_index = next_profile.index
                                    continue
                                raise HTTPException(status_code=429, detail=self._flow_profiles_all_quota_blocked_detail()) from exc
                            attempted_try_again_profiles.add(profile.key)
                            next_profile = self._next_unattempted_flow_profile(
                                profile,
                                attempted_try_again_profiles,
                            )
                            if next_profile is not None:
                                self._active_flow_profile_index = next_profile.index
                                continue
                            raise HTTPException(
                                status_code=self._flow_error_status(exc),
                                detail=(
                                    f"{self._flow_error_detail(exc)} "
                                    f"(Flow Agent retry error {count}/{threshold} trên {profile.label}; đủ {threshold} lần liên tiếp sẽ đổi acc.)"
                                ),
                            ) from exc
                        if self._is_browser_closed_error(exc):
                            await self._close_shared_browser()
                        raise HTTPException(
                            status_code=self._flow_error_status(exc),
                            detail=self._flow_error_detail(exc),
                        ) from exc

                if last_quota_error is not None:
                    raise HTTPException(
                        status_code=429,
                        detail=self._flow_error_detail(last_quota_error),
                    ) from last_quota_error

        try:
            client = await FlowClient.create(
                project_id=config.project_id,
                workflow_id=resolved_workflow_id,
                headless=config.headless,
                cdp_url=config.cdp_url or None,
                timeout_s=effective_timeout_s,
            )
        except Exception as exc:
            raise HTTPException(
                status_code=self._flow_error_status(exc),
                detail=self._flow_error_detail(exc),
            ) from exc
        try:
            return await fn(client)
        except HTTPException:
            raise
        except Exception as exc:
            raise HTTPException(
                status_code=self._flow_error_status(exc),
                detail=self._flow_error_detail(exc),
            ) from exc
        finally:
            await client.close()

    def _should_keep_flow_browser_open(self, config: AppConfig) -> bool:
        return not config.headless and not config.cdp_url

    def _split_flow_profile_env(self, raw: str) -> List[str]:
        normalized = str(raw or "").replace("\r", "\n").replace("|", "\n")
        parts: List[str] = []
        for segment in normalized.split("\n"):
            for item in segment.split(";"):
                value = item.strip()
                if value:
                    parts.append(value)
        return parts

    def _resolve_flow_profile_path(self, value: str) -> Path:
        raw = str(value or "").strip().strip('"').strip("'")
        if not raw or raw.lower() in {"default", "flow-default", "flow_py_default"}:
            try:
                from flow._storage import PROFILE_DIR
            except Exception:
                return PROJECT_ROOT / ".flow-browser-profile"
            return Path(PROFILE_DIR)

        path = Path(os.path.expandvars(os.path.expanduser(raw)))
        if not path.is_absolute():
            path = PROJECT_ROOT / path
        return path

    def _flow_profile_specs(self) -> List[FlowBrowserProfile]:
        raw_profiles = (
            os.getenv("FLOW_CHROME_PROFILE_DIRS", "").strip()
            or os.getenv("FLOW_PROFILE_DIRS", "").strip()
            or os.getenv("GOOGLE_FLOW_PROFILE_DIRS", "").strip()
        )
        entries = self._split_flow_profile_env(raw_profiles)
        specs: List[FlowBrowserProfile] = []

        if entries:
            for index, entry in enumerate(entries):
                label = f"Flow profile {index + 1}"
                value = entry
                if "=" in entry:
                    maybe_label, maybe_value = entry.split("=", 1)
                    if maybe_label.strip() and maybe_value.strip():
                        label = maybe_label.strip()
                        value = maybe_value.strip()
                specs.append(FlowBrowserProfile(index=index, label=label, path=self._resolve_flow_profile_path(value)))
        else:
            specs.append(FlowBrowserProfile(index=0, label="Flow profile 1", path=self._resolve_flow_profile_path("default")))
            raw_count = os.getenv("FLOW_CHROME_PROFILE_COUNT", "").strip()
            try:
                profile_count = max(1, min(20, int(raw_count))) if raw_count else 1
            except ValueError:
                profile_count = 1
            for index in range(1, profile_count):
                specs.append(
                    FlowBrowserProfile(
                        index=index,
                        label=f"Flow profile {index + 1}",
                        path=PROJECT_ROOT / "data" / "flow-profiles" / f"profile-{index + 1}",
                    )
                )

        project_map = self._flow_profile_project_map()
        positional_projects = self._flow_profile_positional_projects()
        deduped: List[FlowBrowserProfile] = []
        seen: set[str] = set()
        for spec in specs:
            key = spec.key
            if key in seen:
                continue
            seen.add(key)
            profile_index = len(deduped)
            project_id = (
                project_map.get(spec.label.strip().lower(), "")
                or project_map.get(key, "")
                or project_map.get(spec.path.name.strip().lower(), "")
                or (positional_projects[profile_index] if profile_index < len(positional_projects) else "")
            )
            deduped.append(
                FlowBrowserProfile(
                    index=profile_index,
                    label=spec.label,
                    path=spec.path,
                    project_id=project_id,
                )
            )
        return deduped or [FlowBrowserProfile(index=0, label="Flow profile 1", path=self._resolve_flow_profile_path("default"))]

    def _flow_profile_project_entries(self) -> List[str]:
        raw = (
            os.getenv("FLOW_CHROME_PROFILE_PROJECTS", "").strip()
            or os.getenv("FLOW_PROFILE_PROJECTS", "").strip()
            or os.getenv("GOOGLE_FLOW_PROFILE_PROJECTS", "").strip()
        )
        return self._split_flow_profile_env(raw)

    def _flow_profile_project_map(self) -> Dict[str, str]:
        mapping: Dict[str, str] = {}
        for entry in self._flow_profile_project_entries():
            if "=" not in entry:
                continue
            key, value = entry.split("=", 1)
            project_id = self._normalize_project_id(value)
            if not key.strip() or not project_id:
                continue
            raw_key = key.strip().strip('"').strip("'")
            mapping[raw_key.lower()] = project_id
            try:
                mapping[self._resolve_flow_profile_path(raw_key).resolve().as_posix().lower()] = project_id
                mapping[str(self._resolve_flow_profile_path(raw_key).resolve()).lower()] = project_id
            except Exception:
                pass
        return mapping

    def _flow_profile_positional_projects(self) -> List[str]:
        projects: List[str] = []
        for entry in self._flow_profile_project_entries():
            if "=" in entry:
                continue
            project_id = self._normalize_project_id(entry)
            if project_id:
                projects.append(project_id)
        return projects

    def _flow_profile_project_id(self, profile: FlowBrowserProfile, fallback_project_id: str = "") -> str:
        return self._normalize_project_id(profile.project_id or fallback_project_id)

    FLOW_PROFILE_BLOCK_MIN_SECONDS = 60.0
    FLOW_PROFILE_BLOCK_SECONDS = 24.0 * 60.0 * 60.0

    def _flow_profile_block_until(self, now: float | None = None) -> float:
        """Epoch when a quota-blocked profile may be used again: 24 h after the strike.

        Flow's Agent limit (and the editor's 2K download limit) behave as rolling ~24 h windows from the
        moment they were hit: accounts blocked at 12:19 / 15:42 VN on 2026-09-09 still failed at 08:08 VN
        the next day, i.e. after 00:00 UTC, so a release at midnight UTC under-blocked them. The earlier
        "reset at 07:00 VN" reading came from the 2026-09-08 "high demand" outage, not from the quota.
        FLOW_CHROME_PROFILE_QUOTA_BLOCK_S / FLOW_PROFILE_QUOTA_BLOCK_S override the duration.
        """
        current = float(now if now is not None else time.time())
        raw = os.getenv("FLOW_CHROME_PROFILE_QUOTA_BLOCK_S", "").strip() or os.getenv("FLOW_PROFILE_QUOTA_BLOCK_S", "").strip()
        if raw:
            try:
                return current + max(self.FLOW_PROFILE_BLOCK_MIN_SECONDS, float(raw))
            except ValueError:
                pass
        return current + self.FLOW_PROFILE_BLOCK_SECONDS

    def _flow_profile_block_until_label(self, blocked_until: float) -> str:
        """Human label in Vietnam time, e.g. '07:00 10/09'."""
        try:
            moment = datetime.fromtimestamp(float(blocked_until), tz=timezone(timedelta(hours=7)))
        except (TypeError, ValueError, OverflowError, OSError):
            return ""
        return moment.strftime("%H:%M %d/%m")

    def _flow_agent_failed_switch_threshold(self) -> int:
        """Consecutive jobs ending in "The agent failed" on one profile before the app blocks it and rotates."""
        raw = os.getenv("FLOW_AGENT_FAILED_SWITCH_THRESHOLD", "").strip()
        try:
            return max(1, min(20, int(raw))) if raw else 2
        except ValueError:
            return 2

    def _record_flow_profile_agent_failed_job(self, profile: FlowBrowserProfile) -> int:
        next_count = int(self._flow_profile_agent_failed_job_counts.get(profile.key, 0) or 0) + 1
        self._flow_profile_agent_failed_job_counts[profile.key] = next_count
        return next_count

    def _flow_agent_try_again_threshold(self) -> int:
        raw = (
            os.getenv("FLOW_AGENT_TRY_AGAIN_SWITCH_THRESHOLD", "").strip()
            or os.getenv("FLOW_CHROME_PROFILE_TRY_AGAIN_SWITCH_THRESHOLD", "").strip()
        )
        try:
            return max(1, min(100, int(raw))) if raw else 10
        except ValueError:
            return 10

    def _valid_flow_profile_quota_blocks(self, blocks: Dict[str, float] | None) -> Dict[str, float]:
        now = time.time()
        valid: Dict[str, float] = {}
        for key, value in (blocks or {}).items():
            safe_key = str(key or "").strip().lower()
            if not safe_key:
                continue
            try:
                blocked_until = float(value or 0.0)
            except (TypeError, ValueError):
                continue
            if blocked_until > now:
                valid[safe_key] = blocked_until
        return valid

    def _valid_flow_profile_agent_retry_counts(self, counts: Dict[str, int] | None) -> Dict[str, int]:
        valid: Dict[str, int] = {}
        for key, value in (counts or {}).items():
            safe_key = str(key or "").strip().lower()
            if not safe_key:
                continue
            try:
                count = int(value or 0)
            except (TypeError, ValueError):
                continue
            if count > 0:
                valid[safe_key] = count
        return valid

    def _flow_profiles_all_quota_blocked_detail(self) -> str:
        profiles = self._flow_profile_specs()
        blocked_labels = [
            profile.label
            for profile in profiles
            if self._flow_profile_is_quota_blocked(profile)
        ]
        label_text = ", ".join(blocked_labels) if blocked_labels else "tat ca profile"
        expiries = [
            float(self._flow_profile_quota_blocked_until.get(profile.key, 0.0) or 0.0)
            for profile in profiles
            if self._flow_profile_is_quota_blocked(profile)
        ]
        reset_text = ""
        if expiries:
            reset_label = self._flow_profile_block_until_label(min(expiries))
            if reset_label:
                reset_text = f" (som nhat {reset_label} gio VN)"
        return (
            f"Tat ca Chrome profile Flow da het quota Agent ({label_text}). "
            f"App da dung thay vi quay lai profile da het quota. Hay dang nhap them profile khac hoac cho quota reset{reset_text}."
        )

    async def _log_flow_profile_agent_failed_switch(
        self,
        job_id: str,
        profile: FlowBrowserProfile,
        next_profile: FlowBrowserProfile | None,
        count: int,
    ) -> None:
        if not job_id:
            return
        until_label = self._flow_profile_block_until_label(
            float(self._flow_profile_quota_blocked_until.get(profile.key, 0.0) or 0.0)
        )
        head = (
            f"Flow Agent failed {count} card liên tiếp trên {profile.label} (hết hạn mức Agent trong ngày). "
            f"App chặn {profile.label} đến {until_label} giờ VN"
        )
        if next_profile is not None:
            message = f"{head} và chuyển sang {next_profile.label} cho card này."
        else:
            message = f"{head}; không còn acc nào khác nên Auto AI sẽ dừng tới lúc đó."
        await self.store.append_log(job_id, message)

    def _flow_profile_is_quota_blocked(self, profile: FlowBrowserProfile) -> bool:
        blocked_until = float(self._flow_profile_quota_blocked_until.get(profile.key, 0.0) or 0.0)
        if blocked_until <= 0:
            return False
        if blocked_until > time.time():
            return True
        self._flow_profile_quota_blocked_until.pop(profile.key, None)
        return False

    def _current_flow_profile(self) -> FlowBrowserProfile:
        profiles = self._flow_profile_specs()
        if self._active_flow_profile_index >= len(profiles):
            self._active_flow_profile_index = 0
        start = max(0, self._active_flow_profile_index)
        for offset in range(len(profiles)):
            candidate = profiles[(start + offset) % len(profiles)]
            if not self._flow_profile_is_quota_blocked(candidate):
                self._active_flow_profile_index = candidate.index
                return candidate
        return profiles[start % len(profiles)]

    def _next_available_flow_profile(self, current: FlowBrowserProfile) -> FlowBrowserProfile | None:
        profiles = self._flow_profile_specs()
        if len(profiles) <= 1:
            return None
        start = (current.index + 1) % len(profiles)
        for offset in range(len(profiles) - 1):
            candidate = profiles[(start + offset) % len(profiles)]
            if candidate.key == current.key:
                continue
            if self._flow_profile_is_quota_blocked(candidate):
                continue
            return candidate
        return None

    def _next_unattempted_flow_profile(
        self,
        current: FlowBrowserProfile,
        attempted_keys: set[str],
    ) -> FlowBrowserProfile | None:
        profiles = self._flow_profile_specs()
        if len(profiles) <= 1:
            return None
        for offset in range(1, len(profiles) + 1):
            candidate = profiles[(current.index + offset) % len(profiles)]
            if candidate.key in attempted_keys:
                continue
            if self._flow_profile_is_quota_blocked(candidate):
                continue
            return candidate
        return None

    def _is_flow_agent_quota_error(self, exc: Exception) -> bool:
        if isinstance(exc, FlowAgentQuotaError):
            return True
        detail = self._strip_accents(str(exc or "")).lower()
        return (
            "tools agent quota" in detail
            or "flow agent quota" in detail
            or ("agent" in detail and "quota limit" in detail)
            or ("come back tomorrow" in detail and "quota" in detail)
            or ("daily quota" in detail and "agent" in detail)
        )

    def _is_flow_agent_source_attachment_error(self, exc: Exception | str) -> bool:
        detail = self._flow_agent_error_match_text(exc)
        return any(
            signal in detail
            for signal in (
                "chua keo/upload duoc anh trello",
                "chua keo duoc anh nguon",
                "chua upload duoc anh trello",
                "chua xac minh duoc anh nguon",
                "no new ready attachment visible",
            )
        )

    def _flow_agent_error_match_text(self, value: Exception | str) -> str:
        detail = self._strip_accents(str(value or "")).lower()
        detail = detail.replace("đ", "d").replace("Đ", "d")
        return re.sub(r"\s+", " ", detail).strip()

    def _is_flow_agent_try_again_error(self, exc: Exception | str) -> bool:
        compact = self._flow_agent_error_match_text(exc)
        return (
            ("xay ra loi" in compact and "thu lai" in compact)
            or ("da xay ra loi" in compact and "hay thu lai" in compact)
            or ("an error occurred" in compact and "try again" in compact)
            or ("something went wrong" in compact and "try again" in compact)
        )

    def _is_flow_agent_failed_message(self, value: Exception | str) -> bool:
        """Flow's "The agent failed. Please try again." (capacity), distinct from the try-again quota counter."""
        compact = self._flow_agent_error_match_text(value)
        return (
            ("agent failed" in compact and "try again" in compact)
            or ("tac nhan" in compact and ("that bai" in compact or "khong thanh cong" in compact) and "thu lai" in compact)
        )

    async def _mark_flow_profile_quota_limited(self, profile: FlowBrowserProfile, exc: Exception) -> None:
        self._flow_profile_quota_blocked_until = self._valid_flow_profile_quota_blocks(self._flow_profile_quota_blocked_until)
        self._flow_profile_quota_blocked_until[profile.key] = self._flow_profile_block_until()
        await self.store.replace_flow_profile_quota_blocks(self._flow_profile_quota_blocked_until)
        self._flow_profile_agent_retry_error_counts.pop(profile.key, None)
        self._flow_profile_agent_failed_job_counts.pop(profile.key, None)
        await self.store.replace_flow_profile_agent_retry_error_counts(self._flow_profile_agent_retry_error_counts)
        if self._shared_browser_profile_key == profile.key:
            await self._close_shared_browser()

    async def _record_flow_profile_agent_try_again_error(self, profile: FlowBrowserProfile, exc: Exception | str) -> int:
        self._flow_profile_agent_retry_error_counts = self._valid_flow_profile_agent_retry_counts(
            self._flow_profile_agent_retry_error_counts
        )
        next_count = int(self._flow_profile_agent_retry_error_counts.get(profile.key, 0) or 0) + 1
        self._flow_profile_agent_retry_error_counts[profile.key] = next_count
        await self.store.replace_flow_profile_agent_retry_error_counts(self._flow_profile_agent_retry_error_counts)
        return next_count

    async def _reset_flow_profile_agent_try_again_errors(self, profile: FlowBrowserProfile) -> None:
        if profile.key not in self._flow_profile_agent_retry_error_counts:
            return
        self._flow_profile_agent_retry_error_counts.pop(profile.key, None)
        await self.store.replace_flow_profile_agent_retry_error_counts(self._flow_profile_agent_retry_error_counts)

    def _same_flow_agent_quota_message(self, left: str, right: str) -> bool:
        left_norm = re.sub(r"\s+", " ", self._strip_accents(str(left or "")).lower()).strip()
        right_norm = re.sub(r"\s+", " ", self._strip_accents(str(right or "")).lower()).strip()
        if not left_norm or not right_norm:
            return False
        return left_norm == right_norm or left_norm in right_norm or right_norm in left_norm

    async def _raise_flow_agent_quota_if_visible(
        self,
        page: Any,
        *,
        job_id: str = "",
        ignore_message: str = "",
    ) -> None:
        message = await self._visible_flow_agent_quota_message(page)
        if not message:
            return
        if ignore_message and self._same_flow_agent_quota_message(message, ignore_message):
            if job_id:
                await self.store.append_log(
                    job_id,
                    "Flow Agent: bỏ qua thông báo quota đã có sẵn trong panel từ trước khi gửi prompt.",
                )
            return
        if job_id:
            await self.store.append_log(
                job_id,
                f"Flow Agent profile hiện tại đã hết quota: {message[:220]}. App sẽ chuyển sang Chrome profile khác nếu có.",
            )
        raise FlowAgentQuotaError(message)

    async def _raise_flow_agent_try_again_if_visible(
        self,
        page: Any,
        *,
        job_id: str = "",
        ignore_message: str = "",
    ) -> None:
        message = await self._visible_flow_agent_try_again_message(page)
        if not message:
            return
        if ignore_message and self._same_flow_agent_quota_message(message, ignore_message):
            return
        if job_id:
            await self.store.append_log(
                job_id,
                f"Flow Agent báo lỗi thử lại: {message[:220]}. App sẽ đếm lỗi này; đủ {self._flow_agent_try_again_threshold()} lần liên tiếp sẽ đổi acc.",
            )
        raise RuntimeError(message)

    async def _visible_flow_agent_quota_message(self, page: Any) -> str:
        try:
            text = await page.evaluate(
                """
                () => {
                  const bodyText = document.body ? document.body.innerText || "" : "";
                  const nodes = [...document.querySelectorAll('[role="alert"], [role="status"], div, span, p')];
                  const visibleTexts = nodes
                    .map((node) => {
                      const style = window.getComputedStyle(node);
                      const rect = node.getBoundingClientRect();
                      if (style.display === 'none' || style.visibility === 'hidden' || rect.width === 0 || rect.height === 0) {
                        return '';
                      }
                      return node.innerText || node.textContent || '';
                    })
                    .filter(Boolean)
                    .join('\\n');
                  return `${visibleTexts}\\n${bodyText}`;
                }
                """
            )
        except Exception:
            return ""

        raw = str(text or "").strip()
        if not raw:
            return ""
        lowered = self._strip_accents(raw).lower()
        quota_signals = (
            "tools agent quota",
            "flow agent quota",
            "quota limit",
            "come back tomorrow",
            "daily quota",
            "agent queries",
            "han muc",
        )
        if not any(signal in lowered for signal in quota_signals):
            return ""
        if "agent" not in lowered and "tools" not in lowered and "tac nhan" not in lowered:
            return ""

        lines = [line.strip() for line in raw.splitlines() if line.strip()]
        preferred = []
        for line in lines:
            normalized = self._strip_accents(line).lower()
            if any(signal in normalized for signal in quota_signals):
                preferred.append(line)
        message = " ".join(preferred[:3] or lines[:3]).strip()
        return message[:500] or "Google Flow Agent reported a quota limit."

    async def _visible_flow_agent_try_again_message(self, page: Any) -> str:
        try:
            text = await page.evaluate(
                """
                () => {
                  const visible = (node) => {
                    if (!node || !(node instanceof Element)) return false;
                    const style = window.getComputedStyle(node);
                    const rect = node.getBoundingClientRect();
                    return style.display !== 'none'
                      && style.visibility !== 'hidden'
                      && style.opacity !== '0'
                      && rect.width > 0
                      && rect.height > 0
                      && rect.bottom > 0
                      && rect.top < window.innerHeight;
                  };
                  const nodes = [...document.querySelectorAll('[role="alert"], [role="status"], button, div, span, p')];
                  return nodes
                    .filter(visible)
                    .map((node) => node.innerText || node.textContent || '')
                    .filter(Boolean)
                    .join('\\n');
                }
                """
            )
        except Exception:
            return ""

        raw = str(text or "").strip()
        if not raw:
            return ""
        normalized = self._flow_agent_error_match_text(raw)
        if not (
            ("xay ra loi" in normalized and "thu lai" in normalized)
            or ("da xay ra loi" in normalized and "hay thu lai" in normalized)
            or ("an error occurred" in normalized and "try again" in normalized)
            or ("something went wrong" in normalized and "try again" in normalized)
        ):
            return ""

        lines = [line.strip() for line in raw.splitlines() if line.strip()]
        preferred = []
        for line in lines:
            line_norm = self._flow_agent_error_match_text(line)
            if (
                ("xay ra loi" in line_norm and "thu lai" in line_norm)
                or ("da xay ra loi" in line_norm and "hay thu lai" in line_norm)
                or ("an error occurred" in line_norm and "try again" in line_norm)
                or ("something went wrong" in line_norm and "try again" in line_norm)
            ):
                preferred.append(line)
        message = " ".join(preferred[:2] or lines[:2]).strip()
        return message[:500] or "Flow Agent: Đã xảy ra lỗi. Hãy thử lại."

    async def _close_shared_browser(self) -> None:
        browser = self._shared_browser
        self._shared_browser = None
        self._shared_browser_profile_key = ""
        if browser is None:
            return
        try:
            await browser.stop()
        except Exception:
            pass

    async def _shared_browser_is_usable(self, profile: FlowBrowserProfile | None = None) -> bool:
        browser = self._shared_browser
        if browser is None or getattr(browser, "_ctx", None) is None:
            return False
        if profile is not None and self._shared_browser_profile_key != profile.key:
            return False
        try:
            page = await browser.page()
            if page.is_closed():
                return False
            await page.evaluate("() => document.readyState")
            return True
        except Exception:
            return False

    async def _ensure_shared_browser(self, profile: FlowBrowserProfile | None = None) -> Any:
        selected_profile = profile or self._current_flow_profile()
        if await self._shared_browser_is_usable(selected_profile):
            return self._shared_browser
        await self._close_shared_browser()
        self._ensure_playwright_browsers_available()
        BrowserManager, _, _, _, _ = self._flow_modules()
        try:
            selected_profile.path.mkdir(parents=True, exist_ok=True)
        except OSError:
            pass
        if self._mark_chrome_profile_clean_exit(selected_profile.path):
            logging.info("Cleared Chrome crash flag for profile %s before launch.", selected_profile.label)
        browser = BrowserManager(headless=False, profile_dir=selected_profile.path)
        await browser.start()
        config = self.store.snapshot().config
        project_id = self._flow_profile_project_id(selected_profile, self._normalize_project_id(config.project_id or config.project_url))
        target_url = self._project_url(project_id) if project_id else "https://labs.google/fx/tools/flow"
        await self._close_placeholder_flow_tabs(browser, target_url)
        self._shared_browser = browser
        self._shared_browser_profile_key = selected_profile.key
        return browser

    async def _build_client_from_shared_browser(
        self,
        browser: Any,
        *,
        project_id: str,
        workflow_id: str | None,
        timeout_s: int,
    ) -> Any:
        self._patch_flow_runtime_compat()
        from flow._api import FlowAPI
        from flow._client import FlowClient

        api = FlowAPI(browser, project_id=project_id, default_timeout_s=timeout_s)
        client = FlowClient(api, browser, project_id, workflow_id)
        client.workflow_id = workflow_id
        client._project_url = self._project_url(project_id)

        target_url = client._project_url
        await self._repair_placeholder_flow_tabs(browser, target_url)
        page = await self._acquire_fresh_flow_page(browser, target_url)
        await self._ensure_valid_flow_project_page(page, target_url)
        return client

    def _is_browser_closed_error(self, exc: Exception) -> bool:
        detail = str(exc or "").lower()
        needles = (
            "target page, context or browser has been closed",
            "browser has been closed",
            "context closed",
            "page closed",
        )
        return any(needle in detail for needle in needles)

    def _sync_project_to_flow_storage(self, config: AppConfig) -> None:
        project_id = self._normalize_project_id(config.project_id or config.project_url)
        if not project_id:
            return
        _, _, _, _, sync_project = self._flow_modules()
        sync_project(project_id, config.project_name or "web-ui", self._project_url(project_id))

    def _flow_modules(
        self,
        client_only: bool = False,
    ) -> Any:
        self._patch_flow_runtime_compat()
        from flow._client import FlowClient

        if client_only:
            return FlowClient, None, None, None, None

        from flow._browser import BrowserManager
        from flow._storage import add_project, get_active_project, is_authenticated, load_projects, set_active_project

        def sync_project(project_id: str, project_name: str, project_url: str) -> None:
            set_active_project(project_id, project_url)
            add_project(project_id, project_name, project_url)

        return BrowserManager, is_authenticated, load_projects, get_active_project, sync_project

    def _patch_flow_runtime_compat(self) -> None:
        if self.__class__._FLOW_RUNTIME_PATCHED:
            return

        from flow._api import FlowAPI, GeneratedImage, VideoJob, RECAPTCHA_SITE_KEY
        from flow._client import FlowClient
        from flow._flow_ui import FlowUI
        from flow._models import AspectRatio, GenerationMode
        from flow._ui_interceptor import UIInterceptor

        async def _compat_settings_visible(_self: Any, page: Any) -> bool:
            return bool(await page.evaluate(
                """
                () => {
                  const menus = [...document.querySelectorAll('[role="menu"]')];
                  return menus.some(el => {
                    const style = window.getComputedStyle(el);
                    const text = (el.textContent || '').trim().toLowerCase();
                    return style.display !== 'none'
                      && style.visibility !== 'hidden'
                      && (text.includes('image') || text.includes('hình ảnh') || text.includes('hinh anh'))
                      && text.includes('video')
                      && /x[1-4]/.test(text);
                  });
                }
                """
            ))

        async def _compat_find_create_options_trigger_index(page: Any) -> int:
            index = await page.evaluate(
                """
                () => {
                  const buttons = [...document.querySelectorAll('button[aria-haspopup="menu"]')];
                  const candidates = buttons
                    .map((button, index) => {
                      const text = (button.textContent || '').trim();
                      const rect = button.getBoundingClientRect();
                      const style = window.getComputedStyle(button);
                      return {
                        index,
                        text,
                        top: rect.top,
                        visible: rect.width > 0
                          && rect.height > 0
                          && style.display !== 'none'
                          && style.visibility !== 'hidden',
                      };
                    })
                    .filter(item => item.visible && /(x[1-4]|Nano Banana|Veo|Imagen|Video|Image|🍌)/i.test(item.text))
                    .sort((a, b) => a.top - b.top);
                  return candidates.length ? candidates[candidates.length - 1].index : -1;
                }
                """
            )
            try:
                return int(index)
            except Exception:
                return -1

        async def _compat_find_tabbed_menu_index(page: Any) -> int:
            index = await page.evaluate(
                """
                () => {
                  const menus = [...document.querySelectorAll('[role="menu"]')];
                  const candidates = menus
                    .map((menu, index) => {
                      const style = window.getComputedStyle(menu);
                      const rect = menu.getBoundingClientRect();
                      const tabs = [...menu.querySelectorAll('[role="tab"]')].filter((tab) => {
                        const tabStyle = window.getComputedStyle(tab);
                        const tabRect = tab.getBoundingClientRect();
                        return tabRect.width > 0
                          && tabRect.height > 0
                          && tabStyle.display !== 'none'
                          && tabStyle.visibility !== 'hidden';
                      });
                      return {
                        index,
                        top: rect.top,
                        visible: rect.width > 0
                          && rect.height > 0
                          && style.display !== 'none'
                          && style.visibility !== 'hidden',
                        tabCount: tabs.length,
                      };
                    })
                    .filter((item) => item.visible && item.tabCount > 0)
                    .sort((a, b) => a.top - b.top);
                  return candidates.length ? candidates[candidates.length - 1].index : -1;
                }
                """
            )
            try:
                return int(index)
            except Exception:
                return -1

        async def _compat_get_tabbed_menu(page: Any) -> Any | None:
            index = await _compat_find_tabbed_menu_index(page)
            if index < 0:
                return None
            return page.locator('[role="menu"]').nth(index)

        async def _compat_wait_for_new_call(
            interceptor: Any,
            start_index: int,
            endpoint_tail: str,
            *,
            timeout_s: float,
            fail_on_tails: Optional[List[str]] = None,
        ) -> Any:
            deadline = time.monotonic() + timeout_s
            seen_tails: List[str] = []
            fail_on = [str(item or "") for item in (fail_on_tails or []) if str(item or "")]
            best_match = None
            settle_deadline = 0.0

            def _response_weight(call: Any) -> int:
                if not isinstance(getattr(call, "resp", None), dict):
                    return 0
                resp = call.resp or {}
                return (
                    len(resp.get("jobs", []) or [])
                    + len(resp.get("media", []) or [])
                    + len(resp.get("workflows", []) or [])
                )

            while time.monotonic() < deadline:
                completed = [
                    call
                    for call in getattr(interceptor, "_calls", [])[start_index:]
                    if call.resp is not None
                ]
                if completed:
                    seen_tails = [str(call.tail or "") for call in completed]
                for call in reversed(completed):
                    tail = str(call.tail or "")
                    if any(fragment in tail for fragment in fail_on):
                        raise RuntimeError(
                            "Google Flow đã gửi nhầm endpoint cho thao tác hiện tại. "
                            f"Captured: {tail}"
                        )
                    if endpoint_tail not in tail:
                        continue
                    if call.status not in (200, 201):
                        message = ""
                        if isinstance(call.resp, dict):
                            message = str(((call.resp.get("error") or {}).get("message")) or "").strip()
                        raise RuntimeError(
                            f"{endpoint_tail} failed [{call.status}]: {message or tail}"
                        )
                    if best_match is None or _response_weight(call) >= _response_weight(best_match):
                        best_match = call
                        settle_deadline = time.monotonic() + 1.0
                if best_match is not None and time.monotonic() >= settle_deadline:
                    return best_match
                await asyncio.sleep(0.25)
            raise RuntimeError(
                f"Timed out ({timeout_s}s) waiting for {endpoint_tail}. Captured so far: {seen_tails}"
            )

        async def _compat_wait_for_video_submit_call(
            interceptor: Any,
            start_index: int,
            *,
            timeout_s: float,
            expect_start_image: bool,
        ) -> Any:
            deadline = time.monotonic() + timeout_s
            seen_tails: List[str] = []
            best_match = None
            settle_deadline = 0.0

            def _response_weight(call: Any) -> int:
                if not isinstance(getattr(call, "resp", None), dict):
                    return 0
                resp = call.resp or {}
                return (
                    len(resp.get("jobs", []) or [])
                    + len(resp.get("media", []) or [])
                    + len(resp.get("workflows", []) or [])
                )

            while time.monotonic() < deadline:
                completed = [
                    call
                    for call in getattr(interceptor, "_calls", [])[start_index:]
                    if call.resp is not None
                ]
                if completed:
                    seen_tails = [str(call.tail or "") for call in completed]

                for call in reversed(completed):
                    tail = str(call.tail or "")
                    normalized = tail.lower()
                    if "generatevideo" not in normalized:
                        continue
                    if call.status not in (200, 201):
                        continue
                    if expect_start_image and "text" in normalized:
                        raise RuntimeError(
                            "Google Flow đã gửi nhầm sang text-to-video. Ảnh đầu vào nhiều khả năng chưa được gắn vào Start."
                        )
                    if expect_start_image and not isinstance(getattr(call, "resp", None), dict):
                        continue
                    if expect_start_image and _response_weight(call) == 0:
                        continue
                    if best_match is None or _response_weight(call) >= _response_weight(best_match):
                        best_match = call
                        settle_deadline = time.monotonic() + 1.0

                if best_match is not None and time.monotonic() >= settle_deadline:
                    return best_match
                await asyncio.sleep(0.25)

            label = "image-to-video" if expect_start_image else "text-to-video"
            raise RuntimeError(
                f"Timed out ({timeout_s}s) waiting for {label} submit response. Captured so far: {seen_tails}"
            )

        async def _compat_click_menu_trigger(page: Any) -> bool:
            index = await _compat_find_create_options_trigger_index(page)
            if index < 0:
                return False
            trigger = page.locator('button[aria-haspopup="menu"]').nth(index)
            try:
                await trigger.click(force=True)
            except Exception:
                return False
            await asyncio.sleep(0.5)
            return True

        async def _compat_open_settings_panel(_self: Any, page: Any) -> bool:
            try:
                await page.wait_for_selector("button", timeout=8000)
            except Exception:
                pass
            await asyncio.sleep(0.5)

            if await _compat_settings_visible(_self, page):
                return True

            if await _compat_click_menu_trigger(page):
                await asyncio.sleep(1.0)
                if await _compat_settings_visible(_self, page):
                    return True

            return False

        async def _compat_click_menu_tab(page: Any, labels: List[str]) -> bool:
            menu = await _compat_get_tabbed_menu(page)
            if menu is None:
                return False
            for label in labels:
                wanted = str(label or "").strip().lower()
                tabs = menu.locator('[role="tab"]')
                count = await tabs.count()
                matched = False
                for index in range(count):
                    tab = tabs.nth(index)
                    try:
                        box = await tab.bounding_box()
                    except Exception:
                        box = None
                    if not box:
                        continue
                    text = str(await tab.text_content() or "").replace("\n", " ").strip().lower()
                    if wanted not in text:
                        continue
                    try:
                        await tab.click(force=True)
                    except Exception:
                        continue
                    matched = True
                    break
                if not matched:
                    continue
                await asyncio.sleep(0.45)
                selected_tabs = menu.locator('[role="tab"][aria-selected="true"]')
                selected_count = await selected_tabs.count()
                for selected_index in range(selected_count):
                    text = str(await selected_tabs.nth(selected_index).text_content() or "").replace("\n", " ").strip().lower()
                    if wanted in text:
                        return True
            return False

        async def _compat_click_visible_surface_control(page: Any, labels: List[str]) -> bool:
            wanted_labels = [str(label or "").strip() for label in labels if str(label or "").strip()]
            if not wanted_labels:
                return False

            locators = []
            for label in wanted_labels:
                pattern = re.compile(re.escape(label), re.I)
                locators.extend(
                    [
                        page.locator('[role="tab"]').filter(has_text=pattern),
                        page.locator('button').filter(has_text=pattern),
                        page.locator('[role="button"]').filter(has_text=pattern),
                        page.locator('div[type="button"]').filter(has_text=pattern),
                    ]
                )

            for locator in locators:
                candidate = await _compat_visible_locator(locator)
                if candidate is None:
                    continue
                try:
                    await candidate.scroll_into_view_if_needed()
                except Exception:
                    pass
                try:
                    await candidate.click(force=True)
                    await asyncio.sleep(0.5)
                    return True
                except Exception:
                    continue
            return False

        async def _compat_click_visible_menu_item(page: Any, wanted: str) -> bool:
            wanted = str(wanted or "").strip().lower()
            items = page.locator('[role="menuitem"]')
            count = await items.count()
            for index in range(count):
                item = items.nth(index)
                try:
                    box = await item.bounding_box()
                except Exception:
                    box = None
                if not box:
                    continue
                text = str(await item.text_content() or "").replace("\n", " ").strip().lower()
                if wanted not in text:
                    continue
                try:
                    await item.click(force=True)
                    return True
                except Exception:
                    continue
            return False

        async def _compat_fill_prompt(_self: Any, page: Any, prompt: str) -> bool:
            prompt = str(prompt or "").strip()
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.2)
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.2)
            except Exception:
                pass

            best = None
            best_is_input = False
            best_y = -1.0
            for selector, is_input in (
                ('div[role="textbox"][contenteditable="true"]', False),
                ('div[data-slate-editor="true"][contenteditable="true"]', False),
                ('div[contenteditable="true"]', False),
                ('textarea', True),
                ('input[type="text"]', True),
            ):
                locator = page.locator(selector)
                count = await locator.count()
                for index in range(count):
                    candidate = locator.nth(index)
                    try:
                        box = await candidate.bounding_box()
                    except Exception:
                        box = None
                    if not box:
                        continue
                    if box["width"] < 240 or box["height"] < 18 or box["y"] < 300:
                        continue
                    if box["y"] >= best_y:
                        best = candidate
                        best_is_input = is_input
                        best_y = float(box["y"])

            if best is None:
                return False

            await best.scroll_into_view_if_needed()
            await asyncio.sleep(0.1)
            await best.click(force=True)
            await asyncio.sleep(0.2)

            if best_is_input:
                try:
                    await best.fill(prompt)
                except Exception:
                    return False
                try:
                    value = await best.input_value()
                except Exception:
                    value = await best.text_content()
                return prompt[:20] in str(value or "")

            try:
                await page.keyboard.press("Meta+a")
                await page.keyboard.press("Control+a")
                await asyncio.sleep(0.05)
                await page.keyboard.press("Backspace")
                await asyncio.sleep(0.05)
                await page.keyboard.insert_text(prompt)
                await asyncio.sleep(0.2)
                content = await best.text_content()
                if prompt[:20] in str(content or ""):
                    return True
            except Exception:
                pass

            try:
                injected = await best.evaluate(
                    """
                    (el, value) => {
                      el.focus();
                      if (el instanceof HTMLInputElement || el instanceof HTMLTextAreaElement) {
                        el.value = value;
                      } else {
                        const paragraph = el.querySelector('[data-slate-node="element"]') || el.firstElementChild || el;
                        if (paragraph) {
                          paragraph.textContent = value;
                        }
                      }
                      el.dispatchEvent(new Event('input', { bubbles: true }));
                      el.dispatchEvent(new Event('change', { bubbles: true }));
                      return (el.textContent || el.value || '').trim();
                    }
                    """,
                    prompt,
                )
            except Exception:
                return False
            return prompt[:20] in str(injected or "")

        async def _compat_switch_mode(_self: Any, page: Any, mode: Any) -> bool:
            await _compat_open_settings_panel(_self, page)
            label_map = {
                GenerationMode.IMAGE: ["Image", "Hình ảnh", "Hinh anh"],
                GenerationMode.VIDEO: ["Video"],
                GenerationMode.FRAME_TO_VIDEO: ["Frames", "Frame", "Khung hình", "Khung"],
            }
            target_labels = label_map.get(mode, [])
            if await _compat_click_menu_tab(page, target_labels):
                return True

            if mode == GenerationMode.FRAME_TO_VIDEO:
                video_labels = label_map.get(GenerationMode.VIDEO, [])
                if await _compat_click_visible_surface_control(page, video_labels):
                    await _compat_open_settings_panel(_self, page)
                    if await _compat_click_menu_tab(page, target_labels):
                        return True
                if await _compat_click_visible_surface_control(page, target_labels):
                    return True
                await _compat_open_settings_panel(_self, page)
                return await _compat_click_menu_tab(page, target_labels)

            if await _compat_click_visible_surface_control(page, target_labels):
                return True

            await _compat_open_settings_panel(_self, page)
            return await _compat_click_menu_tab(page, target_labels)

        async def _compat_set_aspect_ratio(_self: Any, page: Any, ratio: Any) -> bool:
            await _compat_open_settings_panel(_self, page)
            label_map = {
                AspectRatio.LANDSCAPE: ["16:9", "Landscape"],
                AspectRatio.PORTRAIT: ["9:16", "Portrait"],
                AspectRatio.SQUARE: ["1:1", "Square"],
            }
            return await _compat_click_menu_tab(page, label_map.get(ratio, []))

        async def _compat_set_count(_self: Any, page: Any, count: int) -> bool:
            await _compat_open_settings_panel(_self, page)
            return await _compat_click_menu_tab(page, [f"x{max(1, min(self.FLOW_AGENT_TARGET_OUTPUT_COUNT, count))}"])

        async def _compat_get_video_model_selector(_self: Any, page: Any) -> str:
            await _compat_open_settings_panel(_self, page)
            menu = await _compat_get_tabbed_menu(page)
            if menu is None:
                return ""
            button = menu.locator('button[aria-haspopup="menu"]').first
            if await button.count() > 0:
                return str((await button.text_content()) or "").replace("arrow_drop_down", "").strip()
            for label in ["Veo", "Nano Banana", "Imagen"]:
                locator = menu.locator("button").filter(has_text=label).first
                if await locator.count() > 0:
                    return str((await locator.text_content()) or "").replace("arrow_drop_down", "").strip()
            return ""

        async def _compat_select_video_model(_self: Any, page: Any, model_display_name: str) -> bool:
            await _compat_open_settings_panel(_self, page)
            menu = await _compat_get_tabbed_menu(page)
            if menu is None:
                return False
            current = await _compat_get_video_model_selector(_self, page)
            wanted = str(model_display_name or "").strip()
            if wanted and wanted.lower() in current.lower():
                return True

            model_button = menu.locator('button[aria-haspopup="menu"]').first
            if await model_button.count() > 0:
                await model_button.click(force=True)
                await asyncio.sleep(0.5)

            if not wanted:
                return bool(await _compat_get_video_model_selector(_self, page))

            matched = await _compat_click_visible_menu_item(page, wanted)
            if matched:
                await asyncio.sleep(0.5)
                return True
            return False

        async def _compat_get_image_model_selector(_self: Any, page: Any) -> str:
            await _compat_open_settings_panel(_self, page)
            menu = await _compat_get_tabbed_menu(page)
            if menu is None:
                return ""
            button = menu.locator('button[aria-haspopup="menu"]').first
            if await button.count() > 0:
                return str((await button.text_content()) or "").replace("arrow_drop_down", "").strip()
            for label in ["Nano Banana", "Imagen"]:
                locator = menu.locator("button").filter(has_text=label).first
                if await locator.count() > 0:
                    return str((await locator.text_content()) or "").replace("arrow_drop_down", "").strip()
            return ""

        async def _compat_select_image_model(_self: Any, page: Any, model_display_name: str) -> bool:
            await _compat_open_settings_panel(_self, page)
            menu = await _compat_get_tabbed_menu(page)
            if menu is None:
                return False
            current = await _compat_get_image_model_selector(_self, page)
            wanted = str(model_display_name or "").strip()
            if wanted and wanted.lower() in current.lower():
                return True

            model_button = menu.locator('button[aria-haspopup="menu"]').first
            if await model_button.count() > 0:
                await model_button.click(force=True)
                await asyncio.sleep(0.5)

            if not wanted:
                return bool(await _compat_get_image_model_selector(_self, page))

            matched = await _compat_click_visible_menu_item(page, wanted)
            if matched:
                await asyncio.sleep(0.5)
                return True
            return False

        async def _compat_upload_via_file_input(page: Any, image_path: str) -> bool:
            selectors = [
                'input[type="file"][accept*="image"]',
                'input[type="file"]',
            ]
            for selector in selectors:
                locator = page.locator(selector)
                count = await locator.count()
                for index in range(count):
                    candidate = locator.nth(index)
                    try:
                        await candidate.set_input_files(image_path)
                        return True
                    except Exception:
                        continue
            return False

        async def _compat_visible_locator(locator: Any) -> Any | None:
            try:
                count = await locator.count()
            except Exception:
                return None
            for index in range(count):
                candidate = locator.nth(index)
                try:
                    box = await candidate.bounding_box()
                except Exception:
                    box = None
                if not box or box["width"] < 16 or box["height"] < 16:
                    continue
                try:
                    disabled = await candidate.evaluate(
                        """
                        (el) => {
                          const node = el instanceof HTMLElement ? el : el.closest('*');
                          if (!node) return false;
                          const style = window.getComputedStyle(node);
                          return node.hasAttribute('disabled')
                            || node.getAttribute('aria-disabled') === 'true'
                            || style.pointerEvents === 'none';
                        }
                        """
                    )
                except Exception:
                    disabled = False
                if disabled:
                    continue
                return candidate
            return None

        async def _compat_start_trigger(page: Any) -> Any | None:
            locators = [
                page.locator('[aria-label*="Bắt đầu" i]'),
                page.locator('[aria-label*="Bat dau" i]'),
                page.locator('[aria-label*="Start image" i]'),
                page.locator('[aria-label*="Start frame" i]'),
                page.locator('[aria-label*="Add image" i]'),
                page.locator('[aria-label*="Add media" i]'),
                page.locator('[aria-label*="Start" i]'),
                page.locator('[aria-label*="frame" i]'),
                page.locator('button').filter(has_text=re.compile(r"^Bắt đầu$|^Bat dau$", re.I)),
                page.locator('button').filter(has_text=re.compile(r"^Start image$", re.I)),
                page.locator('button').filter(has_text=re.compile(r"^Start frame$", re.I)),
                page.locator('button').filter(has_text=re.compile(r"^Add image$", re.I)),
                page.locator('button').filter(has_text=re.compile(r"^Add Media$", re.I)),
                page.locator('button').filter(has_text=re.compile(r"^Start$", re.I)),
                page.locator('[role="button"]').filter(has_text=re.compile(r"^Bắt đầu$|^Bat dau$", re.I)),
                page.locator('[role="button"]').filter(has_text=re.compile(r"^Start$", re.I)),
                page.locator('[role="button"]').filter(has_text=re.compile(r"^Add image$", re.I)),
                page.locator('[role="button"]').filter(has_text=re.compile(r"^Add Media$", re.I)),
                page.locator('div[type="button"]').filter(has_text=re.compile(r"^Bắt đầu$|^Bat dau$", re.I)),
                page.locator('div[type="button"]').filter(has_text=re.compile(r"^Start$", re.I)),
                page.get_by_text("Bắt đầu", exact=True),
                page.get_by_text("Bat dau", exact=True),
                page.get_by_text("Start", exact=True),
            ]
            for locator in locators:
                candidate = await _compat_visible_locator(locator)
                if candidate is not None:
                    return candidate
            return None

        async def _compat_open_start_dialog(page: Any) -> Any | None:
            deadline = time.monotonic() + 8.0
            while time.monotonic() < deadline:
                existing = page.locator('[role="dialog"]').last
                if await existing.count() > 0:
                    return existing

                trigger = await _compat_start_trigger(page)
                if trigger is not None:
                    try:
                        await trigger.scroll_into_view_if_needed()
                    except Exception:
                        pass
                    try:
                        await trigger.click(force=True)
                    except Exception:
                        await asyncio.sleep(0.4)
                    try:
                        await page.wait_for_selector('[role="dialog"]', timeout=1500)
                    except Exception:
                        await asyncio.sleep(0.4)
                        continue
                    return page.locator('[role="dialog"]').last
                await asyncio.sleep(0.5)
            return None

        async def _compat_first_start_image_option(dialog: Any) -> Any | None:
            selectors = [
                '[data-index]',
                '[data-item-index]',
                'button:has(img)',
                '[role="button"]:has(img)',
                'img[alt]',
            ]
            for selector in selectors:
                locator = dialog.locator(selector)
                count = await locator.count()
                for index in range(count):
                    candidate = locator.nth(index)
                    try:
                        box = await candidate.bounding_box()
                    except Exception:
                        box = None
                    if not box or box["width"] < 48 or box["height"] < 48:
                        continue
                    return candidate
            return None

        async def _compat_confirm_start_dialog(page: Any, dialog: Any) -> bool:
            labels = ["Use", "Select", "Done", "Add", "Choose", "Dùng", "Chọn", "Xong", "Thêm"]
            for label in labels:
                locator = dialog.locator("button").filter(has_text=label)
                count = await locator.count()
                for index in range(count):
                    button = locator.nth(index)
                    try:
                        box = await button.bounding_box()
                    except Exception:
                        box = None
                    if not box:
                        continue
                    try:
                        await button.click(force=True)
                    except Exception:
                        continue
                    await asyncio.sleep(0.35)
                    if await page.locator('[role="dialog"]').count() == 0:
                        return True
            try:
                await page.keyboard.press("Enter")
                await asyncio.sleep(0.25)
            except Exception:
                pass
            return await page.locator('[role="dialog"]').count() == 0

        async def _compat_describe_start_dialog(dialog: Any) -> str:
            try:
                text = re.sub(r"\s+", " ", str(await dialog.text_content() or "")).strip()
            except Exception:
                text = ""
            try:
                button_count = await dialog.locator("button").count()
            except Exception:
                button_count = 0
            try:
                image_count = await dialog.locator("img").count()
            except Exception:
                image_count = 0
            summary = f"dialog buttons={button_count}, images={image_count}"
            if text:
                return f"{summary}, text='{text[:220]}'"
            return summary

        async def _compat_find_start_image_option(dialog: Any, image_name: str) -> Any | None:
            search = dialog.locator('input[type="text"]').first
            search_terms = self._start_image_search_terms(image_name)
            if not search_terms:
                search_terms = [str(image_name or "").strip()]

            for term in search_terms:
                if await search.count() > 0:
                    try:
                        await search.fill(term)
                        await asyncio.sleep(0.4)
                    except Exception:
                        pass

                candidates = [
                    dialog.locator('[data-index]').filter(has_text=term).last,
                    dialog.locator('[data-item-index]').filter(has_text=term).last,
                    dialog.locator('[role="button"]').filter(has_text=term).last,
                    dialog.locator("button").filter(has_text=term).last,
                    dialog.get_by_text(term, exact=True).last,
                ]
                for candidate in candidates:
                    try:
                        if await candidate.count() > 0:
                            return candidate
                    except Exception:
                        continue

                image_candidates = dialog.locator("img[alt]")
                image_count = await image_candidates.count()
                for index in range(image_count):
                    candidate = image_candidates.nth(index)
                    try:
                        alt_text = str(await candidate.get_attribute("alt") or "").strip()
                    except Exception:
                        alt_text = ""
                    haystack = " ".join(self._start_image_search_terms(alt_text))
                    if term.lower() and term.lower() in haystack.lower():
                        return candidate

            if await search.count() > 0:
                try:
                    await search.fill("")
                    await asyncio.sleep(0.2)
                except Exception:
                    pass

            return await _compat_first_start_image_option(dialog)

        async def _compat_close_dialog(page: Any) -> None:
            if await page.locator('[role="dialog"]').count() == 0:
                return
            try:
                await page.keyboard.press("Escape")
                await asyncio.sleep(0.3)
            except Exception:
                pass

        async def _compat_wait_for_uploaded_image(page: Any, image_name: str, *, timeout_s: float = 18.0) -> bool:
            deadline = time.monotonic() + timeout_s
            while time.monotonic() < deadline:
                dialog = await _compat_open_start_dialog(page)
                if dialog is not None:
                    option = await _compat_find_start_image_option(dialog, image_name)
                    await _compat_close_dialog(page)
                    if option is not None:
                        return True
                await asyncio.sleep(1.0)
            return False

        async def _compat_wait_for_project_media_name(client_self: Any, known_media: set[str], *, timeout_s: float = 8.0) -> str:
            deadline = time.monotonic() + timeout_s
            while time.monotonic() < deadline:
                try:
                    data = await client_self._api.get_project_data()
                except Exception:
                    data = {}
                for workflow in data.get("projectContents", {}).get("workflows", []) or []:
                    media_name = str((workflow.get("metadata") or {}).get("primaryMediaId") or "").strip()
                    if media_name and media_name not in known_media:
                        return media_name
                    for media in workflow.get("medias", []) or []:
                        media_name = str(media.get("name") or "").strip()
                        if media_name and media_name not in known_media:
                            return media_name
                await asyncio.sleep(0.8)
            return ""

        def _compat_parse_video_jobs_from_project_data(
            client_self: Any,
            project_data: Dict[str, Any],
            known_media: set[str],
        ) -> list[Any]:
            jobs: List[Any] = []
            seen_media: set[str] = set()
            workflows = project_data.get("projectContents", {}).get("workflows", []) or []
            for workflow in workflows:
                workflow_id = str(workflow.get("name") or "").strip()
                metadata = workflow.get("metadata", {}) or {}
                candidate_media: List[str] = []
                primary_media_id = str(metadata.get("primaryMediaId") or "").strip()
                if primary_media_id:
                    candidate_media.append(primary_media_id)
                for media in workflow.get("medias", []) or []:
                    media_name = str(media.get("name") or "").strip()
                    if media_name:
                        candidate_media.append(media_name)
                for media_name in candidate_media:
                    if not media_name or media_name in known_media or media_name in seen_media:
                        continue
                    seen_media.add(media_name)
                    job = VideoJob.__new__(VideoJob)
                    job.media_name = media_name
                    job.status = "PENDING"
                    job.project_id = client_self.project_id
                    job.workflow_id = workflow_id
                    jobs.append(job)
            return jobs

        async def _compat_wait_for_video_jobs_from_project(
            client_self: Any,
            known_media: set[str],
            *,
            target_count: int,
            timeout_s: float,
        ) -> list[Any]:
            deadline = time.monotonic() + timeout_s
            while time.monotonic() < deadline:
                try:
                    data = await client_self._api.get_project_data()
                except Exception:
                    data = {}
                jobs = _compat_parse_video_jobs_from_project_data(client_self, data, known_media)
                if len(jobs) >= target_count:
                    return jobs[:target_count]
                await asyncio.sleep(1.0)
            return []

        async def _compat_upload_project_image(client_self: Any, page: Any, image_path: str) -> dict[str, str]:
            image_file = Path(str(image_path or "")).expanduser().resolve()
            file_name = image_file.name.strip()
            if not file_name:
                raise RuntimeError("Chưa nhận được đường dẫn ảnh đầu vào hợp lệ.")
            if not image_file.exists():
                raise RuntimeError("Không tìm thấy ảnh đầu vào trên máy để tải lên Flow.")

            known_media: set[str] = set()
            try:
                known_media = self._project_media_names(await client_self._api.get_project_data())
            except Exception:
                known_media = set()

            uploaded = await _compat_upload_via_file_input(page, str(image_file))
            if not uploaded:
                for trigger in (
                    page.locator("button").filter(has_text="Add Media").first,
                    page.get_by_text("Add Media", exact=True).first,
                    page.locator("button").filter(has_text="Upload image").first,
                    page.get_by_text("Upload image", exact=True).first,
                ):
                    try:
                        if await trigger.count() > 0:
                            await trigger.click(force=True)
                            await asyncio.sleep(0.5)
                            uploaded = await _compat_upload_via_file_input(page, str(image_file))
                            if uploaded:
                                break
                    except Exception:
                        continue

            if not uploaded:
                raise RuntimeError("Google Flow chưa tải được ảnh đầu vào lên project.")

            media_name = await _compat_wait_for_project_media_name(client_self, known_media)
            await asyncio.sleep(1.0)
            return {"file_name": file_name, "media_name": media_name}

        async def _compat_attach_start_frame(page: Any, image_name: str, media_name: str = "") -> tuple[bool, str]:
            dialog = await _compat_open_start_dialog(page)
            if dialog is None:
                return False, "Không mở được dialog Start."
            row = await _compat_find_start_image_option(dialog, image_name)
            if row is None and media_name:
                row = await _compat_find_start_image_option(dialog, media_name)
            if row is None:
                search = dialog.locator('input[type="text"]').first
                if await search.count() > 0:
                    await search.fill("")
                    await asyncio.sleep(0.3)
                    row = await _compat_find_start_image_option(dialog, image_name)
                    if row is None and media_name:
                        row = await _compat_find_start_image_option(dialog, media_name)
            if row is None:
                row = await _compat_first_start_image_option(dialog)
                if row is None:
                    await _compat_close_dialog(page)
                    return False, await _compat_describe_start_dialog(dialog)

            click_attempts = [
                (
                    "closest-clickable",
                    lambda: row.evaluate(
                        """(el) => {
                            const target = el.closest('button, [role="button"], [data-index], [data-item-index]') || el;
                            target.click();
                        }"""
                    ),
                ),
                ("row", lambda: row.click(force=True)),
                ("row-double", lambda: row.dblclick(force=True)),
                ("image", lambda: row.locator("img").first.click(force=True)),
                ("first-child", lambda: row.evaluate("(el) => (el.firstElementChild || el).click()")),
                (
                    "dispatch-events",
                    lambda: row.evaluate(
                        """(el) => {
                            const target = el.closest('button, [role="button"], [data-index], [data-item-index]') || el;
                            ['mousedown','mouseup','click','dblclick'].forEach((type) => {
                                target.dispatchEvent(new MouseEvent(type, { bubbles: true, cancelable: true, view: window }));
                            });
                        }"""
                    ),
                ),
            ]
            for _, action in click_attempts:
                try:
                    await action()
                except Exception:
                    continue
                try:
                    await page.wait_for_function(
                        "() => !document.querySelector('[role=\"dialog\"]')",
                        timeout=5000,
                    )
                except Exception:
                    pass
                await asyncio.sleep(0.5)
                if await page.locator('[role="dialog"]').count() == 0:
                    return True, ""
                if await _compat_confirm_start_dialog(page, dialog):
                    return True, ""
                dialog = page.locator('[role="dialog"]').last
            try:
                detail = await _compat_describe_start_dialog(dialog)
                await _compat_close_dialog(page)
            except Exception:
                detail = ""
            return False, detail

        async def _compat_generate_video(
            client_self: Any,
            prompt: str,
            *,
            model: str = "Veo 3.1 - Fast",
            aspect: str = "landscape",
            count: int = 1,
            start_image: str | None = None,
            workflow_id: str | None = None,
            timeout_s: int = 120,
        ) -> list[Any]:
            page = await client_self._bm.page()
            await client_self._ensure_project_page(page)

            interceptor = UIInterceptor()
            interceptor.attach(page)
            target_count = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(count or 1)))

            mode = GenerationMode.FRAME_TO_VIDEO if start_image else GenerationMode.VIDEO
            ratio = AspectRatio.PORTRAIT if aspect == "portrait" else AspectRatio.LANDSCAPE

            await client_self._ui.open_settings_panel(page)
            switched = await client_self._ui.switch_mode(page, mode)
            if start_image and not switched:
                raise RuntimeError(
                    "Google Flow chưa chuyển được sang chế độ video từ ảnh (Frames), nên ảnh đầu vào chưa thể được gắn vào Start."
                )
            await client_self._ui.select_video_model(page, model)
            await client_self._ui.set_aspect_ratio(page, ratio)
            await client_self._ui.set_count(page, target_count)
            await client_self._ui.fill_prompt(page, prompt)
            uploaded_image_info: dict[str, str] = {"file_name": "", "media_name": ""}
            if start_image:
                uploaded_image_info = await _compat_upload_project_image(client_self, page, start_image)
            if uploaded_image_info.get("file_name") or uploaded_image_info.get("media_name"):
                attached, attach_detail = await _compat_attach_start_frame(
                    page,
                    uploaded_image_info.get("file_name", ""),
                    uploaded_image_info.get("media_name", ""),
                )
                if not attached:
                    # Flow thay đổi UI khá thất thường: có lúc upload xong là ảnh đã tự gắn vào Start
                    # mà không còn mở dialog theo đường cũ nữa. Đừng fail sớm ở đây; hãy thử submit
                    # thật và bắt đúng endpoint i2v để biết ảnh có được gắn hay không.
                    await asyncio.sleep(0.75)

            try:
                known_media_before_submit = self._project_media_names(await client_self._api.get_project_data())
            except Exception:
                known_media_before_submit = set()

            call_start = len(getattr(interceptor, "_calls", []))
            await client_self._ui.click_submit(page)
            jobs: list[Any] = []
            submit_error: Exception | None = None
            if start_image:
                submit_task = asyncio.create_task(
                    _compat_wait_for_video_submit_call(
                        interceptor,
                        call_start,
                        timeout_s=timeout_s,
                        expect_start_image=True,
                    )
                )
                project_task = asyncio.create_task(
                    _compat_wait_for_video_jobs_from_project(
                        client_self,
                        known_media_before_submit,
                        target_count=target_count,
                        timeout_s=min(timeout_s, 120),
                    )
                )
                done, pending = await asyncio.wait(
                    {submit_task, project_task},
                    return_when=asyncio.FIRST_COMPLETED,
                )
                for task in pending:
                    task.cancel()
                for task in done:
                    try:
                        result = task.result()
                    except Exception as exc:
                        submit_error = exc
                        continue
                    if isinstance(result, list):
                        jobs = result
                    else:
                        jobs = _compat_parse_video_jobs(client_self, result.resp)
                    break
                if not jobs and submit_error is not None:
                    raise submit_error
            else:
                entry = await _compat_wait_for_video_submit_call(
                    interceptor,
                    call_start,
                    timeout_s=timeout_s,
                    expect_start_image=False,
                )
                jobs = _compat_parse_video_jobs(client_self, entry.resp)
            if not jobs:
                raise RuntimeError("Google Flow chưa khởi tạo được clip video nào từ yêu cầu này.")
            if len(jobs) < target_count:
                raise RuntimeError(
                    f"Google Flow chỉ khởi tạo {len(jobs)}/{target_count} clip trong một lượt gửi. "
                    "Em dừng tại đây để tránh bấm thêm và tạo dư clip ngoài ý muốn. Hãy thử chạy lại."
                )
            return jobs[:target_count]

        async def _compat_ensure_project_page(client_self: Any, page: Any = None) -> None:
            if page is None:
                page = await client_self._bm.page()
            if client_self.project_id in str(page.url or ""):
                return
            try:
                await page.goto(
                    client_self._project_url,
                    wait_until="domcontentloaded",
                    timeout=60_000,
                )
            except Exception:
                await page.goto(
                    client_self._project_url,
                    wait_until="commit",
                    timeout=60_000,
                )
            await asyncio.sleep(2.5)

        async def _compat_generate_image(
            client_self: Any,
            prompt: str,
            *,
            model: str = "Nano Banana Pro",
            aspect: str = "landscape",
            count: int = 1,
            reference_images: Optional[list[str]] = None,
            timeout_s: int = 120,
        ) -> list[Any]:
            page = await client_self._bm.page()
            await client_self._ensure_project_page(page)

            interceptor = UIInterceptor()
            interceptor.attach(page)
            target_count = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(count or 1)))

            ratio = (
                AspectRatio.PORTRAIT
                if "port" in str(aspect or "").lower()
                else AspectRatio.SQUARE
                if "square" in str(aspect or "").lower()
                else AspectRatio.LANDSCAPE
            )
            images: List[Any] = []
            attempts = 0
            max_attempts = max(target_count, 1) + 1
            while len(images) < target_count and attempts < max_attempts:
                remaining = target_count - len(images)
                batch_target = max(1, min(self._flow_agent_max_images_per_run(), remaining))
                attempts += 1

                try:
                    known_media_before_submit = self._project_media_names(await client_self._api.get_project_data())
                except Exception:
                    known_media_before_submit = set()

                await client_self._ui.open_settings_panel(page)
                switched = await client_self._ui.switch_mode(page, GenerationMode.IMAGE)
                if not switched:
                    raise RuntimeError("Google Flow chưa chuyển sang chế độ tạo ảnh.")
                await client_self._ui.select_image_model(page, model)
                await client_self._ui.set_aspect_ratio(page, ratio)
                await client_self._ui.set_count(page, batch_target)
                await client_self._ui.fill_prompt(page, prompt)
                call_start = len(getattr(interceptor, "_calls", []))
                clicked = await client_self._ui.click_submit(page)
                if not clicked:
                    raise RuntimeError("Google Flow chưa bấm được nút tạo ảnh.")

                endpoint_task = asyncio.create_task(
                    _compat_wait_for_new_call(
                        interceptor,
                        call_start,
                        "batchGenerateImages",
                        timeout_s=max(30, timeout_s),
                        fail_on_tails=["batchAsyncGenerateVideo"],
                    )
                )
                project_task = asyncio.create_task(
                    self._wait_for_new_project_images(
                        client_self,
                        known_media_before_submit,
                        prompt=prompt,
                        target_count=batch_target,
                        timeout_s=max(30, timeout_s),
                    )
                )

                batch_images: List[Any] = []
                errors: List[Exception] = []
                pending = {endpoint_task, project_task}
                while pending and not batch_images:
                    done, pending = await asyncio.wait(pending, return_when=asyncio.FIRST_COMPLETED)
                    for task in done:
                        try:
                            result = task.result()
                        except Exception as exc:
                            errors.append(exc)
                            continue
                        if isinstance(result, list):
                            batch_images = result
                        else:
                            batch_images = _compat_parse_images(result.resp)
                        if batch_images:
                            break

                for task in pending:
                    task.cancel()

                if not batch_images:
                    if errors:
                        raise errors[-1]
                    raise RuntimeError("Google Flow không trả ảnh nào về từ yêu cầu hiện tại.")
                images.extend(batch_images)

            return images[:target_count]

        def _compat_parse_images(payload: Any) -> list[Any]:
            response = payload if isinstance(payload, dict) else {}
            images: List[Any] = []

            media_items = response.get("media", []) or []
            if media_items:
                for media_item in media_items:
                    if not isinstance(media_item, dict):
                        continue
                    image = GeneratedImage.__new__(GeneratedImage)
                    image._raw = media_item
                    image.media_name = str(media_item.get("name") or media_item.get("mediaName") or "").strip()
                    image.project_id = str(media_item.get("projectId") or "").strip()
                    image.workflow_id = str(media_item.get("workflowId") or "").strip()
                    generated = ((media_item.get("image") or {}).get("generatedImage") or {})
                    image.fife_url = str(
                        generated.get("fifeUrl")
                        or generated.get("url")
                        or media_item.get("fifeUrl")
                        or ""
                    ).strip()
                    image.seed = generated.get("seed", 0)
                    image.model = str(generated.get("modelNameType") or generated.get("model") or "").strip()
                    image.prompt = str(generated.get("prompt") or "").strip()
                    image.dimensions = media_item.get("dimensions", {}) or {}
                    image.file_path = None
                    images.append(image)
                if images:
                    return images

            generated_items = response.get("generatedImages", []) or []
            for item in generated_items:
                if not isinstance(item, dict):
                    continue
                image = GeneratedImage.__new__(GeneratedImage)
                image._raw = item
                image.media_name = str(item.get("mediaName") or item.get("name") or "").strip()
                image.project_id = ""
                image.workflow_id = ""
                image.fife_url = str(item.get("fifeUrl") or item.get("url") or "").strip()
                image.seed = int(item.get("seed", 0) or 0)
                image.model = str(item.get("modelNameType") or item.get("model") or "").strip()
                image.prompt = str(item.get("prompt") or "").strip()
                image.dimensions = item.get("dimensions", {}) or {}
                image.file_path = None
                images.append(image)
            return images

        def _compat_parse_video_jobs(client_self: Any, payload: Any) -> list[Any]:
            response = payload if isinstance(payload, dict) else {}
            jobs: List[Any] = []

            workflows_by_media: Dict[str, str] = {}
            for media_item in response.get("media", []) or []:
                media_name = str(media_item.get("name") or media_item.get("mediaName") or "").strip()
                workflow_id = str(media_item.get("workflowId") or "").strip()
                if media_name and workflow_id:
                    workflows_by_media[media_name] = workflow_id

            if not workflows_by_media:
                for job_data in response.get("jobs", []) or []:
                    media_id = job_data.get("mediaId", {}) if isinstance(job_data, dict) else {}
                    media_name = str(media_id.get("mediaName") or media_id.get("name") or "").strip()
                    workflow_id = str(job_data.get("workflowId") or "").strip()
                    if media_name and workflow_id:
                        workflows_by_media[media_name] = workflow_id

            if response.get("media"):
                for media_item in response.get("media", []) or []:
                    media_name = str(media_item.get("name") or media_item.get("mediaName") or "").strip()
                    if not media_name:
                        continue
                    job = VideoJob.__new__(VideoJob)
                    job.media_name = media_name
                    job.status = "PENDING"
                    job.project_id = client_self.project_id
                    job.workflow_id = workflows_by_media.get(media_name, "")
                    jobs.append(job)
                if jobs:
                    return jobs

            for job_data in response.get("jobs", []) or []:
                media_id = job_data.get("mediaId", {}) if isinstance(job_data, dict) else {}
                media_name = str(media_id.get("mediaName") or media_id.get("name") or "").strip()
                if not media_name:
                    continue
                job = VideoJob.__new__(VideoJob)
                job.media_name = media_name
                job.status = "PENDING"
                job.project_id = client_self.project_id
                job.workflow_id = workflows_by_media.get(media_name, str(job_data.get("workflowId") or "").strip())
                jobs.append(job)
            return jobs

        async def _compat_get_recaptcha_token(api_self: Any) -> str:
            page = await api_self._bm.page()

            is_on_flow = "labs.google" in str(page.url or "")
            if not is_on_flow:
                await api_self._ensure_project_page()
                page = await api_self._bm.page()
            elif getattr(api_self, "project_id", "") and getattr(api_self, "_project_page_url", "") not in str(page.url or ""):
                await api_self._ensure_project_page()
                page = await api_self._bm.page()

            async def _token_once() -> str:
                try:
                    ready = await page.wait_for_function(
                        "() => !!window.grecaptcha?.enterprise?.execute",
                        timeout=12_000,
                    )
                    await ready.dispose()
                except Exception:
                    return ""
                try:
                    token = await page.evaluate(
                        f"""
                        async () => {{
                            try {{
                                return await window.grecaptcha.enterprise.execute(
                                    '{RECAPTCHA_SITE_KEY}',
                                    {{ action: 'GENERATE' }}
                                );
                            }} catch (error) {{
                                return '';
                            }}
                        }}
                        """
                    )
                except Exception:
                    return ""
                return str(token or "").strip()

            for attempt in range(3):
                token = await _token_once()
                if token:
                    return token
                if attempt == 0:
                    try:
                        await page.reload(wait_until="domcontentloaded", timeout=20_000)
                    except Exception:
                        pass
                await asyncio.sleep(1.5)
            return ""

        async def _compat_api_fetch(api_self: Any, method: str, url: str, body: Optional[dict] = None) -> dict:
            if not str(url).startswith("http"):
                url = f"{api_self.API_BASE if hasattr(api_self, 'API_BASE') else 'https://aisandbox-pa.googleapis.com/v1'}/{str(url).lstrip('/')}"

            hdrs = await api_self._get_auth_headers()
            api_key = str(getattr(api_self, "FLOW_API_KEY", "") or "").strip()
            if api_key:
                hdrs["x-goog-api-key"] = api_key
            data = json.dumps(body) if body is not None else None
            ctx = api_self._bm.context.request
            timeout_ms = int(max(30, int(getattr(api_self, "_timeout_s", 300) or 300)) * 1000)

            if method.upper() == "GET":
                resp = await ctx.get(url, headers=hdrs, timeout=timeout_ms)
            elif method.upper() == "PATCH":
                resp = await ctx.patch(url, headers=hdrs, data=data, timeout=timeout_ms)
            else:
                resp = await ctx.post(url, headers=hdrs, data=data, timeout=timeout_ms)

            if resp.status >= 400:
                text = await resp.text()
                endpoint = str(url).split("/")[-1].split(":")[-1]
                if resp.status == 404:
                    raise RuntimeError(
                        f"Endpoint not found (HTTP 404): {endpoint}\n"
                        f"This feature may be deprecated or unavailable via direct API.\n"
                        f"Response: {text[:200]}"
                    )
                if resp.status == 400:
                    try:
                        err_body = json.loads(text)
                        msg = err_body.get("error", {}).get("message", text[:200])
                    except Exception:
                        msg = text[:200]
                    raise RuntimeError(f"HTTP 400 INVALID_ARGUMENT on {endpoint}: {msg}")
                if resp.status in (401, 403):
                    try:
                        err_body = json.loads(text)
                        msg = err_body.get("error", {}).get("message", text[:200])
                    except Exception:
                        msg = text[:200]
                    raise RuntimeError(
                        f"HTTP {resp.status} on {endpoint}: {msg or 'authentication failed. Session cookies may be expired.'}"
                    )
                raise RuntimeError(f"HTTP {resp.status} on {endpoint}: {text[:200]}")

            try:
                return await resp.json()
            except Exception:
                return {}

        def _compat_interceptor_attach(self: Any, page: Any) -> None:
            if getattr(self, "_attached", False):
                return
            self._attached = True

            targets: List[Any] = [page]
            context = getattr(page, "context", None)
            if context is not None and hasattr(context, "on"):
                targets.append(context)

            for target in targets:
                try:
                    target.on("request", self._on_request)
                    target.on("response", self._on_response)
                except Exception:
                    continue

        FlowAPI._fetch = _compat_api_fetch
        FlowAPI.get_recaptcha_token = _compat_get_recaptcha_token
        UIInterceptor.attach = _compat_interceptor_attach
        FlowClient._ensure_project_page = _compat_ensure_project_page
        FlowUI._settings_visible = _compat_settings_visible
        FlowUI.fill_prompt = _compat_fill_prompt
        FlowUI.open_settings_panel = _compat_open_settings_panel
        FlowUI.switch_mode = _compat_switch_mode
        FlowUI.set_aspect_ratio = _compat_set_aspect_ratio
        FlowUI.set_count = _compat_set_count
        FlowUI.get_video_model_selector = _compat_get_video_model_selector
        FlowUI.select_video_model = _compat_select_video_model
        FlowUI.get_image_model_selector = _compat_get_image_model_selector
        FlowUI.select_image_model = _compat_select_image_model
        FlowClient.generate_video = _compat_generate_video
        FlowClient.generate_image = _compat_generate_image
        self.__class__._FLOW_RUNTIME_PATCHED = True

    def _project_url(self, project_id: str) -> str:
        return canonical_project_url(project_id)

    def _looks_like_placeholder_project_url(self, url: str) -> bool:
        candidate = str(url or "").strip().lower()
        if not candidate:
            return False
        return any(
            marker in candidate
            for marker in (
                "/project/[projectid]",
                "/project/%5bprojectid%5d",
                "/project/%5bproject_id%5d",
                "/project/[project_id]",
            )
        )

    FLOW_APP_HOSTS = ("labs.google", "flow.google.com")

    def _is_flow_project_page_url(self, url: str, project_url: str) -> bool:
        current_url = str(url or "").strip()
        target_url = str(project_url or "").strip()
        if not current_url or not target_url:
            return False
        if self._looks_like_placeholder_project_url(current_url):
            return False
        if current_url.startswith(target_url):
            return True
        project_id = self._normalize_project_id(target_url)
        if not project_id:
            return False
        parsed = urlparse(current_url)
        host = str(parsed.netloc or "").lower()
        if not any(host == known or host.endswith("." + known) for known in self.FLOW_APP_HOSTS):
            return False
        path = str(parsed.path or "")
        return f"/project/{project_id}" in path or f"/project/{quote(project_id, safe='')}" in path

    FLOW_DISMISS_BANNER_JS = """
        /* flow-banner-dismiss */
        () => {
          const deepQuery = (selector, root = document, seen = new Set()) => {
            const found = [];
            const visit = (node) => {
              if (!node || seen.has(node)) return;
              seen.add(node);
              try {
                found.push(...node.querySelectorAll(selector));
                for (const el of node.querySelectorAll('*')) {
                  if (el.shadowRoot) visit(el.shadowRoot);
                }
              } catch (_) {}
            };
            visit(root);
            return found;
          };
          const visible = (el) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            if (rect.width < 18 || rect.height < 18) return false;
            const style = window.getComputedStyle(el);
            return style.visibility !== 'hidden'
              && style.display !== 'none'
              && style.opacity !== '0'
              && rect.bottom > 0
              && rect.top < window.innerHeight;
          };
          const labelFor = (el) => [
            el.textContent || '',
            el.getAttribute('aria-label') || '',
            el.getAttribute('title') || '',
            el.getAttribute('data-testid') || '',
            el.getAttribute('class') || '',
          ].join(' ').replace(/\\s+/g, ' ').trim();
          const bannerHost = (el) => el.closest('[class*="banner" i], [role="banner"], [role="alert"], [role="status"], [class*="notice" i], [class*="announcement" i], [class*="toast" i]');
          const noticeText = /high\\s+demand|nhu\\s*cầu\\s*cao|retried|thử\\s*lại|refunded|hoàn\\s*lại|credits?|tín\\s*dụng|experiencing|đang\\s*gặp/i;
          const topLimit = Math.max(120, window.innerHeight * 0.16);
          const dismissed = [];
          const buttons = deepQuery('button, [role="button"]')
            .filter(visible)
            .map((el) => ({ el, rect: el.getBoundingClientRect(), label: labelFor(el) }))
            .filter((item) => item.rect.top < topLimit)
            .filter((item) => !/session|panel|dialog|search|filter|menu|more_vert|account|history|edit_square|settings|tune|help|back/i.test(item.label))
            .filter((item) => {
              if (/dismiss|banner/i.test(item.label)) return true;
              const host = bannerHost(item.el);
              if (!host) return false;
              const hostText = `${host.innerText || host.textContent || ''} ${host.getAttribute('class') || ''}`;
              return /đóng|dong\\b|close|ok\\b|got\\s*it|đã\\s*hiểu/i.test(item.label) && noticeText.test(hostText);
            })
            .slice(0, 2);
          for (const item of buttons) {
            try {
              item.el.scrollIntoView({ block: 'nearest', inline: 'nearest' });
              item.el.click();
              dismissed.push(item.label.replace(/\\s+/g, ' ').slice(0, 60));
            } catch (_) {}
          }
          return { dismissed, count: dismissed.length };
        }
    """

    async def _dismiss_flow_top_banner(self, page: Any) -> str:
        """Close Flow's top notice banner ("high demand", ...).

        The banner pushes the whole app down, so the Agent composer toolbar (Add ingredients,
        Start generation) ends up below the 900px viewport and every click on it misses.
        """
        try:
            result = await page.evaluate(self.FLOW_DISMISS_BANNER_JS)
        except Exception as exc:
            return f"top banner check skipped: {humanize_flow_error(str(exc))[:80]}"
        result = result if isinstance(result, dict) else {}
        dismissed = [str(label) for label in (result.get("dismissed") or []) if label]
        if not dismissed:
            return ""
        await asyncio.sleep(0.6)
        return f"dismissed top banner: {', '.join(dismissed)[:120]}"

    async def _wait_for_flow_app_ready(self, page: Any, timeout_s: float = 40.0) -> tuple[bool, str]:
        deadline = asyncio.get_running_loop().time() + max(3.0, float(timeout_s or 40.0))
        last_detail = "flow app not rendered"
        while asyncio.get_running_loop().time() < deadline:
            try:
                info = await page.evaluate(
                    """
                    () => {
                      const deepQuery = (selector, root = document, seen = new Set()) => {
                        const found = [];
                        const visit = (node) => {
                          if (!node || seen.has(node)) return;
                          seen.add(node);
                          try {
                            found.push(...node.querySelectorAll(selector));
                            for (const el of node.querySelectorAll('*')) {
                              if (el.shadowRoot) visit(el.shadowRoot);
                            }
                          } catch (_) {}
                        };
                        visit(root);
                        return found;
                      };
                      const visible = (el) => {
                        const rect = el.getBoundingClientRect();
                        if (rect.width < 12 || rect.height < 12) return false;
                        const style = window.getComputedStyle(el);
                        return style.visibility !== 'hidden' && style.display !== 'none' && style.opacity !== '0';
                      };
                      const buttons = deepQuery('button, [role="button"]').filter(visible).length;
                      const textboxes = deepQuery('textarea, [contenteditable="true"], [role="textbox"]').filter(visible).length;
                      return { buttons, textboxes, url: location.href.slice(0, 160) };
                    }
                    """
                )
            except Exception as exc:
                info = {"error": humanize_flow_error(str(exc))[:120]}
            info = info if isinstance(info, dict) else {}
            try:
                buttons = int(info.get("buttons") or 0)
            except Exception:
                buttons = 0
            if buttons >= 3:
                return True, f"flow app rendered ({buttons} controls) at {str(info.get('url') or '')[:120]}"
            last_detail = f"controls={buttons} url={str(info.get('url') or '')[:120]} {str(info.get('error') or '')}".strip()
            await asyncio.sleep(0.75)
        return False, last_detail

    async def _ensure_valid_flow_project_page(self, page: Any, project_url: str) -> None:
        target_url = str(project_url or "").strip()
        if not target_url:
            return

        current_url = str(getattr(page, "url", "") or "").strip()
        if self._is_flow_project_page_url(current_url, target_url):
            return

        if self._looks_like_placeholder_project_url(current_url):
            logging.getLogger(__name__).warning(
                "Flow tab opened placeholder project route (%s); redirecting to %s",
                current_url,
                target_url,
            )

        try:
            await page.goto(target_url, wait_until="domcontentloaded", timeout=60_000)
        except Exception:
            await page.goto(target_url, wait_until="commit", timeout=60_000)
        await asyncio.sleep(2.0)

    async def _repair_placeholder_flow_tabs(self, browser: Any, project_url: str) -> None:
        target_url = str(project_url or "").strip()
        if not target_url:
            return

        context = getattr(browser, "context", None)
        pages = list(getattr(context, "pages", []) or [])
        for candidate in pages:
            current_url = str(getattr(candidate, "url", "") or "").strip()
            if not self._looks_like_placeholder_project_url(current_url):
                continue
            try:
                logging.getLogger(__name__).warning(
                    "Repairing stale Flow placeholder tab (%s) -> %s",
                    current_url,
                    target_url,
                )
                await self._ensure_valid_flow_project_page(candidate, target_url)
            except Exception:
                continue

    async def _acquire_fresh_flow_page(self, browser: Any, project_url: str) -> Any:
        target_url = str(project_url or "").strip()
        context = getattr(browser, "context", None)
        pages = list(getattr(context, "pages", []) or [])

        for candidate in pages:
            current_url = str(getattr(candidate, "url", "") or "").strip()
            if self._is_flow_project_page_url(current_url, target_url):
                try:
                    browser._page = candidate
                except Exception:
                    pass
                return candidate

        try:
            fresh_page = await context.new_page()
        except Exception:
            fresh_page = await browser.page()
        try:
            browser._page = fresh_page
        except Exception:
            pass
        return fresh_page

    async def _close_placeholder_flow_tabs(self, browser: Any, project_url: str) -> None:
        target_url = str(project_url or "").strip()
        context = getattr(browser, "context", None)
        pages = list(getattr(context, "pages", []) or [])
        stale_pages = [
            candidate
            for candidate in pages
            if self._looks_like_placeholder_project_url(str(getattr(candidate, "url", "") or ""))
        ]
        if not stale_pages:
            return

        logger = logging.getLogger(__name__)
        for candidate in stale_pages:
            current_url = str(getattr(candidate, "url", "") or "").strip()
            try:
                logger.warning("Closing stale Flow placeholder tab (%s)", current_url)
                await candidate.close()
            except Exception:
                continue

        remaining_pages = list(getattr(context, "pages", []) or [])
        if remaining_pages:
            try:
                browser._page = remaining_pages[0]
            except Exception:
                pass
            return

        try:
            fresh_page = await context.new_page()
        except Exception:
            return
        try:
            browser._page = fresh_page
        except Exception:
            pass
        if target_url:
            await self._ensure_valid_flow_project_page(fresh_page, target_url)

    def _normalize_project_id(self, project_value: str) -> str:
        return normalize_project_id(project_value)

    def _normalized_config(self, config: AppConfig) -> AppConfig:
        normalized = normalized_app_config(config)
        try:
            active_profile = self._current_flow_profile()
            profile_project_id = self._flow_profile_project_id(active_profile, "")
        except Exception:
            return normalized
        if not profile_project_id:
            return normalized

        payload = _model_dump(normalized)
        payload["project_id"] = profile_project_id
        payload["project_url"] = self._project_url(profile_project_id)
        if not str(payload.get("project_name", "")).strip():
            payload["project_name"] = active_profile.label
        return normalized_app_config(payload)

    def _normalize_projects_payload(self, projects: Dict[str, Dict[str, Any]]) -> tuple[Dict[str, Dict[str, str]], bool]:
        normalized: Dict[str, Dict[str, str]] = {}
        changed = False

        for raw_id, payload in projects.items():
            normalized_id = self._normalize_project_id(raw_id) or self._normalize_project_id(payload.get("url", ""))
            if not normalized_id:
                changed = True
                continue

            normalized_entry = {
                "name": str(payload.get("name", "")),
                "url": self._project_url(normalized_id),
            }
            current = normalized.get(normalized_id)
            if current is None or (not current["name"] and normalized_entry["name"]):
                normalized[normalized_id] = normalized_entry

            if raw_id != normalized_id or payload.get("url", "") != normalized_entry["url"]:
                changed = True

        return normalized, changed

    def _save_project_registry(self, projects: Dict[str, Dict[str, str]], active_id: str) -> None:
        from flow._storage import save_projects, set_active_project

        save_projects(projects)
        set_active_project(active_id or None, self._project_url(active_id) or None)

    def _fields_set(self, model: Any) -> set[str]:
        return set(getattr(model, "model_fields_set", getattr(model, "__fields_set__", set())))

    def _pick_skill_value(self, fields_set: set[str], field_name: str, explicit: Any, fallback: Any) -> Any:
        if field_name in fields_set:
            if isinstance(explicit, str):
                return explicit.strip()
            return explicit
        return fallback

    def _pick_skill_list(self, fields_set: set[str], field_name: str, explicit: List[str], fallback: List[str]) -> List[str]:
        return explicit if field_name in fields_set else fallback

    def _normalize_reference_media_names(self, values: List[str]) -> List[str]:
        return [str(entry).strip() for entry in values if str(entry).strip()]

    def _strip_accents(self, text: str) -> str:
        normalized = unicodedata.normalize("NFD", text)
        return "".join(char for char in normalized if unicodedata.category(char) != "Mn")

    def _normalize_skill_token(self, text: str) -> str:
        stripped = self._strip_accents(text or "").lower()
        stripped = re.sub(r"[^a-z0-9]+", "_", stripped)
        return stripped.strip("_")

    def _suggest_skill_name(self, skill_type: str, prompt: str) -> str:
        labels = {
            "video": "Tạo video",
            "image": "Tạo ảnh",
            "extend": "Kéo dài video",
            "upscale": "Nâng chất lượng",
            "camera_motion": "Chuyển động camera",
            "camera_position": "Vị trí camera",
            "insert": "Chèn vật thể",
            "remove": "Xóa vật thể",
        }
        snippet = (prompt or "").strip().replace("\n", " ")
        if snippet:
            return f"{labels.get(skill_type, skill_type)}: {snippet[:40]}"
        return labels.get(skill_type, "Skill mới")

    def _infer_skill_type(self, text: str) -> str:
        hinted = self._infer_skill_type_from_hint(text)
        if hinted:
            return hinted
        return "video"

    def _infer_skill_type_from_hint(self, text: str) -> str:
        normalized = self._normalize_skill_token(text)
        if any(token in normalized for token in {"tools_video", "guides_video", "video_guide", "video_ad"}):
            return "video"
        if any(token in normalized for token in {"tools_image", "guides_photo", "photo_graphy", "product_photography"}):
            return "image"
        rules = [
            ("camera_position", ["camera_position", "vi_tri_camera", "position_camera"]),
            ("camera_motion", ["camera_motion", "chuyen_dong_camera", "motion_camera"]),
            ("upscale", ["upscale", "nang_chat_luong"]),
            ("extend", ["extend", "keo_dai"]),
            ("insert", ["insert", "chen_vat_the", "them_vat_the"]),
            ("remove", ["remove", "xoa_vat_the"]),
            ("image", ["tao_anh", "image", "anh", "concept"]),
            ("video", ["tao_video", "video", "clip"]),
        ]
        for skill_type, keys in rules:
            if any(key in normalized for key in keys):
                return skill_type
        return ""

    def _parse_skill_type(self, value: str) -> str:
        normalized = self._normalize_skill_token(value)
        mapping = {
            "video": "video",
            "tao_video": "video",
            "image": "image",
            "anh": "image",
            "tao_anh": "image",
            "extend": "extend",
            "keo_dai": "extend",
            "upscale": "upscale",
            "nang_chat_luong": "upscale",
            "camera_motion": "camera_motion",
            "chuyen_dong_camera": "camera_motion",
            "camera_position": "camera_position",
            "vi_tri_camera": "camera_position",
            "insert": "insert",
            "chen_vat_the": "insert",
            "remove": "remove",
            "xoa_vat_the": "remove",
        }
        return mapping.get(normalized, self._infer_skill_type(value))

    def _parse_aspect(self, value: str) -> str:
        normalized = self._normalize_skill_token(value)
        if normalized in {"portrait", "9_16", "doc", "dung", "vertical"}:
            return "portrait"
        if normalized in {"square", "1_1", "vuong"}:
            return "square"
        return "landscape"

    def _parse_skill_text(self, text: str) -> Dict[str, Any]:
        parsed: Dict[str, Any] = {
            "type": self._infer_skill_type(text),
            "summary": "Học từ ô skill tự do.",
            "reference_media_names": [],
            "aspect": "landscape",
            "count": 1,
            "resolution": "1080p",
            "mask_x": 0.5,
            "mask_y": 0.5,
            "brush_size": 40,
        }
        free_lines: List[str] = []

        alias_map = {
            "ten": "name",
            "name": "name",
            "skill": "name",
            "tom_tat": "summary",
            "summary": "summary",
            "ghi_chu": "summary",
            "note": "summary",
            "loai": "type",
            "type": "type",
            "mode": "type",
            "prompt": "prompt",
            "mo_ta": "prompt",
            "description": "prompt",
            "aspect": "aspect",
            "ti_le": "aspect",
            "ratio": "aspect",
            "count": "count",
            "so_luong": "count",
            "quantity": "count",
            "workflow": "workflow_id",
            "workflow_id": "workflow_id",
            "ma_workflow": "workflow_id",
            "media": "media_id",
            "media_id": "media_id",
            "ma_media": "media_id",
            "motion": "motion",
            "huong_camera": "motion",
            "position": "position",
            "vi_tri_camera": "position",
            "resolution": "resolution",
            "do_phan_giai": "resolution",
            "references": "reference_media_names",
            "reference_media_names": "reference_media_names",
            "media_ref": "reference_media_names",
            "mask_x": "mask_x",
            "maskx": "mask_x",
            "mask_y": "mask_y",
            "masky": "mask_y",
            "brush": "brush_size",
            "brush_size": "brush_size",
            "co": "brush_size",
        }

        for raw_line in text.splitlines():
            line = raw_line.strip()
            if not line or line.startswith("#!"):
                continue
            if line.startswith("#"):
                continue
            if line.lower().startswith("export "):
                line = line[7:].strip()
            line = line.strip("-").strip()
            if not line:
                continue

            separator = ":" if ":" in line else "=" if "=" in line else ""
            if separator:
                key, value = [part.strip() for part in line.split(separator, 1)]
                value = value.strip().strip('"').strip("'")
                field_name = alias_map.get(self._normalize_skill_token(key), "")
                if not field_name:
                    free_lines.append(line)
                    continue

                if field_name == "type":
                    parsed["type"] = self._parse_skill_type(value)
                elif field_name == "aspect":
                    parsed["aspect"] = self._parse_aspect(value)
                elif field_name == "count":
                    numbers = re.findall(r"\d+", value)
                    if numbers:
                        parsed["count"] = int(numbers[0])
                elif field_name == "reference_media_names":
                    parsed["reference_media_names"] = [entry.strip() for entry in re.split(r"[,\n]", value) if entry.strip()]
                elif field_name in {"mask_x", "mask_y"}:
                    try:
                        parsed[field_name] = float(value)
                    except ValueError:
                        pass
                elif field_name == "brush_size":
                    numbers = re.findall(r"\d+", value)
                    if numbers:
                        parsed["brush_size"] = int(numbers[0])
                else:
                    parsed[field_name] = value
                continue

            free_lines.append(line)

        normalized_text = self._normalize_skill_token(text)
        plain_text = self._strip_accents(text).lower()
        count_match = re.search(r"\b(\d+)\s*(anh|video|ket qua|ket_qua|results?)\b", plain_text)
        if count_match and parsed.get("count", 1) == 1:
            parsed["count"] = int(count_match.group(1))

        if "9_16" in normalized_text or "doc" in normalized_text:
            parsed["aspect"] = "portrait"
        elif "1_1" in normalized_text or "vuong" in normalized_text:
            parsed["aspect"] = "square"
        elif "16_9" in normalized_text or "ngang" in normalized_text:
            parsed["aspect"] = "landscape"

        if "4k" in normalized_text:
            parsed["resolution"] = "4k"

        if not parsed.get("prompt"):
            parsed["prompt"] = "\n".join(free_lines).strip()

        if not parsed.get("name"):
            parsed["name"] = self._suggest_skill_name(parsed.get("type", "video"), parsed.get("prompt", ""))

        return parsed

    def _looks_like_instructional_skill_doc(self, text: str, source_hint: str = "") -> bool:
        source_name = Path(urlparse(source_hint).path or source_hint).name.lower()
        lowered = text.lower()
        has_frontmatter = lowered.startswith("---\n") and ("name:" in lowered[:300] or "description:" in lowered[:600])
        has_markdown_sections = "\n# " in text or text.startswith("# ")
        if source_name in {"skill.md", "readme.md"} and has_markdown_sections:
            return True
        return has_frontmatter and has_markdown_sections and "```" in text

    def _looks_like_skill_add_command(self, value: str) -> bool:
        lowered = value.strip().lower()
        return " skills add " in f" {lowered} " or lowered.startswith("skills add ") or lowered.startswith("npx ")

    def _parse_skill_add_command(self, command: str) -> Dict[str, Any]:
        try:
            tokens = shlex.split(command)
        except ValueError as exc:
            raise HTTPException(status_code=400, detail=f"Lệnh skills add không hợp lệ: {exc}") from exc

        if not tokens:
            raise HTTPException(status_code=400, detail="Lệnh skills add đang trống.")

        position = 0
        wrappers = {"npx", "bunx"}
        while position < len(tokens) and tokens[position] in wrappers:
            position += 1
            while position < len(tokens) and tokens[position].startswith("-"):
                position += 1

        if position + 1 < len(tokens) and tokens[position] == "pnpm" and tokens[position + 1] == "dlx":
            position += 2
        elif position + 1 < len(tokens) and tokens[position] == "yarn" and tokens[position + 1] == "dlx":
            position += 2

        if position >= len(tokens) or tokens[position] not in {"skills", "skill"}:
            raise HTTPException(status_code=400, detail="Bot hiện mới hiểu lệnh kiểu `skills add ...`.")

        position += 1
        if position >= len(tokens) or tokens[position] != "add":
            raise HTTPException(status_code=400, detail="Bot hiện mới hỗ trợ lệnh `skills add`.")

        position += 1
        source = ""
        name = ""
        summary = ""
        selected_skills: List[str] = []

        while position < len(tokens):
            token = tokens[position]

            if token in {"--skill", "-s"}:
                position += 1
                if position >= len(tokens):
                    raise HTTPException(status_code=400, detail="Thiếu tên skill sau `--skill`.")
                selected_skills.extend(self._split_skill_selector_values(tokens[position]))
                position += 1
                continue

            if token.startswith("--skill="):
                selected_skills.extend(self._split_skill_selector_values(token.split("=", 1)[1]))
                position += 1
                continue

            if token == "--skills":
                position += 1
                if position >= len(tokens):
                    raise HTTPException(status_code=400, detail="Thiếu danh sách skill sau `--skills`.")
                selected_skills.extend(self._split_skill_selector_values(tokens[position]))
                position += 1
                continue

            if token.startswith("--skills="):
                selected_skills.extend(self._split_skill_selector_values(token.split("=", 1)[1]))
                position += 1
                continue

            if token == "--name":
                position += 1
                if position < len(tokens):
                    name = tokens[position].strip()
                position += 1
                continue

            if token.startswith("--name="):
                name = token.split("=", 1)[1].strip()
                position += 1
                continue

            if token == "--summary":
                position += 1
                if position < len(tokens):
                    summary = tokens[position].strip()
                position += 1
                continue

            if token.startswith("--summary="):
                summary = token.split("=", 1)[1].strip()
                position += 1
                continue

            if token.startswith("-"):
                position += 1
                continue

            if not source:
                source = token
                position += 1
                continue

            selected_skills.extend(self._split_skill_selector_values(token))
            position += 1

        if not source:
            raise HTTPException(status_code=400, detail="Lệnh skills add đang thiếu repo hoặc link skill.")

        return {
            "url": source,
            "skills": self._normalize_selected_skills(selected_skills),
            "name": name,
            "summary": summary,
        }

    def _split_skill_selector_values(self, value: str) -> List[str]:
        return [part.strip() for part in re.split(r"[,\n]", value) if part.strip()]

    def _normalize_selected_skills(self, skills: List[str]) -> List[str]:
        normalized: List[str] = []
        seen: set[str] = set()
        for raw_skill in skills:
            for value in self._split_skill_selector_values(raw_skill):
                skill = value.strip().strip("/")
                if not skill:
                    continue
                lowered = skill.lower()
                if lowered.endswith("/skill.md"):
                    skill = skill[:-9].rstrip("/")
                elif lowered.endswith("/readme.md"):
                    skill = skill[:-10].rstrip("/")
                elif lowered.endswith(".md") and "/" not in skill:
                    skill = re.sub(r"\.md$", "", skill, flags=re.IGNORECASE)
                key = skill.lower()
                if key in seen:
                    continue
                seen.add(key)
                normalized.append(skill)
        return normalized

    def _normalize_skill_source_input(self, value: str) -> str:
        raw = value.strip()
        if not raw:
            return ""
        if raw.startswith("github.com/"):
            return f"https://{raw}"
        if re.fullmatch(r"[A-Za-z0-9_.-]+/[A-Za-z0-9_.-]+(?:\.git)?", raw):
            return f"https://github.com/{raw[:-4] if raw.endswith('.git') else raw}"
        return raw

    def _parse_github_collection_url(self, value: str) -> Dict[str, str] | None:
        parsed = urlparse(value.strip())
        if parsed.netloc != "github.com":
            return None

        parts = [segment for segment in parsed.path.strip("/").split("/") if segment]
        if len(parts) < 2:
            return None
        if len(parts) >= 3 and parts[2] == "blob":
            return None

        owner = parts[0]
        repo = parts[1][:-4] if parts[1].endswith(".git") else parts[1]
        branch = ""
        path = ""

        if len(parts) >= 4 and parts[2] == "tree":
            branch = parts[3]
            path = "/".join(parts[4:])
        elif len(parts) > 2:
            return None

        return {
            "owner": owner,
            "repo": repo,
            "branch": branch,
            "path": path,
            "source_url": value.strip(),
        }

    def _normalize_skill_source_url(self, value: str) -> str:
        url = value.strip()
        if url.startswith("www."):
            url = f"https://{url}"

        parsed = urlparse(url)
        if parsed.scheme not in {"http", "https"}:
            raise HTTPException(status_code=400, detail="Link skill phải bắt đầu bằng http:// hoặc https://")

        if parsed.netloc == "github.com":
            parts = parsed.path.strip("/").split("/")
            if len(parts) >= 5 and parts[2] == "blob":
                owner, repo = parts[0], parts[1]
                branch = parts[3]
                file_path = "/".join(parts[4:])
                return f"https://raw.githubusercontent.com/{owner}/{repo}/{branch}/{file_path}"

        return url

    def _download_skill_text(self, url: str) -> Dict[str, str]:
        request = Request(url, headers={"User-Agent": "flow-web-ui/0.1"})
        last_error: Exception | None = None
        for attempt in range(2):
            try:
                with urlopen(request, timeout=30) as response:
                    payload = response.read(200_000)
                    content_type = response.headers.get_content_type()
                    charset = response.headers.get_content_charset() or "utf-8"
                    final_url = response.geturl()
                break
            except HTTPError as exc:
                message = f"Không tải được file skill từ link này ({exc.code})."
                if exc.code == 404:
                    message = "Không tìm thấy file skill tại link này."
                raise HTTPException(status_code=400, detail=message) from exc
            except URLError as exc:
                last_error = exc
                if attempt == 1:
                    raise HTTPException(status_code=400, detail=f"Không tải được skill từ link này: {exc.reason}") from exc
                time.sleep(0.5)
        else:
            raise HTTPException(status_code=400, detail=f"Không tải được skill từ link này: {last_error}")

        if content_type not in {
            "text/plain",
            "text/markdown",
            "text/x-shellscript",
            "text/x-sh",
            "application/x-sh",
            "application/octet-stream",
            "text/html",
        }:
            raise HTTPException(status_code=400, detail="Link này không giống tệp văn bản/skill có thể đọc được.")

        text = payload.decode(charset, errors="replace").strip()
        if not text:
            raise HTTPException(status_code=400, detail="Link skill không có nội dung để học.")

        return {
            "url": final_url,
            "text": text,
        }

    def _http_json(self, url: str) -> Any:
        request = Request(
            url,
            headers={
                "User-Agent": "flow-web-ui/0.1",
                "Accept": "application/vnd.github+json",
            },
        )
        try:
            with urlopen(request, timeout=20) as response:
                payload = response.read(500_000)
        except HTTPError as exc:
            message = f"GitHub trả về lỗi {exc.code}"
            if exc.code == 404:
                message = "Không tìm thấy repo/thư mục GitHub này."
            elif exc.code == 403:
                message = "GitHub tạm chặn hoặc giới hạn lượt truy cập. Hãy thử lại sau ít phút."
            raise HTTPException(status_code=400, detail=message) from exc
        except URLError as exc:
            raise HTTPException(status_code=400, detail=f"Không kết nối được tới GitHub: {exc.reason}") from exc

        try:
            return json.loads(payload.decode("utf-8"))
        except Exception as exc:
            raise HTTPException(status_code=400, detail="GitHub trả về dữ liệu không hợp lệ.") from exc

    def _github_default_branch(self, owner: str, repo: str) -> str:
        payload = self._http_json(f"https://api.github.com/repos/{owner}/{repo}")
        branch = str(payload.get("default_branch", "")).strip()
        return branch or "main"

    def _github_contents_api_url(self, owner: str, repo: str, path: str, branch: str) -> str:
        encoded_path = quote(path.strip("/"), safe="/")
        base = f"https://api.github.com/repos/{owner}/{repo}/contents"
        if encoded_path:
            base = f"{base}/{encoded_path}"
        return f"{base}?ref={quote(branch, safe='')}"

    def _github_tree_api_url(self, owner: str, repo: str, branch: str) -> str:
        return f"https://api.github.com/repos/{owner}/{repo}/git/trees/{quote(branch, safe='')}?recursive=1"

    def _media_skill_repo_entries(self) -> List[Dict[str, Any]]:
        owner, repo = self.MEDIA_SKILL_REPO.split("/", 1)
        branch = self._github_default_branch(owner, repo)
        payload = self._http_json(self._github_tree_api_url(owner, repo, branch))
        tree = payload.get("tree", []) if isinstance(payload, dict) else []
        entries: List[Dict[str, Any]] = []

        for item in tree:
            if item.get("type") != "blob":
                continue
            path = str(item.get("path", "")).strip()
            if not self.MEDIA_SKILL_PATH_PATTERN.match(path):
                continue
            entries.append(
                {
                    "path": path,
                    "download_url": f"https://raw.githubusercontent.com/{owner}/{repo}/{branch}/{path}",
                    "html_url": f"https://github.com/{owner}/{repo}/blob/{branch}/{path}",
                }
            )

        entries.sort(key=lambda item: item["path"].lower())
        return entries

    def _github_selected_skill_entries(
        self,
        owner: str,
        repo: str,
        branch: str,
        root_path: str,
        selected_skills: List[str],
    ) -> Dict[str, Any]:
        active_branch = branch or self._github_default_branch(owner, repo)
        payload = self._http_json(self._github_tree_api_url(owner, repo, active_branch))
        tree = payload.get("tree", []) if isinstance(payload, dict) else []
        root_prefix = root_path.strip("/").lower()
        candidate_paths: List[str] = []

        for item in tree:
            if item.get("type") != "blob":
                continue
            item_path = str(item.get("path", "")).strip()
            if not item_path:
                continue
            lowered = item_path.lower()
            if root_prefix and lowered != root_prefix and not lowered.startswith(f"{root_prefix}/"):
                continue
            file_name = Path(lowered).name
            if file_name not in {"skill.md", "readme.md"} and Path(lowered).suffix not in self.SKILL_TEXT_EXTENSIONS:
                continue
            candidate_paths.append(item_path)

        entries: List[Dict[str, Any]] = []
        missing: List[str] = []
        seen_paths: set[str] = set()
        for skill in selected_skills:
            matches = self._match_skill_paths(skill, candidate_paths)
            if not matches:
                missing.append(skill)
                continue
            for path in matches:
                if path in seen_paths:
                    continue
                seen_paths.add(path)
                entries.append(
                    {
                        "path": path,
                        "download_url": f"https://raw.githubusercontent.com/{owner}/{repo}/{active_branch}/{path}",
                        "html_url": f"https://github.com/{owner}/{repo}/blob/{active_branch}/{path}",
                        "size": 0,
                    }
                )

        return {
            "entries": entries,
            "missing": missing,
        }

    def _github_skill_file_entries(self, owner: str, repo: str, branch: str, root_path: str) -> List[Dict[str, Any]]:
        active_branch = branch or self._github_default_branch(owner, repo)
        queue = [root_path.strip("/")]
        files: List[Dict[str, Any]] = []
        visited: set[str] = set()
        scanned_dirs = 0

        while queue:
            current = queue.pop(0)
            if current in visited:
                continue
            visited.add(current)
            scanned_dirs += 1
            if scanned_dirs > 40:
                break

            payload = self._http_json(self._github_contents_api_url(owner, repo, current, active_branch))
            items = payload if isinstance(payload, list) else [payload]
            for item in items:
                item_type = item.get("type", "")
                item_path = str(item.get("path", "")).strip()
                if item_type == "dir":
                    queue.append(item_path)
                    continue
                if item_type != "file":
                    continue
                if self._is_skill_candidate_path(item_path):
                    files.append(
                        {
                            "path": item_path,
                            "download_url": item.get("download_url", ""),
                            "html_url": item.get("html_url", ""),
                            "size": int(item.get("size", 0) or 0),
                        }
                    )
                if len(files) >= 25:
                    return files
        return files

    def _match_skill_paths(self, skill: str, candidate_paths: List[str]) -> List[str]:
        normalized_skill = skill.strip().strip("/")
        if not normalized_skill:
            return []

        normalized_skill_lower = normalized_skill.lower()
        skill_base = Path(normalized_skill_lower).name
        direct_file_matches: List[str] = []
        folder_matches: List[str] = []
        fuzzy_matches: List[str] = []

        for path in candidate_paths:
            lowered = path.lower()
            parent = str(Path(lowered).parent)
            file_name = Path(lowered).name

            if lowered == normalized_skill_lower or lowered.endswith(f"/{normalized_skill_lower}"):
                direct_file_matches.append(path)
                continue

            if lowered.endswith(f"/{normalized_skill_lower}/skill.md") or lowered.endswith(f"/{normalized_skill_lower}/readme.md"):
                folder_matches.append(path)
                continue

            if skill_base and (
                parent.endswith(f"/{skill_base}")
                or parent == skill_base
                or lowered.endswith(f"/{skill_base}/skill.md")
                or lowered.endswith(f"/{skill_base}/readme.md")
            ):
                folder_matches.append(path)
                continue

            if normalized_skill_lower in lowered:
                fuzzy_matches.append(path)
                continue

            if file_name in {"skill.md", "readme.md"} and skill_base and skill_base in parent:
                fuzzy_matches.append(path)

        matches = direct_file_matches or folder_matches or fuzzy_matches
        return sorted(
            matches,
            key=lambda path: (
                0 if Path(path).name.lower() == "skill.md" else 1,
                path.count("/"),
                len(path),
            ),
        )[:5]

    def _is_skill_candidate_path(self, path: str) -> bool:
        lower = path.lower()
        name = Path(lower).name
        ext = Path(lower).suffix
        parent = str(Path(lower).parent)
        if ext not in self.SKILL_TEXT_EXTENSIONS:
            return False
        if name.startswith("."):
            return False
        if name == "readme.md" and "skill" not in parent:
            return False
        return True

    def _looks_like_skill_text(self, text: str, path: str = "") -> bool:
        normalized_path = path.lower()
        if "skill" in normalized_path:
            return True

        lowered = self._strip_accents(text).lower()
        signals = [
            "prompt",
            "workflow",
            "workflow_id",
            "type=",
            "type:",
            "aspect",
            "count",
            "tao anh",
            "tao video",
            "image",
            "video",
            "camera_motion",
            "camera_position",
            "upscale",
            "insert",
            "remove",
        ]
        score = sum(1 for signal in signals if signal in lowered)
        return score >= 2

    def _skill_signature(self, name: str, content: str) -> str:
        return f"{name.strip().lower()}::{content.strip()}"

    def _name_from_url(self, url: str) -> str:
        path = urlparse(url).path.rstrip("/")
        file_name = path.split("/")[-1] if path else ""
        if not file_name:
            return ""
        name = re.sub(r"\.[A-Za-z0-9]+$", "", file_name).replace("-", " ").replace("_", " ").strip()
        return name[:80]

    def _name_from_path(self, path: str) -> str:
        path_obj = Path(path)
        file_name = path_obj.name
        if not file_name:
            return ""
        if file_name.lower() in {"skill.md", "readme.md"} and path_obj.parent.name:
            file_name = path_obj.parent.name
        return re.sub(r"\.[A-Za-z0-9]+$", "", file_name).replace("-", " ").replace("_", " ").strip()[:80]

    def _flow_error_status(self, exc: Exception) -> int:
        if isinstance(exc, HTTPException):
            return exc.status_code
        if self._is_profile_lock_error(exc):
            return 409
        return 500

    def _flow_error_detail(self, exc: Exception) -> str:
        if isinstance(exc, HTTPException):
            detail = exc.detail
            if isinstance(detail, str):
                return humanize_flow_error(detail)
            return "Yêu cầu tới Google Flow không thành công."

        return humanize_flow_error(str(exc).strip()) or "Không thể kết nối tới Google Flow."

    def _is_profile_lock_error(self, exc: Exception) -> bool:
        message = str(exc)
        lowered = message.lower()
        return (
            "processsingleton" in message
            or "singletonlock" in lowered
            or "profile directory is already in use" in lowered
        )

    def _download_name(self, job: JobRecord, artifact: JobArtifact, artifact_index: int) -> str:
        extension = ".mp4" if artifact.mime_type.startswith("video") else ".jpg"
        slug = artifact.media_name or f"{job.type}-{job.id[:8]}-{artifact_index + 1}"
        return f"{slug}{extension}"

    def _resolve_job_request(self, request: CreateJobRequest, config: AppConfig) -> CreateJobRequest:
        payload = _model_dump(request)
        raw_timeout = int(payload.get("timeout_s") or 0)
        payload["type"] = str(payload.get("type", "")).strip()
        payload["prompt"] = str(payload.get("prompt", "")).strip()
        payload["title"] = str(payload.get("title", "")).strip()
        payload["model"] = self._normalize_job_model(payload["type"], str(payload.get("model", "")).strip())
        payload["aspect"] = str(payload.get("aspect", "landscape")).strip() or "landscape"
        payload["start_image_path"] = str(payload.get("start_image_path", "")).strip()
        payload["reference_image_paths"] = [
            str(item).strip()
            for item in payload.get("reference_image_paths", [])
            if str(item).strip()
        ]
        payload["reference_image_roles"] = self._normalize_reference_image_roles(
            payload["reference_image_paths"],
            payload.get("reference_image_roles", []),
        )
        payload["reference_media_names"] = [
            str(item).strip()
            for item in payload.get("reference_media_names", [])
            if str(item).strip()
        ]
        payload["media_id"] = str(payload.get("media_id", "")).strip()
        payload["workflow_id"] = str(payload.get("workflow_id", "")).strip() or config.active_workflow_id
        payload["trello_source_card_id"] = self._normalize_trello_card_id(str(payload.get("trello_source_card_id") or ""))
        payload["trello_source_attachment_ids"] = self._normalize_trello_attachment_ids(
            payload.get("trello_source_attachment_ids") or []
        )
        payload["motion"] = str(payload.get("motion", "")).strip()
        payload["position"] = str(payload.get("position", "")).strip()
        payload["resolution"] = str(payload.get("resolution", "1080p")).strip() or "1080p"
        payload["source_job_id"] = str(payload.get("source_job_id", "")).strip()
        payload["timeout_s"] = max(30, raw_timeout) if raw_timeout > 0 else max(30, int(config.generation_timeout_s))
        return CreateJobRequest(**payload)

    def _resolve_retry_source(self, source_job_id: str, request_type: str) -> JobRecord | None:
        source_id = str(source_job_id or "").strip()
        if not source_id:
            return None

        source_job = self.store.get_job(source_id)
        if source_job is None:
            raise HTTPException(status_code=400, detail="Không tìm thấy job gốc để chạy lại.")
        if source_job.status not in {"failed", "interrupted"}:
            raise HTTPException(status_code=400, detail="Chỉ có thể chạy lại job đang lỗi hoặc đã bị ngắt.")
        if source_job.type not in self.SUPPORTED_SKILL_TYPES:
            raise HTTPException(status_code=400, detail="Loại job này chưa hỗ trợ chạy lại.")
        if source_job.type != request_type:
            raise HTTPException(status_code=400, detail="Loại tác vụ chạy lại phải khớp với job gốc.")
        return source_job

    def _build_retry_snapshot(self, source_job: JobRecord | None) -> JobRetrySnapshot:
        if source_job is None:
            return JobRetrySnapshot()
        return JobRetrySnapshot(
            is_retry=True,
            source_job_id=source_job.id,
            source_job_title=source_job.title or source_job.type.replace("_", " ").title(),
            source_job_type=source_job.type,
            source_job_status=source_job.status,
            source_job_created_at=source_job.created_at,
        )

    def _default_title(self, request: CreateJobRequest) -> str:
        if request.type == "video":
            if request.start_image_path:
                return "Tạo video từ ảnh"
            if request.reference_image_paths or request.reference_media_names:
                return "Tạo video từ ảnh tham chiếu"
            return "Tạo video từ prompt"
        if request.type == "image":
            if request.reference_image_paths or request.reference_media_names:
                return "Chỉnh ảnh từ ảnh tham chiếu"
            return "Tạo ảnh từ prompt"
        titles = {
            "extend": "Kéo dài video",
            "upscale": "Nâng chất lượng video",
            "camera_motion": "Chuyển động camera",
            "camera_position": "Vị trí camera",
            "insert": "Chèn vật thể",
            "remove": "Xóa vật thể",
        }
        return titles.get(request.type, request.type.replace("_", " ").title())

    def _job_type_label(self, job_type: str) -> str:
        titles = {
            "login": "Đăng nhập",
            "video": "Tạo video",
            "image": "Tạo ảnh",
            "extend": "Kéo dài video",
            "upscale": "Nâng chất lượng",
            "camera_motion": "Chuyển động camera",
            "camera_position": "Vị trí camera",
            "insert": "Chèn vật thể",
            "remove": "Xóa vật thể",
        }
        return titles.get(str(job_type or "").strip(), str(job_type or "").strip())

    def _build_output_shelf(self, jobs: List[JobRecord]) -> OutputShelfSnapshot:
        items: List[OutputShelfItem] = []

        for job in jobs:
            if job.status != "completed" or not job.artifacts:
                continue

            job_input = job.input if isinstance(job.input, dict) else {}
            for artifact_index, artifact in enumerate(job.artifacts):
                workflow_id = str(artifact.workflow_id or "").strip() or str(job_input.get("workflow_id", "") or "").strip()
                local_path = str(artifact.local_path or "").strip()
                local_exists = self._artifact_local_exists(local_path)
                local_file_url = self._artifact_file_url(job.id, artifact_index) if local_path else ""
                items.append(
                    OutputShelfItem(
                        job_id=job.id,
                        artifact_index=artifact_index,
                        title=artifact.label or f"Kết quả {artifact_index + 1}",
                        job_title=job.title or self._job_type_label(job.type),
                        job_type=job.type,
                        job_type_label=self._job_type_label(job.type),
                        created_at=job.updated_at or job.created_at,
                        media_id=str(artifact.media_name or "").strip(),
                        workflow_id=workflow_id,
                        source_url=str(artifact.url or "").strip(),
                        local_path=local_path,
                        local_file_url=local_file_url,
                        local_exists=local_exists,
                        preview_url=self._artifact_preview_url(job, artifact, artifact_index),
                        mime_type=str(artifact.mime_type or "").strip(),
                        prompt=str(artifact.prompt or job_input.get("prompt", "") or "").strip(),
                        dimensions=artifact.dimensions or {},
                    )
                )
                if len(items) >= self.MAX_OUTPUT_SHELF_ITEMS:
                    break

            if len(items) >= self.MAX_OUTPUT_SHELF_ITEMS:
                break

        if not items:
            return OutputShelfSnapshot()

        job_count = len({item.job_id for item in items})
        return OutputShelfSnapshot(
            has_items=True,
            total_items=len(items),
            job_count=job_count,
            summary=self._output_shelf_summary(len(items), job_count),
            items=items,
        )

    def _replay_group_meta(self, group_key: str) -> Dict[str, str]:
        mapping = {
            "auth": {
                "label": "Cụm đăng nhập bị ngắt",
                "description": "Giữ log cuối để mở lại đăng nhập Google Flow mà không phải mò lại từ đầu.",
            },
            "video": {
                "label": "Cụm tạo video bị ngắt",
                "description": "Giữ prompt, tỉ lệ, ảnh đầu vào và timeout cuối để mở retry nhanh.",
            },
            "image": {
                "label": "Cụm tạo ảnh bị ngắt",
                "description": "Giữ prompt, tỉ lệ, media tham chiếu và timeout cuối để khôi phục nhanh.",
            },
            "edit": {
                "label": "Cụm chỉnh sửa media bị ngắt",
                "description": "Giữ media ID, workflow và tham số chỉnh sửa cuối để mở lại đúng form retry.",
            },
            "other": {
                "label": "Interrupted work khác",
                "description": "Giữ log cuối để quyết định bước recovery phù hợp mà không mất dấu công việc dở dang.",
            },
        }
        return mapping.get(group_key, mapping["edit"])

    def _download_root(self) -> Path:
        configured = self.store.snapshot().config.output_dir.strip()
        if configured:
            return Path(configured).expanduser()
        return DOWNLOADS_DIR

    def _artifact_file_url(self, job_id: str, artifact_index: int) -> str:
        return f"/api/jobs/{quote(str(job_id or '').strip(), safe='')}/artifacts/{int(artifact_index)}/file"

    def _get_artifact_or_raise(self, job_id: str, artifact_index: int) -> tuple[JobRecord, JobArtifact]:
        job = self.store.get_job(job_id)
        if job is None:
            raise HTTPException(status_code=404, detail="Không tìm thấy tác vụ.")
        if artifact_index < 0 or artifact_index >= len(job.artifacts):
            raise HTTPException(status_code=400, detail="Chỉ mục kết quả không hợp lệ.")
        return job, job.artifacts[artifact_index]

    def _artifact_local_exists(self, local_path: str) -> bool:
        raw = str(local_path or "").strip()
        if not raw:
            return False
        try:
            return Path(raw).expanduser().exists()
        except OSError:
            return False

    def _artifact_local_roots(self) -> List[Path]:
        roots = [DOWNLOADS_DIR.resolve(), UPLOADS_DIR.resolve()]
        configured = str(self.store.snapshot().config.output_dir or "").strip()
        if configured:
            try:
                roots.insert(0, Path(configured).expanduser().resolve())
            except OSError:
                pass

        unique_roots: List[Path] = []
        seen: set[str] = set()
        for root in roots:
            normalized = str(root)
            if normalized in seen:
                continue
            seen.add(normalized)
            unique_roots.append(root)
        return unique_roots

    def _artifact_local_path(self, artifact: JobArtifact) -> Path:
        raw = str(artifact.local_path or "").strip()
        if not raw:
            raise HTTPException(status_code=400, detail="Artifact này chưa có tệp local đã lưu.")

        try:
            path = Path(raw).expanduser().resolve()
        except OSError as exc:
            raise HTTPException(status_code=404, detail="Không thể đọc tệp local của artifact này.") from exc

        allowed_roots = self._artifact_local_roots()
        if allowed_roots and not any(str(path).startswith(str(root)) for root in allowed_roots):
            raise HTTPException(status_code=403, detail="Tệp local này nằm ngoài vùng app đang phục vụ.")
        if not path.exists() or not path.is_file():
            raise HTTPException(status_code=404, detail="Tệp đã lưu cho artifact này không còn trên máy.")
        return path

    def _artifact_preview_url(self, job: JobRecord, artifact: JobArtifact, artifact_index: int) -> str:
        if str(artifact.local_path or "").strip():
            try:
                self._artifact_local_path(artifact)
            except HTTPException:
                pass
            else:
                return self._artifact_file_url(job.id, artifact_index)
        return str(artifact.public_url or artifact.url or "").strip()

    def _output_shelf_summary(self, item_count: int, job_count: int) -> str:
        return (
            f"{item_count} artifact mới nhất từ {job_count} job hoàn tất gần đây. "
            "Có thể mở, lưu hoặc tái dùng ngay tại đây mà không cần cuộn hết lịch sử tác vụ."
        )

    def _build_cleanup_assistant(
        self,
        config: Dict[str, Any] | AppConfig,
        jobs: List[JobRecord],
        output_shelf: OutputShelfSnapshot,
    ) -> tuple[CleanupAssistantSnapshot, Dict[str, Dict[str, Any]]]:
        normalized_config = self._normalized_config(config)
        upload_group, upload_plan = self._build_upload_cleanup_group(jobs)
        download_group, download_plan = self._build_download_cleanup_group(normalized_config, jobs, output_shelf)
        history_group, history_plan = self._build_history_cleanup_group(normalized_config, jobs, output_shelf)
        groups = [upload_group, download_group, history_group]

        total_safe_count = sum(group.safe_count for group in groups)
        total_safe_bytes = sum(group.safe_bytes for group in groups)
        protected_count = sum(group.protected_count for group in groups)
        protected_bytes = sum(group.protected_bytes for group in groups)
        visible = any(group.safe_count or group.protected_count for group in groups)

        if total_safe_count:
            headline = f"Có {total_safe_count} mục an toàn để dọn ngay"
            if protected_count:
                summary = (
                    f"Em đã tách riêng {total_safe_count} mục an toàn khỏi {protected_count} mục còn mới hoặc còn quan trọng. "
                    "Các nút dọn chỉ xóa trong phạm vi đã được phân loại sẵn."
                )
            else:
                summary = "Các mục hiện có đều nằm trong phạm vi an toàn đã được phân loại sẵn để dọn."
        elif protected_count:
            headline = "Chưa có mục an toàn để dọn"
            summary = (
                "Uploads, downloads và history hiện vẫn còn mới hoặc còn gắn với artifact local quan trọng, "
                "nên em đang giữ lại mặc định."
            )
        else:
            headline = ""
            summary = ""

        return (
            CleanupAssistantSnapshot(
                visible=visible,
                headline=headline,
                summary=summary,
                total_safe_count=total_safe_count,
                total_safe_bytes=total_safe_bytes,
                protected_count=protected_count,
                protected_bytes=protected_bytes,
                groups=groups,
            ),
            {
                "uploads": upload_plan,
                "downloads": download_plan,
                "history": history_plan,
            },
        )

    def _build_upload_cleanup_group(self, jobs: List[JobRecord]) -> tuple[CleanupGroupSnapshot, Dict[str, Any]]:
        root = UPLOADS_DIR.resolve()
        references: Dict[str, Dict[str, int]] = {}

        for job in jobs:
            job_input = job.input if isinstance(job.input, dict) else {}
            raw_paths = [str(job_input.get("start_image_path", "") or "").strip()]
            raw_paths.extend(
                str(item or "").strip()
                for item in job_input.get("reference_image_paths", [])
                if str(item or "").strip()
            )
            for raw_path in raw_paths:
                if not raw_path:
                    continue
                try:
                    path = Path(raw_path).expanduser().resolve()
                except OSError:
                    continue
                if not self._path_within_roots(path, [root]):
                    continue

                key = str(path)
                ref = references.setdefault(key, {"active": 0, "terminal": 0, "total": 0})
                ref["total"] += 1
                if job.status in {"queued", "running", "polling"}:
                    ref["active"] += 1
                else:
                    ref["terminal"] += 1

        safe_entries: List[Dict[str, Any]] = []
        protected_entries: List[Dict[str, Any]] = []
        safe_paths: List[Path] = []
        for path in self._list_cleanup_files([root]):
            modified_at = self._path_modified_datetime(path)
            size_bytes = self._file_size(path)
            ref = references.get(str(path), {"active": 0, "terminal": 0, "total": 0})
            active_count = int(ref.get("active", 0) or 0)
            terminal_count = int(ref.get("terminal", 0) or 0)
            is_recent = self._is_recent_datetime(modified_at, hours=self.CLEANUP_UPLOAD_GRACE_HOURS)

            if active_count:
                detail = f"Ảnh đầu vào này đang được {active_count} job chưa xong tham chiếu, nên em giữ lại."
                protected_entries.append({
                    "path": path,
                    "bytes": size_bytes,
                    "snapshot": self._cleanup_file_item(
                        path,
                        root,
                        detail=detail,
                        size_bytes=size_bytes,
                        status="protected",
                    ),
                })
                continue

            if is_recent:
                detail = (
                    f"Upload này mới xuất hiện trong khoảng {self.CLEANUP_UPLOAD_GRACE_HOURS} giờ gần đây. "
                    "App giữ lại để tránh xóa nhầm trước khi dùng."
                )
                if terminal_count:
                    detail += f" Nó đã từng được dùng cho {terminal_count} job đã xong."
                protected_entries.append({
                    "path": path,
                    "bytes": size_bytes,
                    "snapshot": self._cleanup_file_item(
                        path,
                        root,
                        detail=detail,
                        size_bytes=size_bytes,
                        status="protected",
                    ),
                })
                continue

            detail = "File tạm đã cũ và không còn job đang chạy nào giữ lại."
            if terminal_count:
                detail += f" Nó từng được dùng cho {terminal_count} job đã xong."
            safe_paths.append(path)
            safe_entries.append({
                "path": path,
                "bytes": size_bytes,
                "snapshot": self._cleanup_file_item(
                    path,
                    root,
                    detail=detail,
                    size_bytes=size_bytes,
                    status="safe",
                ),
            })

        safe_entries.sort(key=lambda item: item["snapshot"].path_hint)
        protected_entries.sort(key=lambda item: item["snapshot"].path_hint)
        safe_count = len(safe_entries)
        safe_bytes = sum(item["bytes"] for item in safe_entries)
        protected_count = len(protected_entries)
        protected_bytes = sum(item["bytes"] for item in protected_entries)

        if safe_count:
            summary = "Uploads tạm đã cũ có thể dọn ngay mà không ảnh hưởng các job đang chạy."
        elif protected_count:
            summary = "Uploads hiện còn mới hoặc còn bị job đang chạy giữ lại, nên em chưa xếp chúng vào nhóm an toàn."
        else:
            summary = "Chưa có upload tạm nào để phân loại."

        group = CleanupGroupSnapshot(
            key="uploads",
            label="Uploads tạm",
            action_label="Dọn uploads tạm",
            summary=summary,
            empty_label="Chưa có upload tạm nào cần dọn.",
            safe_count=safe_count,
            safe_bytes=safe_bytes,
            protected_count=protected_count,
            protected_bytes=protected_bytes,
            notes=[
                "Chỉ quét trong thư mục uploads của app.",
                "Upload mới hoặc đang bị job chưa xong tham chiếu sẽ được giữ lại mặc định.",
            ],
            safe_items=[entry["snapshot"] for entry in safe_entries[: self.CLEANUP_PREVIEW_LIMIT]],
            protected_items=[entry["snapshot"] for entry in protected_entries[: self.CLEANUP_PREVIEW_LIMIT]],
        )
        return group, {"paths": safe_paths, "artifact_refs": {}, "job_ids": []}

    def _build_download_cleanup_group(
        self,
        config: AppConfig,
        jobs: List[JobRecord],
        output_shelf: OutputShelfSnapshot,
    ) -> tuple[CleanupGroupSnapshot, Dict[str, Any]]:
        roots = self._download_cleanup_roots()
        reference_map = self._download_artifact_reference_map(jobs, roots)
        shelf_keys = {
            f"{item.job_id}:{int(item.artifact_index)}"
            for item in (output_shelf.items if output_shelf and output_shelf.items else [])
        }
        active_workflow_id = str(config.active_workflow_id or "").strip()

        safe_entries: List[Dict[str, Any]] = []
        protected_entries: List[Dict[str, Any]] = []
        safe_paths: List[Path] = []
        artifact_refs: Dict[str, List[tuple[str, int]]] = {}
        for path in self._list_cleanup_files(roots):
            size_bytes = self._file_size(path)
            refs = reference_map.get(str(path), [])
            protection_reasons = self._download_protection_reasons(refs, shelf_keys, active_workflow_id)

            if protection_reasons:
                protected_entries.append({
                    "path": path,
                    "bytes": size_bytes,
                    "snapshot": self._cleanup_file_item(
                        path,
                        self._matching_cleanup_root(path, roots),
                        detail=" ".join(protection_reasons[:2]),
                        size_bytes=size_bytes,
                        status="protected",
                    ),
                })
                continue

            if refs:
                detail = (
                    f"Artifact local này đã cũ hơn {self.CLEANUP_DOWNLOAD_RETENTION_DAYS} ngày "
                    "và không còn nằm trong nhóm output quan trọng gần đây."
                )
                artifact_refs[str(path)] = [(entry["job"].id, entry["artifact_index"]) for entry in refs]
            else:
                detail = "Tệp đã tải này không còn job history nào tham chiếu, nên có thể dọn an toàn."
                artifact_refs[str(path)] = []

            safe_paths.append(path)
            safe_entries.append({
                "path": path,
                "bytes": size_bytes,
                "snapshot": self._cleanup_file_item(
                    path,
                    self._matching_cleanup_root(path, roots),
                    detail=detail,
                    size_bytes=size_bytes,
                    status="safe",
                ),
            })

        safe_entries.sort(key=lambda item: item["snapshot"].path_hint)
        protected_entries.sort(key=lambda item: item["snapshot"].path_hint)
        safe_count = len(safe_entries)
        safe_bytes = sum(item["bytes"] for item in safe_entries)
        protected_count = len(protected_entries)
        protected_bytes = sum(item["bytes"] for item in protected_entries)

        if safe_count:
            summary = (
                "Các file đã tải cũ hoặc không còn tham chiếu sẽ được xóa, "
                "đồng thời metadata local liên quan trong history cũng được làm sạch."
            )
        elif protected_count:
            summary = "Các file đã tải hiện còn mới, còn nằm trên output shelf hoặc còn gắn với workflow quan trọng nên em giữ lại."
        else:
            summary = "Chưa có file đã tải nào để phân loại."

        group = CleanupGroupSnapshot(
            key="downloads",
            label="Downloads đã lưu",
            action_label="Dọn file đã tải",
            summary=summary,
            empty_label="Chưa có file đã tải nào cần dọn.",
            safe_count=safe_count,
            safe_bytes=safe_bytes,
            protected_count=protected_count,
            protected_bytes=protected_bytes,
            notes=[
                "Chỉ xóa file nằm trong thư mục tải xuống an toàn của app.",
                "Artifact local còn mới, còn trên output shelf hoặc còn trùng workflow mặc định sẽ được giữ lại mặc định.",
            ],
            safe_items=[entry["snapshot"] for entry in safe_entries[: self.CLEANUP_PREVIEW_LIMIT]],
            protected_items=[entry["snapshot"] for entry in protected_entries[: self.CLEANUP_PREVIEW_LIMIT]],
        )
        return group, {"paths": safe_paths, "artifact_refs": artifact_refs, "job_ids": []}

    def _build_history_cleanup_group(
        self,
        config: AppConfig,
        jobs: List[JobRecord],
        output_shelf: OutputShelfSnapshot,
    ) -> tuple[CleanupGroupSnapshot, Dict[str, Any]]:
        safe_entries: List[CleanupItemSnapshot] = []
        protected_entries: List[CleanupItemSnapshot] = []
        removable_job_ids: List[str] = []
        shelf_job_ids = {item.job_id for item in (output_shelf.items if output_shelf and output_shelf.items else [])}
        active_workflow_id = str(config.active_workflow_id or "").strip()

        for job in jobs:
            job_activity = self._job_activity_datetime(job)
            is_recent = self._is_recent_datetime(job_activity, days=self.CLEANUP_HISTORY_RETENTION_DAYS)
            has_local_files = self._job_has_existing_local_artifacts(job)
            touches_active_workflow = self._job_touches_workflow(job, active_workflow_id)

            protected_reason = ""
            if job.status in {"queued", "running", "polling"}:
                protected_reason = "Job này vẫn chưa hoàn tất nên history cần được giữ nguyên."
            elif has_local_files:
                protected_reason = "Job này vẫn còn file local trên máy, nên app giữ history để lần lại artifact."
            elif job.id in shelf_job_ids:
                protected_reason = "Job này vẫn đang góp mặt trong output shelf gần đây."
            elif is_recent:
                protected_reason = f"Job này còn mới trong khoảng {self.CLEANUP_HISTORY_RETENTION_DAYS} ngày gần đây."
            elif touches_active_workflow:
                protected_reason = "Job này còn khớp workflow mặc định đang ghim, nên em giữ lại mặc định."

            if protected_reason:
                protected_entries.append(self._cleanup_job_item(job, protected_reason, status="protected"))
                continue

            if job.type == "login":
                detail = "Lịch sử đăng nhập cũ có thể gỡ đi mà không ảnh hưởng phiên hiện tại."
            elif job.status in {"failed", "interrupted"}:
                detail = "Job lỗi cũ này có thể gỡ khỏi history để bảng tác vụ gọn hơn."
            else:
                detail = "Metadata job hoàn tất đã cũ và không còn giữ file local trên máy."

            removable_job_ids.append(job.id)
            safe_entries.append(self._cleanup_job_item(job, detail, status="safe"))

        safe_count = len(safe_entries)
        protected_count = len(protected_entries)
        if safe_count:
            summary = "Các job cũ này chỉ còn là metadata, nên có thể gỡ khỏi history mà không đụng tới file local còn tồn tại."
        elif protected_count:
            summary = "History hiện chỉ còn các job mới hơn hoặc vẫn còn gắn với artifact local cần giữ."
        else:
            summary = "History hiện chưa có mục cũ nào cần dọn."

        group = CleanupGroupSnapshot(
            key="history",
            label="History cũ",
            action_label="Dọn history cũ",
            summary=summary,
            empty_label="Chưa có metadata history nào cần dọn.",
            safe_count=safe_count,
            safe_bytes=0,
            protected_count=protected_count,
            protected_bytes=0,
            notes=[
                "Chỉ gỡ metadata job cũ khỏi state của app.",
                "Job còn mới hoặc còn gắn với file local trên máy sẽ được giữ lại mặc định.",
            ],
            safe_items=safe_entries[: self.CLEANUP_PREVIEW_LIMIT],
            protected_items=protected_entries[: self.CLEANUP_PREVIEW_LIMIT],
        )
        return group, {"paths": [], "artifact_refs": {}, "job_ids": removable_job_ids}

    def _download_cleanup_roots(self) -> List[Path]:
        roots = [DOWNLOADS_DIR.resolve()]
        configured = str(self.store.snapshot().config.output_dir or "").strip()
        if configured:
            try:
                roots.insert(0, Path(configured).expanduser().resolve())
            except OSError:
                pass

        unique_roots: List[Path] = []
        seen: set[str] = set()
        for root in roots:
            key = str(root)
            if key in seen:
                continue
            seen.add(key)
            unique_roots.append(root)
        return unique_roots

    def _download_artifact_reference_map(
        self,
        jobs: List[JobRecord],
        roots: List[Path],
    ) -> Dict[str, List[Dict[str, Any]]]:
        references: Dict[str, List[Dict[str, Any]]] = {}
        for job in jobs:
            job_input = job.input if isinstance(job.input, dict) else {}
            for artifact_index, artifact in enumerate(job.artifacts):
                raw_path = str(artifact.local_path or "").strip()
                if not raw_path:
                    continue
                try:
                    path = Path(raw_path).expanduser().resolve()
                except OSError:
                    continue
                if not self._path_within_roots(path, roots):
                    continue
                references.setdefault(str(path), []).append({
                    "job": job,
                    "job_input": job_input,
                    "artifact": artifact,
                    "artifact_index": artifact_index,
                })
        return references

    def _download_protection_reasons(
        self,
        refs: List[Dict[str, Any]],
        shelf_keys: set[str],
        active_workflow_id: str,
    ) -> List[str]:
        reasons: List[str] = []
        for entry in refs:
            job = entry["job"]
            artifact = entry["artifact"]
            artifact_index = int(entry["artifact_index"])
            workflow_id = str(artifact.workflow_id or entry["job_input"].get("workflow_id", "") or "").strip()
            activity_at = self._job_activity_datetime(job)

            if job.status in {"queued", "running", "polling"}:
                reasons.append("Tệp này vẫn gắn với job chưa hoàn tất.")
            if self._is_recent_datetime(activity_at, days=self.CLEANUP_DOWNLOAD_RETENTION_DAYS):
                reasons.append(f"Job này còn mới trong khoảng {self.CLEANUP_DOWNLOAD_RETENTION_DAYS} ngày gần đây.")
            if f"{job.id}:{artifact_index}" in shelf_keys:
                reasons.append("Artifact này vẫn đang nằm trên output shelf gần đây.")
            if active_workflow_id and workflow_id and workflow_id == active_workflow_id:
                reasons.append("Artifact này còn thuộc workflow mặc định đang ghim.")

        deduped: List[str] = []
        seen: set[str] = set()
        for reason in reasons:
            if reason in seen:
                continue
            seen.add(reason)
            deduped.append(reason)
        return deduped

    def _cleanup_file_item(
        self,
        path: Path,
        root: Path,
        *,
        detail: str,
        size_bytes: int,
        status: str,
    ) -> CleanupItemSnapshot:
        status_label = "An toàn để xóa" if status == "safe" else "Đang giữ lại"
        relative_path = path.name
        try:
            relative_path = str(path.relative_to(root))
        except ValueError:
            relative_path = path.name
        return CleanupItemSnapshot(
            key=str(path),
            label=path.name,
            detail=detail,
            path_hint=f"{root.name}/{relative_path}".replace("\\", "/"),
            bytes=size_bytes,
            status=status,
            status_label=status_label,
        )

    def _cleanup_job_item(self, job: JobRecord, detail: str, *, status: str) -> CleanupItemSnapshot:
        status_label = "An toàn để xóa" if status == "safe" else "Đang giữ lại"
        return CleanupItemSnapshot(
            key=job.id,
            label=job.title or self._job_type_label(job.type),
            detail=f"{self._job_type_label(job.type)} · {detail}",
            path_hint=f"job {job.id[:8]}",
            bytes=0,
            status=status,
            status_label=status_label,
        )

    def _job_has_existing_local_artifacts(self, job: JobRecord) -> bool:
        for artifact in job.artifacts:
            if str(artifact.local_path or "").strip() and self._artifact_local_exists(str(artifact.local_path or "").strip()):
                return True
        return False

    def _job_touches_workflow(self, job: JobRecord, workflow_id: str) -> bool:
        safe_workflow_id = str(workflow_id or "").strip()
        if not safe_workflow_id:
            return False
        job_input = job.input if isinstance(job.input, dict) else {}
        if str(job_input.get("workflow_id", "") or "").strip() == safe_workflow_id:
            return True
        return any(str(artifact.workflow_id or "").strip() == safe_workflow_id for artifact in job.artifacts)

    def _list_cleanup_files(self, roots: List[Path]) -> List[Path]:
        files: List[Path] = []
        seen: set[str] = set()
        for root in roots:
            if not root.exists() or not root.is_dir():
                continue
            for candidate in root.rglob("*"):
                if not candidate.is_file() or candidate.name == ".gitkeep":
                    continue
                try:
                    resolved = candidate.resolve()
                except OSError:
                    continue
                key = str(resolved)
                if key in seen or not self._path_within_roots(resolved, [root]):
                    continue
                seen.add(key)
                files.append(resolved)
        return files

    def _matching_cleanup_root(self, path: Path, roots: List[Path]) -> Path:
        for root in roots:
            if self._path_within_roots(path, [root]):
                return root
        return roots[0]

    def _path_within_roots(self, path: Path, roots: List[Path]) -> bool:
        for root in roots:
            try:
                path.relative_to(root)
            except ValueError:
                continue
            return True
        return False

    def _path_modified_datetime(self, path: Path) -> datetime | None:
        try:
            stat = path.stat()
        except OSError:
            return None
        return datetime.fromtimestamp(stat.st_mtime, tz=timezone.utc)

    def _is_recent_datetime(self, value: datetime | None, *, days: int = 0, hours: int = 0) -> bool:
        if value is None:
            return False
        threshold = datetime.now(timezone.utc) - timedelta(days=max(0, days), hours=max(0, hours))
        return value >= threshold

    def _file_size(self, path: Path) -> int:
        try:
            return int(path.stat().st_size)
        except OSError:
            return 0

    def _delete_cleanup_file(self, path: Path, roots: List[Path]) -> str:
        try:
            resolved = Path(path).expanduser().resolve()
        except OSError as exc:
            raise HTTPException(status_code=400, detail=f"Không thể xác định tệp cần dọn: {path}") from exc

        if not self._path_within_roots(resolved, roots):
            raise HTTPException(status_code=403, detail="Tệp cần dọn nằm ngoài phạm vi an toàn của app.")
        if resolved.exists() and not resolved.is_file():
            raise HTTPException(status_code=400, detail="Cleanup chỉ hỗ trợ xóa tệp, không xóa thư mục.")
        if resolved.exists():
            resolved.unlink()
        return str(resolved)

    def _public_download_url(self, local_path: str) -> str:
        path = Path(local_path).resolve()
        default_root = DOWNLOADS_DIR.resolve()
        if str(path).startswith(str(default_root)):
            return f"/files/downloads/{path.name}"
        return ""

    def _validate_job_request(self, request: CreateJobRequest) -> None:
        if request.type != "login" and not self.get_auth_status().authenticated:
            raise HTTPException(
                status_code=400,
                detail="Cần đăng nhập Google Flow trước khi chạy tác vụ. Hãy bấm Đăng nhập Google Flow rồi thử lại.",
            )

        if request.type == "video" and not request.prompt.strip():
            raise HTTPException(status_code=400, detail="Hãy nhập mô tả video trước khi chạy.")

        if request.type == "image" and not request.prompt.strip():
            raise HTTPException(status_code=400, detail="Hãy nhập mô tả ảnh trước khi chạy.")

        if request.type == "image" and len(request.reference_image_paths) > 4:
            raise HTTPException(status_code=400, detail="Tối đa 4 ảnh tham chiếu cho một lượt chỉnh ảnh.")

        if request.type == "video" and len(request.reference_image_paths) > 4:
            raise HTTPException(status_code=400, detail="Tối đa 4 ảnh tham chiếu cho một lượt tạo video.")

        if request.type in {"video", "image"}:
            max_count = self.FLOW_AGENT_MAX_OUTPUT_COUNT if request.type == "image" and self._flow_agent_enabled_for_request(request) else 4
            if not 1 <= int(request.count) <= max_count:
                raise HTTPException(status_code=400, detail=f"Số lượng cho tác vụ tạo nội dung phải nằm trong khoảng 1 đến {max_count}.")

        if request.type == "image" and self._normalize_image_model(request.model) not in self.IMAGE_MODEL_LABELS:
            raise HTTPException(status_code=400, detail="Model ảnh này hiện chưa được hỗ trợ trong app.")

        if request.type in {"extend", "upscale", "camera_motion", "camera_position", "insert", "remove"}:
            if not request.media_id.strip():
                raise HTTPException(status_code=400, detail="Vui lòng nhập Media ID cho tác vụ chỉnh sửa.")

        if request.type == "camera_motion" and not request.motion.strip():
            raise HTTPException(status_code=400, detail="Vui lòng chọn chuyển động camera.")

        if request.type == "camera_position" and not request.position.strip():
            raise HTTPException(status_code=400, detail="Vui lòng chọn vị trí camera.")

        if request.type == "insert" and not request.prompt.strip():
            raise HTTPException(status_code=400, detail="Vui lòng nhập prompt để chèn vật thể.")

    def _image_api_aspect_ratio(self, aspect: str) -> str:
        normalized = self._parse_aspect(aspect or "landscape")
        if normalized == "portrait":
            return "IMAGE_ASPECT_RATIO_PORTRAIT"
        if normalized == "square":
            return "IMAGE_ASPECT_RATIO_SQUARE"
        return "IMAGE_ASPECT_RATIO_LANDSCAPE"

    def _normalize_video_model(self, model: str) -> str:
        raw = str(model or "").strip()
        if not raw:
            return self.DEFAULT_VIDEO_MODEL
        compact = re.sub(r"\s+", " ", raw).strip().lower()
        return self.VIDEO_MODEL_DISPLAY_ALIASES.get(compact, raw)

    def _normalize_image_model(self, model: str) -> str:
        raw = str(model or "").strip()
        if not raw:
            return self.DEFAULT_IMAGE_MODEL
        compact = re.sub(r"\s+", " ", raw).strip().lower()
        normalized = self.IMAGE_MODEL_ALIASES.get(compact, raw.upper())
        if normalized not in self.IMAGE_MODEL_LABELS:
            return self.DEFAULT_IMAGE_MODEL
        return normalized

    def _normalize_job_model(self, request_type: str, model: str) -> str:
        kind = str(request_type or "").strip()
        if kind == "video":
            return self._normalize_video_model(model)
        if kind == "image":
            return self._normalize_image_model(model)
        return str(model or "").strip()

    def _normalize_policy_text(self, value: str) -> str:
        raw = str(value or "").strip()
        if not raw:
            return ""
        normalized = unicodedata.normalize("NFD", raw)
        normalized = "".join(char for char in normalized if unicodedata.category(char) != "Mn")
        normalized = re.sub(r"[^a-zA-Z0-9\s]", " ", normalized).lower()
        return re.sub(r"\s+", " ", normalized).strip()

    def _policy_text_has_any(self, text: str, terms: tuple[str, ...]) -> bool:
        if not text:
            return False
        return any(term in text for term in terms)

    def _policy_preflight_notice(self, request: CreateJobRequest) -> str:
        normalized_prompt = self._normalize_policy_text(request.prompt)
        has_minor = self._policy_text_has_any(normalized_prompt, self.POLICY_MINOR_TERMS)
        has_appearance = self._policy_text_has_any(normalized_prompt, self.POLICY_APPEARANCE_TERMS)
        has_apparel = self._policy_text_has_any(normalized_prompt, self.POLICY_APPAREL_TERMS)
        normalized_roles = self._normalize_reference_image_roles(
            list(request.reference_image_paths or []),
            list(request.reference_image_roles or []),
        )
        has_reference_images = bool(request.start_image_path or request.reference_image_paths or request.reference_media_names)
        has_product_images = any(role == "product" for role in normalized_roles)

        if has_minor and (has_appearance or has_apparel or has_reference_images):
            return (
                "Cảnh báo an toàn: prompt này có nguy cơ bị Google Flow chặn nếu ảnh hoặc mô tả ám chỉ người chưa đủ tuổi. "
                "Nếu đang làm quần áo, logo hoặc beauty edit, hãy đổi sang người mẫu trưởng thành rõ ràng, mannequin hoặc flat-lay."
            )

        if has_reference_images and (has_appearance or has_apparel or has_product_images):
            return (
                "Gợi ý an toàn: nếu ảnh tham chiếu là người trông quá trẻ, Google Flow thường chặn các ca thay đồ, ghép logo lên áo hoặc làm đẹp ngoại hình. "
                "Chủ nhân nên dùng người mẫu trưởng thành, mannequin hoặc ảnh sản phẩm riêng."
            )

        return ""

    def _image_api_model_name(self, model: str) -> str:
        return self._normalize_image_model(model)

    def _image_edit_model_name(self, model: str) -> str:
        normalized = self._normalize_image_model(model)
        return self.IMAGE_MODEL_EDIT_VALUES.get(normalized, self.IMAGE_MODEL_EDIT_VALUES[self.DEFAULT_IMAGE_MODEL])

    def _image_ui_model_label(self, model: str) -> str:
        normalized = self._normalize_image_model(model)
        return self.IMAGE_MODEL_LABELS.get(normalized, self.IMAGE_MODEL_LABELS[self.DEFAULT_IMAGE_MODEL])

    def _normalize_reference_image_role(self, role: str) -> str:
        normalized = re.sub(r"[^a-z]+", "", str(role or "").strip().lower())
        if normalized in {"base", "main", "model", "subject", "primary"}:
            return "base"
        if normalized in {"logo", "brand"}:
            return "logo"
        if normalized in {"product", "item"}:
            return "product"
        return "reference"

    def _start_image_search_terms(self, value: str) -> List[str]:
        raw = str(value or "").strip()
        if not raw:
            return []

        candidates = [raw]
        try:
            path = PureWindowsPath(raw) if ("\\" in raw or re.match(r"^[A-Za-z]:", raw)) else Path(raw)
        except Exception:
            path = None

        if path is not None:
            name = path.name.strip()
            stem = path.stem.strip()
            if name:
                candidates.append(name)
            if stem:
                candidates.append(stem)

        normalized_variants: List[str] = []
        for item in candidates:
            compact = re.sub(r"\s+", " ", str(item or "").strip())
            if compact:
                normalized_variants.append(compact)
            simple = re.sub(r"[^a-z0-9]+", " ", str(item or "").strip().lower())
            simple = re.sub(r"\s+", " ", simple).strip()
            if simple:
                normalized_variants.append(simple)

        ordered: List[str] = []
        seen: set[str] = set()
        for item in normalized_variants:
            key = item.lower()
            if not key or key in seen:
                continue
            seen.add(key)
            ordered.append(item)
        return ordered

    def _normalize_reference_image_roles(self, image_paths: List[str], roles: List[str]) -> List[str]:
        path_count = len(image_paths or [])
        if path_count <= 0:
            return []

        normalized = [
            self._normalize_reference_image_role(roles[index] if index < len(roles or []) else "")
            for index in range(path_count)
        ]
        if "base" not in normalized:
            normalized[0] = "base"
        else:
            base_index = normalized.index("base")
            normalized = ["reference" if role == "base" and index != base_index else role for index, role in enumerate(normalized)]
        return normalized

    def _ordered_reference_media_names(
        self,
        media_items: List[Dict[str, str]],
        fallback_names: List[str] | None = None,
    ) -> List[str]:
        ordered: List[str] = []
        seen: set[str] = set()

        def push(name: str) -> None:
            safe_name = str(name or "").strip()
            if not safe_name or safe_name in seen:
                return
            seen.add(safe_name)
            ordered.append(safe_name)

        for role in ("base", "product", "logo", "reference"):
            for item in media_items:
                if str(item.get("role") or "") == role:
                    push(item.get("media_name", ""))

        for name in fallback_names or []:
            push(name)
        return ordered

    def _normalize_local_upload_paths(self, values: List[str]) -> List[str]:
        roots = [UPLOADS_DIR.resolve()]
        normalized: List[str] = []
        seen: set[str] = set()
        for value in values:
            raw = str(value or "").strip()
            if not raw:
                continue
            try:
                resolved = Path(raw).expanduser().resolve()
            except OSError:
                continue
            if not resolved.exists() or not resolved.is_file():
                continue
            if not self._path_within_roots(resolved, roots):
                continue
            key = str(resolved)
            if key in seen:
                continue
            seen.add(key)
            normalized.append(key)
        return normalized

    def _video_reference_prompt_suffix(self, request: CreateJobRequest) -> str:
        prompt_text = self._normalize_skill_token(request.prompt or "")
        suffix_parts = [
            "first storyboard keyframe for a later image-to-video shot",
            "cinematic hero frame with clean full-subject readability",
            "keep the exact product design, logo placement, fabric color, material texture, and silhouette from the reference images",
            "if the reference image is clothing, accessories, or a product, place it naturally on a photoreal human model or in a believable real-world usage scene instead of leaving it as a flat packshot",
            "strong continuity-ready frame that can animate cleanly into a video",
        ]
        if any(
            token in prompt_text
            for token in (
                "ao",
                "shirt",
                "tshirt",
                "hoodie",
                "fashion",
                "thoi trang",
                "jacket",
                "dress",
                "quan",
                "giay",
                "shoe",
                "bag",
            )
        ):
            suffix_parts.append("show a photoreal fashion model wearing the referenced item naturally")
        if any(token in prompt_text for token in ("logo", "brand", "thuong hieu", "nhan")):
            suffix_parts.append("preserve brand marks sharply and naturally on the product")
        return ", ".join(suffix_parts)

    def _video_start_frame_prompt(self, request: CreateJobRequest) -> str:
        selected = self._select_prompt_skills(
            "image",
            request.prompt,
            "cinematic start frame for video",
            self._video_reference_prompt_suffix(request),
        )
        baseline = self._compose_prompt_draft(
            PromptCreateRequest(
                mode="image",
                brief=request.prompt,
                style="cinematic start frame for video",
                must_include=self._video_reference_prompt_suffix(request),
                avoid="flat lay ecommerce photo, isolated catalog cutout, watermark, broken anatomy",
                audience="video generation start frame",
                aspect=self._parse_aspect(request.aspect or "landscape"),
            ),
            selected,
        )
        prompt, _ = self._ensure_prompt_detail(baseline, baseline, "image")
        return prompt

    async def _download_intermediate_image(
        self,
        client: Any,
        job_id: str,
        source_url: str,
        *,
        suffix: str = ".jpg",
    ) -> str:
        target = UPLOADS_DIR / f"{job_id}-video-start{suffix}"
        target.parent.mkdir(parents=True, exist_ok=True)
        try:
            saved = await client.download(source_url, target)
        except Exception as exc:
            raise RuntimeError("Flow đã tạo ảnh khung đầu nhưng app chưa tải ảnh đó về máy để dựng video.") from exc
        return str(Path(saved).expanduser().resolve())

    async def _prepare_video_start_image_from_references(
        self,
        client: Any,
        job_id: str,
        request: CreateJobRequest,
    ) -> tuple[str, str]:
        reference_media_names = await self._resolve_image_reference_media(client, job_id, request)
        if not reference_media_names:
            raise RuntimeError("Chưa có ảnh tham chiếu hợp lệ để dựng khung đầu cho video.")

        prompt = self._video_start_frame_prompt(request)
        await self.store.append_log(job_id, "Đang dùng ảnh tham chiếu để dựng một ảnh khung đầu trước khi tạo video.")
        await self._set_job_progress(
            job_id,
            "sending_request",
            "Em đang dựng một ảnh khung đầu từ ảnh tham chiếu để dùng tiếp cho bước tạo video.",
        )
        image_request = CreateJobRequest(
            type="image",
            prompt=prompt,
            model=self.DEFAULT_IMAGE_MODEL,
            aspect=request.aspect,
            count=1,
            timeout_s=max(30, int(request.timeout_s or self.store.snapshot().config.generation_timeout_s or 300)),
            reference_media_names=reference_media_names,
            workflow_id=request.workflow_id or "",
        )
        images = await self._generate_images_with_retry(client, job_id, image_request, reference_media_names)
        if not images:
            raise RuntimeError("Flow chưa dựng được ảnh khung đầu từ các ảnh tham chiếu.")

        first_image = images[0]
        source_url = str(getattr(first_image, "fife_url", "") or "").strip()
        if not source_url:
            raise RuntimeError("Flow đã dựng ảnh khung đầu nhưng chưa trả URL ảnh để tiếp tục tạo video.")
        local_path = await self._download_intermediate_image(client, job_id, source_url)
        current_job = self.store.get_job(job_id)
        current_result = dict(getattr(current_job, "result", {}) or {})
        current_result.update(
            {
                "auto_start_frame_path": local_path,
                "auto_start_frame_public_url": f"/files/uploads/{Path(local_path).name}",
                "auto_start_frame_prompt": prompt,
                "auto_start_frame_at": utc_now(),
            }
        )
        await self.store.patch_job(job_id, result=current_result)
        await self.store.append_log(job_id, f"Đã dựng xong ảnh khung đầu và lưu tạm tại {Path(local_path).name}.")
        return local_path, prompt

    async def _resolve_image_reference_media(self, client: Any, job_id: str, request: CreateJobRequest) -> List[str]:
        reference_media_names = self._normalize_reference_media_names(request.reference_media_names or [])
        reference_image_paths = self._normalize_local_upload_paths(request.reference_image_paths or [])
        if not reference_image_paths:
            return reference_media_names

        reference_roles = self._normalize_reference_image_roles(reference_image_paths, request.reference_image_roles or [])
        total = len(reference_image_paths)
        allow_local_flow_agent_fallback = self._request_requires_flow_agent_ui(request) and self._flow_agent_enabled_for_request(request)
        await self.store.append_log(job_id, f"Đang chuẩn bị {total} ảnh tham chiếu để ghép/chỉnh ảnh.")
        uploaded_items: List[Dict[str, str]] = []
        for index, image_path in enumerate(reference_image_paths):
            role = reference_roles[index] if index < len(reference_roles) else ("base" if index == 0 else "reference")
            role_label = self.REFERENCE_IMAGE_ROLE_LABELS.get(role, "tham chiếu")
            await self._set_job_progress(
                job_id,
                "sending_request",
                f"Em đang tải ảnh {role_label} {index + 1}/{total} lên Flow trước khi chỉnh ảnh.",
            )
            await self.store.append_log(job_id, f"Đang tải ảnh {role_label} {index + 1}/{total}: {Path(image_path).name}")
            try:
                media_name = await self._upload_project_image_robust(client, image_path)
            except Exception as exc:
                if not allow_local_flow_agent_fallback:
                    raise
                await self.store.append_log(
                    job_id,
                    (
                        f"Flow project upload failed for {Path(image_path).name}; "
                        "will attach the local source file directly inside Flow Agent instead. "
                        f"Detail: {humanize_flow_error(str(exc))[:180]}"
                    ),
                )
                continue
            if media_name:
                uploaded_items.append({"role": role, "media_name": media_name})

        return self._ordered_reference_media_names(uploaded_items, reference_media_names)

    async def _upload_project_image_robust(self, client: Any, image_path: str) -> str:
        image_file = Path(str(image_path or "")).expanduser().resolve()
        # Any file dialog opened by the upload triggers below must receive this file, never the OS dialog.
        self._flow_agent_chooser_file = str(image_file)
        self._flow_agent_chooser_expecting = False
        if not image_file.exists():
            raise RuntimeError(f"Khong tim thay anh de tai len: {image_file}")

        page = await client._bm.page()
        project_url = str(
            getattr(client, "_project_url", "")
            or getattr(getattr(client, "_api", None), "_project_page_url", "")
            or self._project_url(getattr(client, "project_id", ""))
        ).strip()
        await self._ensure_valid_flow_project_page(page, project_url)

        before_data = await client._api.get_project_data()
        known_media = self._project_media_names(before_data)

        selectors = [
            'input[type="file"][accept*="image"]',
            'input[type="file"]',
        ]
        uploaded = False
        for selector in selectors:
            locator = page.locator(selector)
            count = await locator.count()
            for index in range(count):
                candidate = locator.nth(index)
                try:
                    await candidate.set_input_files(str(image_file))
                    uploaded = True
                    break
                except Exception:
                    continue
            if uploaded:
                break

        if not uploaded:
            for trigger in (
                page.locator("button").filter(has_text="Add Media").first,
                page.get_by_text("Add Media", exact=True).first,
                page.locator("button").filter(has_text="Upload image").first,
                page.get_by_text("Upload image", exact=True).first,
            ):
                try:
                    if await trigger.count() == 0:
                        continue
                    await trigger.click(force=True)
                    await asyncio.sleep(0.5)
                    for selector in selectors:
                        locator = page.locator(selector)
                        count = await locator.count()
                        for index in range(count):
                            candidate = locator.nth(index)
                            try:
                                await candidate.set_input_files(str(image_file))
                                uploaded = True
                                break
                            except Exception:
                                continue
                        if uploaded:
                            break
                    if uploaded:
                        break
                except Exception:
                    continue

        if not uploaded:
            self._install_flow_page_file_chooser_guard(page)
            trigger_locators = [
                page.locator('[aria-label*="Upload" i]').first,
                page.locator('[aria-label*="Tải" i]').first,
                page.locator('[aria-label*="Tai" i]').first,
                page.locator('[aria-label*="Add media" i]').first,
                page.locator('[aria-label*="Add image" i]').first,
                page.locator('[data-testid*="upload" i]').first,
                page.locator("button").filter(has_text=re.compile(r"^\\+$|Upload|Tải|Tai|Thêm|Them|Add", re.I)).first,
                page.locator('[role="button"]').filter(has_text=re.compile(r"^\\+$|Upload|Tải|Tai|Thêm|Them|Add", re.I)).first,
            ]
            for trigger in trigger_locators:
                try:
                    if await trigger.count() == 0:
                        continue
                    try:
                        await trigger.scroll_into_view_if_needed(timeout=1200)
                    except Exception:
                        pass
                    self._flow_agent_chooser_expecting = True
                    try:
                        async with page.expect_file_chooser(timeout=3500) as chooser_info:
                            await trigger.click(force=True, timeout=2500)
                        chooser = await chooser_info.value
                    finally:
                        self._flow_agent_chooser_expecting = False
                    await chooser.set_files(str(image_file))
                    uploaded = True
                    break
                except Exception:
                    try:
                        for selector in selectors:
                            locator = page.locator(selector)
                            count = await locator.count()
                            for index in range(count):
                                candidate = locator.nth(index)
                                try:
                                    await candidate.set_input_files(str(image_file))
                                    uploaded = True
                                    break
                                except Exception:
                                    continue
                            if uploaded:
                                break
                    except Exception:
                        pass
                    if uploaded:
                        break

        if not uploaded:
            raise RuntimeError(f"Failed to upload: {image_file}")

        deadline = time.monotonic() + 25.0
        while time.monotonic() < deadline:
            data = await client._api.get_project_data()
            for workflow in data.get("projectContents", {}).get("workflows", []) or []:
                media_name = str((workflow.get("metadata") or {}).get("primaryMediaId") or "").strip()
                if media_name and media_name not in known_media:
                    return media_name
                for media in workflow.get("medias", []) or []:
                    media_name = str(media.get("name") or "").strip()
                    if media_name and media_name not in known_media:
                        return media_name
            await asyncio.sleep(1.0)

        raise RuntimeError(f"Flow da nhan thao tac upload nhung chua thay anh xuat hien: {image_file.name}")

    def _project_media_names(self, project_data: Dict[str, Any]) -> set[str]:
        names: set[str] = set()
        for media in self._project_media_items(project_data):
            media_name = str(media.get("name") or media.get("mediaName") or "").strip()
            if media_name:
                names.add(media_name)
        for workflow in project_data.get("projectContents", {}).get("workflows", []) or []:
            metadata = workflow.get("metadata", {}) or {}
            primary_media_id = str(metadata.get("primaryMediaId") or "").strip()
            if primary_media_id:
                names.add(primary_media_id)
            for media in workflow.get("medias", []) or []:
                media_name = str(media.get("name") or "").strip()
                if media_name:
                    names.add(media_name)
        return names

    def _project_media_items(self, project_data: Dict[str, Any]) -> List[Dict[str, Any]]:
        project_contents = project_data.get("projectContents", {}) if isinstance(project_data, dict) else {}
        media_collection = project_contents.get("media") if isinstance(project_contents, dict) else None
        if isinstance(media_collection, dict):
            return [item for item in media_collection.values() if isinstance(item, dict)]
        if isinstance(media_collection, list):
            return [item for item in media_collection if isinstance(item, dict)]
        return []

    def _project_workflow_metadata_by_id(self, project_data: Dict[str, Any]) -> Dict[str, Dict[str, Any]]:
        workflows = ((project_data.get("projectContents") or {}).get("workflows") or []) if isinstance(project_data, dict) else []
        metadata_by_id: Dict[str, Dict[str, Any]] = {}
        for workflow in workflows:
            if not isinstance(workflow, dict):
                continue
            workflow_id = str(workflow.get("name") or "").strip()
            if workflow_id:
                metadata_by_id[workflow_id] = workflow.get("metadata", {}) or {}
        return metadata_by_id

    def _project_generated_images(
        self,
        project_data: Dict[str, Any],
        *,
        known_media: set[str] | None = None,
        prompt: str = "",
        limit: int = 4,
        fallback_workflow_id: str = "",
    ) -> List[Any]:
        from flow._api import GeneratedImage

        known = {str(item or "").strip() for item in (known_media or set()) if str(item or "").strip()}
        images: List[Any] = []
        seen: set[str] = set()
        workflow_metadata_by_id = self._project_workflow_metadata_by_id(project_data)

        media_sources = list(self._project_media_items(project_data))
        workflows = project_data.get("projectContents", {}).get("workflows", []) or []
        for workflow in workflows:
            if not isinstance(workflow, dict):
                continue
            workflow_id = str(workflow.get("name") or fallback_workflow_id or "").strip()
            for media_item in workflow.get("medias", []) or []:
                if not isinstance(media_item, dict):
                    continue
                if not media_item.get("workflowId") and workflow_id:
                    media_item = {**media_item, "workflowId": workflow_id, "projectId": media_item.get("projectId") or workflow.get("projectId")}
                media_sources.append(media_item)

        for media_item in media_sources:
            media_name = str(media_item.get("name") or media_item.get("mediaName") or "").strip()
            if not media_name or media_name in known or media_name in seen:
                continue
            image_node = media_item.get("image") or {}
            generated = image_node.get("generatedImage") or {}
            if not generated:
                continue

            workflow_id = str(media_item.get("workflowId") or fallback_workflow_id or "").strip()
            metadata = workflow_metadata_by_id.get(workflow_id, {})
            media_metadata = media_item.get("mediaMetadata", {}) or {}
            request_data = media_metadata.get("requestData", {}) or {}
            workflow_prompt = str(
                generated.get("prompt")
                or metadata.get("displayName")
                or self._prompt_from_flow_request_data(request_data)
                or prompt
                or ""
            ).strip()
            workflow_create_time = str(
                media_metadata.get("createTime")
                or metadata.get("createTime")
                or ""
            ).strip()
            fife_url = str(
                generated.get("fifeUrl")
                or generated.get("url")
                or image_node.get("fifeUrl")
                or media_item.get("fifeUrl")
                or ""
            ).strip()

            image = GeneratedImage.__new__(GeneratedImage)
            image._raw = media_item
            image.media_name = media_name
            image.project_id = str(media_item.get("projectId") or "").strip()
            image.workflow_id = workflow_id
            image.fife_url = fife_url
            image.seed = generated.get("seed", 0)
            image.model = str(generated.get("modelNameType") or generated.get("model") or "").strip()
            image.prompt = workflow_prompt
            image.dimensions = image_node.get("dimensions") or media_item.get("dimensions", {}) or {}
            image.file_path = None
            image._flow_workflow_create_time = workflow_create_time
            images.append(image)
            seen.add(media_name)

        images.sort(key=lambda item: str(getattr(item, "_flow_workflow_create_time", "") or ""), reverse=True)
        return images[: max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(limit or 1)))]

    def _prompt_from_flow_request_data(self, request_data: Dict[str, Any]) -> str:
        prompt_inputs = request_data.get("promptInputs", []) if isinstance(request_data, dict) else []
        for prompt_input in prompt_inputs or []:
            if not isinstance(prompt_input, dict):
                continue
            text_input = str(prompt_input.get("textInput") or "").strip()
            if text_input:
                return text_input
            structured = prompt_input.get("structuredPrompt") or {}
            parts = structured.get("parts", []) if isinstance(structured, dict) else []
            text = " ".join(str(part.get("text") or "").strip() for part in parts if isinstance(part, dict)).strip()
            if text:
                return text
        return ""

    async def _flow_project_image_urls_by_workflow(self, client: Any) -> Dict[str, str]:
        page = await client._bm.page()
        try:
            return await page.evaluate(
                """
                () => {
                  const urls = {};
                  const links = [...document.querySelectorAll('a[href*="/edit/"]')];
                  for (const link of links) {
                    const href = link.href || link.getAttribute('href') || '';
                    const match = href.match(/\\/edit\\/([^/?#]+)/);
                    if (!match) continue;
                    const img = link.querySelector('img[src], img[srcset]');
                    const src = img ? (img.currentSrc || img.src || '') : '';
                    if (src && !src.startsWith('data:')) {
                      urls[match[1]] = src;
                    }
                  }
                  return urls;
                }
                """
            )
        except Exception:
            return {}

    async def _visible_flow_project_images_from_page(
        self,
        client: Any,
        *,
        prompt: str,
        target_count: int,
        fallback_workflow_id: str = "",
        exclude_srcs: set[str] | None = None,
    ) -> List[Any]:
        from flow._api import GeneratedImage

        target = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(target_count or 1)))
        try:
            page = await client._bm.page()
            items = await page.evaluate(
                """
                /* visible-grid-images */
                (limit) => {
                  const visible = (el) => {
                    if (!el || !(el instanceof Element)) return false;
                    const rect = el.getBoundingClientRect();
                    const style = window.getComputedStyle(el);
                    return style.display !== 'none'
                      && style.visibility !== 'hidden'
                      && rect.width >= 120
                      && rect.height >= 120
                      && rect.bottom > 0
                      && rect.right > 0
                      && rect.top < window.innerHeight
                      && rect.left < window.innerWidth;
                  };
                  const srcFor = (img) => {
                    const current = img.currentSrc || img.src || '';
                    if (current) return current;
                    const srcset = img.getAttribute('srcset') || '';
                    return srcset.split(',').map((part) => part.trim().split(/\\s+/)[0]).filter(Boolean).pop() || '';
                  };
                  const toItem = (img, index) => {
                    const rect = img.getBoundingClientRect();
                    const src = srcFor(img);
                    const link = img.closest('a[href*="/edit/"]');
                    const href = link ? link.href || link.getAttribute('href') || '' : '';
                    const workflowMatch = href.match(/\\/edit\\/([^/?#]+)/);
                    const card = img.closest('a[href*="/edit/"], [role="gridcell"], article, li, [data-testid], div');
                    const cardRect = card && card.getBoundingClientRect ? card.getBoundingClientRect() : rect;
                    return {
                      src,
                      workflow_id: workflowMatch ? workflowMatch[1] : '',
                      top: cardRect.top,
                      left: cardRect.left,
                      width: rect.width,
                      height: rect.height,
                      area: rect.width * rect.height,
                      linked: Boolean(link),
                      index,
                    };
                  };
                  const seen = new Set();
                  const all = Array.from(document.querySelectorAll('img[src], img[srcset]'))
                    .filter(visible)
                    .map(toItem)
                    .filter((item) => item.src && !item.src.startsWith('data:') && !item.src.startsWith('blob:'))
                    .filter((item) => item.area >= 18000)
                    .filter((item) => {
                      const key = item.workflow_id || item.src;
                      if (seen.has(key)) return false;
                      seen.add(key);
                      return true;
                    });
                  const linked = all.filter((item) => item.linked);
                  const pool = linked.length >= Math.min(limit, 3) ? linked : all;
                  return pool
                    .sort((a, b) => (a.top - b.top) || (a.left - b.left) || (a.index - b.index))
                    .slice(0, limit)
                    .map((item) => ({
                      src: item.src,
                      workflow_id: item.workflow_id,
                      width: Math.round(item.width),
                      height: Math.round(item.height),
                    }));
                }
                """,
                target,
            )
        except Exception:
            return []

        images: List[Any] = []
        seen_urls: set[str] = set()
        for index, item in enumerate(items if isinstance(items, list) else [], start=1):
            if not isinstance(item, dict):
                continue
            url = str(item.get("src") or "").strip()
            if not url or url in seen_urls:
                continue
            if exclude_srcs and url in exclude_srcs:
                continue  # was already on the grid before this submit: the previous card's image
            seen_urls.add(url)
            image = GeneratedImage.__new__(GeneratedImage)
            image._raw = {"visible_ui_fallback": True, **item}
            image.media_name = f"visible-flow-{index}.jpg"
            image.project_id = ""
            image.workflow_id = str(item.get("workflow_id") or fallback_workflow_id or "").strip()
            image.fife_url = url
            image.seed = 0
            image.model = ""
            image.prompt = prompt
            image.dimensions = {"width": int(item.get("width") or 0), "height": int(item.get("height") or 0)}
            image.file_path = None
            images.append(image)
        return images[:target]

    FLOW_VISIBLE_PANEL_TEXT_JS = """
        /* flow-visible-text */
        () => {
          const visible = (node) => {
            if (!node || !(node instanceof Element)) return false;
            const style = window.getComputedStyle(node);
            const rect = node.getBoundingClientRect();
            return style.display !== 'none'
              && style.visibility !== 'hidden'
              && style.opacity !== '0'
              && rect.width > 0
              && rect.height > 0
              && rect.bottom > 0
              && rect.top < window.innerHeight;
          };
          return [...document.querySelectorAll('[role="alert"], [role="status"], button, div, span, p')]
            .filter(visible)
            .map((node) => node.innerText || node.textContent || '')
            .filter(Boolean)
            .join('\\n');
        }
    """

    FLOW_AGENT_TRY_AGAIN_CLICK_JS = """
        /* agent-try-again-click */
        () => {
          const visible = (el) => {
            if (!el || !(el instanceof Element)) return false;
            const rect = el.getBoundingClientRect();
            const style = window.getComputedStyle(el);
            return style.display !== 'none' && style.visibility !== 'hidden' && style.opacity !== '0'
              && rect.width >= 40 && rect.height >= 20 && rect.bottom > 0 && rect.top < window.innerHeight
              && rect.left >= window.innerWidth * 0.35;
          };
          const labelFor = (el) => [el.textContent || '', el.getAttribute('aria-label') || ''].join(' ').replace(/\\s+/g, ' ').trim();
          const buttons = [...document.querySelectorAll('button, [role="button"]')]
            .filter(visible)
            .map((el) => ({ el, label: labelFor(el), rect: el.getBoundingClientRect() }))
            .filter((item) => /^(try\\s*again|thử\\s*lại|thu\\s*lai)$/i.test(item.label) || /^try\\s*again/i.test(item.label))
            .sort((a, b) => b.rect.bottom - a.rect.bottom);
          const target = buttons[0];
          if (!target) return { ok: false, label: '' };
          try { target.el.scrollIntoView({ block: 'nearest' }); target.el.click(); } catch (_) { return { ok: false, label: target.label }; }
          return { ok: true, label: target.label.slice(0, 40) };
        }
    """

    async def _visible_flow_agent_failed_message(self, page: Any) -> str:
        try:
            text = await page.evaluate(self.FLOW_VISIBLE_PANEL_TEXT_JS)
        except Exception:
            return ""
        raw = str(text or "").strip()
        if not raw or not self._is_flow_agent_failed_message(raw):
            return ""
        for line in raw.splitlines():
            if self._is_flow_agent_failed_message(line):
                return line.strip()[:200]
        return "Flow Agent: The agent failed. Please try again."

    async def _click_flow_agent_try_again_button(self, page: Any) -> str:
        try:
            result = await page.evaluate(self.FLOW_AGENT_TRY_AGAIN_CLICK_JS)
        except Exception:
            return ""
        if isinstance(result, dict) and result.get("ok"):
            return str(result.get("label") or "Try again")
        return ""

    FLOW_VISIBLE_GRID_KEYS_JS = """
        /* visible-grid-keys */
        () => {
          const srcFor = (img) => {
            const current = img.currentSrc || img.src || '';
            if (current) return current;
            const srcset = img.getAttribute('srcset') || '';
            return srcset.split(',').map((part) => part.trim().split(/\\s+/)[0]).filter(Boolean).pop() || '';
          };
          return Array.from(document.querySelectorAll('img[src], img[srcset]'))
            .map(srcFor)
            .filter((src) => src && !src.startsWith('data:') && !src.startsWith('blob:'));
        }
    """

    async def _visible_flow_grid_image_keys(self, client: Any) -> set[str]:
        """Every image src currently rendered on the Flow page (taken right before a submit)."""
        try:
            page = await client._bm.page()
            items = await page.evaluate(self.FLOW_VISIBLE_GRID_KEYS_JS)
        except Exception:
            return set()
        return {str(item).strip() for item in (items if isinstance(items, list) else []) if str(item or "").strip()}

    async def _wait_for_flow_agent_images_after_submit(
        self,
        client: Any,
        page: Any,
        known_media: set[str],
        *,
        prompt: str,
        target_count: int,
        timeout_s: float,
        fallback_workflow_id: str = "",
        job_id: str = "",
        visible_before: set[str] | None = None,
        settle_s: float = 45.0,
    ) -> List[Any]:
        """Wait for images the Agent actually generated for THIS submit.

        Two sources, both filtered for newness: project-API media not in ``known_media``, and
        grid images whose src was not on the page before the submit (``visible_before``). The
        API is unreliable on large projects (3170's project routinely fails to load), which is
        why the old unfiltered grid fallback existed and why it handed back the previous
        card's images when the Agent failed (2026-09-07/08 incident). When the panel shows
        "The agent failed" the app presses Try again once; a second failure with no new images
        raises FlowAgentFailedError so the caller retries on a fresh session.
        """
        target = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(target_count or 1)))
        deadline = time.monotonic() + max(10.0, float(timeout_s or 60.0))
        best: List[Any] = []
        best_changed_at = time.monotonic()
        try_again_clicked = False
        api_failures = 0
        api_failure_logged = False
        while True:
            # Check the panel first: a failed agent never produces images, so do not burn the budget waiting.
            message = await self._visible_flow_agent_failed_message(page)
            if message:
                if not try_again_clicked:
                    try_again_clicked = True
                    label = await self._click_flow_agent_try_again_button(page)
                    if job_id:
                        await self.store.append_log(
                            job_id,
                            f"Flow Agent báo lỗi ({message[:80]}); app bấm '{label or 'Try again'}' một lần rồi chờ tiếp, không lấy ảnh cũ trong grid.",
                        )
                    await asyncio.sleep(3.0)
                    continue
                if best:
                    return best[:target]
                raise FlowAgentFailedError(f"Flow Agent failed twice, no new images: {message[:160]}")
            now = time.monotonic()
            if now >= deadline:
                break
            api_images: List[Any] = []
            try:
                project_data = await client._api.get_project_data()
            except Exception as exc:
                project_data = None
                api_failures += 1
                if api_failures >= 3 and job_id and not api_failure_logged:
                    api_failure_logged = True
                    await self.store.append_log(
                        job_id,
                        f"Fallback UI Flow: API project khong doc duoc ({humanize_flow_error(str(exc))[:80]}); app theo doi grid Flow de nhan anh moi cua card nay.",
                    )
            if isinstance(project_data, dict):
                api_images = self._project_generated_images(
                    project_data,
                    known_media=known_media,
                    prompt=prompt,
                    limit=target,
                    fallback_workflow_id=fallback_workflow_id,
                )
                if api_images and any(not str(getattr(image, "fife_url", "") or "").strip() for image in api_images):
                    try:
                        urls_by_workflow = await self._flow_project_image_urls_by_workflow(client)
                    except Exception:
                        urls_by_workflow = {}
                    for image in api_images:
                        if not str(getattr(image, "fife_url", "") or "").strip():
                            image.fife_url = urls_by_workflow.get(str(getattr(image, "workflow_id", "") or "").strip(), "")
                    api_images = [image for image in api_images if str(getattr(image, "fife_url", "") or "").strip()]
            grid_images: List[Any] = []
            if visible_before is not None:
                grid_images = await self._visible_flow_project_images_from_page(
                    client,
                    prompt=prompt,
                    target_count=target,
                    fallback_workflow_id=fallback_workflow_id,
                    exclude_srcs=visible_before,
                )
            candidate = api_images if len(api_images) >= len(grid_images) else grid_images
            if len(candidate) > len(best):
                best = candidate
                best_changed_at = time.monotonic()
            if len(best) >= target:
                return best[:target]
            if best and time.monotonic() - best_changed_at >= max(5.0, float(settle_s or 45.0)):
                return best[:target]
            await asyncio.sleep(3.0)
        if best:
            return best[:target]
        if not known_media and visible_before is None:
            visible_images = await self._visible_flow_project_images_from_page(
                client,
                prompt=prompt,
                target_count=target,
                fallback_workflow_id=fallback_workflow_id,
            )
            if visible_images:
                return visible_images[:target]
        raise RuntimeError("Google Flow không trả ảnh mới trong project sau khi bấm tạo ảnh.")

    async def _wait_for_new_project_images(
        self,
        client: Any,
        known_media: set[str],
        *,
        prompt: str,
        target_count: int,
        timeout_s: float,
        fallback_workflow_id: str = "",
        settle_s: float = 4.0,
        allow_visible_fallback: bool = False,
    ) -> List[Any]:
        target = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(target_count or 1)))
        deadline = time.monotonic() + max(5.0, float(timeout_s or 30))
        settle_window = max(1.0, float(settle_s or 4.0))
        best: List[Any] = []
        first_seen_at = 0.0

        while time.monotonic() < deadline:
            try:
                project_data = await client._api.get_project_data()
            except Exception:
                await asyncio.sleep(1.0)
                continue

            images = self._project_generated_images(
                project_data,
                known_media=known_media,
                prompt=prompt,
                limit=target,
                fallback_workflow_id=fallback_workflow_id,
            )
            if images and any(not str(getattr(image, "fife_url", "") or "").strip() for image in images):
                urls_by_workflow = await self._flow_project_image_urls_by_workflow(client)
                for image in images:
                    if str(getattr(image, "fife_url", "") or "").strip():
                        continue
                    workflow_id = str(getattr(image, "workflow_id", "") or "").strip()
                    image.fife_url = urls_by_workflow.get(workflow_id, "")
                images = [image for image in images if str(getattr(image, "fife_url", "") or "").strip()]
            if len(images) > len(best):
                best = images
                first_seen_at = first_seen_at or time.monotonic()
            if len(best) >= target:
                return best[:target]
            if best and first_seen_at and time.monotonic() - first_seen_at >= settle_window:
                return best[:target]
            await asyncio.sleep(1.0)

        if best:
            return best[:target]
        if allow_visible_fallback:
            visible_images = await self._visible_flow_project_images_from_page(
                client,
                prompt=prompt,
                target_count=target,
                fallback_workflow_id=fallback_workflow_id,
            )
            if visible_images:
                return visible_images[:target]
        raise RuntimeError("Google Flow không trả ảnh mới trong project sau khi bấm tạo ảnh.")

    async def _generate_image_edit_result(
        self,
        client: Any,
        prompt: str,
        *,
        model: str,
        aspect: str,
        count: int,
        reference_media_names: List[str],
        workflow_id: str = "",
    ) -> List[Any]:
        normalized_media_names = self._normalize_reference_media_names(reference_media_names)
        if not normalized_media_names:
            raise RuntimeError("Chưa có ảnh nào để dùng làm đầu vào chỉnh sửa.")

        base_media_name = normalized_media_names[0]
        extra_reference_media_names = normalized_media_names[1:]
        resolved_workflow_id = str(workflow_id or "").strip() or await self._find_workflow_id_for_media(client, base_media_name)
        if not resolved_workflow_id:
            raise RuntimeError(
                "Google Flow chưa tìm thấy workflow gắn với ảnh gốc. Hãy thử tải lại ảnh rồi chạy lại giúp em."
            )

        client_context = dict(await client._api._client_context())
        client_context["workflowId"] = resolved_workflow_id

        image_inputs = [
            {
                "imageInputType": "IMAGE_INPUT_TYPE_BASE_IMAGE",
                "name": base_media_name,
            }
        ]
        image_inputs.extend(
            {
                "imageInputType": "IMAGE_INPUT_TYPE_REFERENCE",
                "name": media_name,
            }
            for media_name in extra_reference_media_names
        )

        body = {
            "clientContext": client_context,
            "mediaGenerationContext": {"batchId": str(uuid.uuid4())},
            "useNewMedia": True,
            "requests": [
                {
                    "clientContext": dict(client_context),
                    "imageModelName": self._image_edit_model_name(model),
                    "imageAspectRatio": self._image_api_aspect_ratio(aspect),
                    "structuredPrompt": {"parts": [{"text": prompt}]},
                    "seed": random.randint(0, 2**31 - 1),
                    "imageInputs": list(image_inputs),
                }
                for _ in range(max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(count or 1))))
            ],
        }
        data = await client._api._fetch(
            "POST",
            f"projects/{client._api.project_id}/flowMedia:batchGenerateImages",
            body,
        )

        from flow._api import GeneratedImage

        images = [GeneratedImage(item) for item in data.get("media", [])]
        for image in images:
            image.prompt = prompt
        if not images:
            raise RuntimeError("Google Flow không trả ảnh nào về từ yêu cầu chỉnh sửa hiện tại.")
        return images

    async def _generate_images_with_retry(
        self,
        client: Any,
        job_id: str,
        request: CreateJobRequest,
        reference_media_names: List[str],
    ) -> List[Any]:
        local_reference_paths = self._normalize_local_upload_paths(request.reference_image_paths or [])
        if (reference_media_names or local_reference_paths) and self._request_requires_flow_agent_ui(request):
            await self.store.append_log(
                job_id,
                "Auto AI Trello dùng Tác nhân Flow: app sẽ chạy qua giao diện Flow Agent, không gửi API prompt thường.",
            )
            return await self._generate_images_via_ui(client, request, reference_media_names, job_id=job_id)

        try:
            return await self._generate_images_once(client, request, reference_media_names)
        except Exception as exc:
            if self._is_recaptcha_error(exc):
                await self.store.append_log(
                    job_id,
                    "Flow API tu choi luot gui tu dong. Em dang chuyen sang duong chay qua giao dien Flow de thu lai.",
                )
                await self._set_job_progress(
                    job_id,
                    "sending_request",
                    "Flow API tu choi luot gui truc tiep. Em dang tai lai project va gui lai bang giao dien Flow.",
                )
            elif self._is_image_model_error(exc):
                await self.store.append_log(
                    job_id,
                    "Flow API chua nhan model anh da chon. Em dang chuyen sang giao dien Flow de chon model bang ten hien thi.",
                )
                await self._set_job_progress(
                    job_id,
                    "sending_request",
                    "Flow API chua nhan model anh da chon. Em dang tai lai project va gui lai bang giao dien Flow.",
                )
            else:
                raise

            await self._reload_flow_project_page(client)
            return await self._generate_images_via_ui(client, request, reference_media_names, job_id=job_id)

    async def _generate_images_once(
        self,
        client: Any,
        request: CreateJobRequest,
        reference_media_names: List[str],
    ) -> List[Any]:
        target_count = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(request.count or 1)))
        if reference_media_names:
            return await self._generate_image_edit_result(
                client,
                request.prompt,
                model=request.model,
                aspect=request.aspect,
                count=target_count,
                reference_media_names=reference_media_names,
                workflow_id=request.workflow_id or "",
            )
        return await client._api.generate_image(
            request.prompt,
            model=self._image_api_model_name(request.model),
            aspect_ratio=self._image_api_aspect_ratio(request.aspect),
            count=target_count,
        )

    async def _generate_images_via_ui(
        self,
        client: Any,
        request: CreateJobRequest,
        reference_media_names: List[str],
        *,
        job_id: str = "",
    ) -> List[Any]:
        reference_media_names = self._normalize_reference_media_names(reference_media_names or [])
        requested_reference_path = str((request.reference_image_paths or [""])[0] if request.reference_image_paths else "").strip()
        local_reference_paths = self._normalize_local_upload_paths(request.reference_image_paths or [])
        local_reference_path = local_reference_paths[0] if local_reference_paths else (requested_reference_path if reference_media_names else "")
        flow_agent_enabled = self._flow_agent_enabled_for_request(request)
        if reference_media_names or (flow_agent_enabled and local_reference_path):
            if len(reference_media_names) > 1:
                raise RuntimeError(
                    "Flow API dang chan nhanh ghep nhieu anh, nen em chua the fallback UI an toan cho hon 1 anh tham chieu."
                )
            target_count = max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(request.count or 1)))
            flow_agent_enabled = self._flow_agent_enabled_for_request(request)
            source_workflow_id = str(request.workflow_id or "").strip()
            if flow_agent_enabled and reference_media_names:
                media_workflow_id = await self._find_workflow_id_for_media(client, reference_media_names[0])
                if media_workflow_id:
                    source_workflow_id = media_workflow_id
            if flow_agent_enabled and not source_workflow_id and reference_media_names:
                raise RuntimeError("Google Flow chua tim thay workflow cua anh goc de mo man hinh chinh anh.")

            require_project_media_baseline = self._trello_source_validation_required(request)
            if flow_agent_enabled and target_count > self._flow_agent_max_images_per_run():
                max_per_run = self._flow_agent_max_images_per_run()
                run_counts: List[int] = []
                remaining = target_count
                while remaining > 0:
                    run_count = max(1, min(max_per_run, remaining))
                    run_counts.append(run_count)
                    remaining -= run_count

                generated: List[Any] = []
                for run_index, run_count in enumerate(run_counts):
                    prompt = self._flow_agent_multi_image_prompt(
                        request.prompt,
                        run_count,
                        shot_offset=len(generated),
                        full_total=target_count,
                    )
                    if job_id:
                        await self.store.append_log(
                            job_id,
                            f"Flow Agent tao luot {run_index + 1}/{len(run_counts)}: {run_count}/{target_count} anh bang setting x{run_count}.",
                        )

                    tries = 3
                    last_exc: Exception | None = None
                    batch_generated: List[Any] = []
                    for attempt in range(tries):
                        try:
                            batch_generated = await self._generate_single_reference_image_via_ui(
                                client,
                                prompt,
                                model=request.model,
                                workflow_id=source_workflow_id,
                                reference_media_name=reference_media_names[0] if reference_media_names else "",
                                reference_image_path=local_reference_path,
                                aspect=request.aspect,
                                count=run_count,
                                timeout_s=max(30, int(request.timeout_s or self.store.snapshot().config.generation_timeout_s or 300)),
                                flow_agent_enabled=True,
                                flow_agent_auto_approve=self._flow_agent_auto_approve_enabled_for_request(request),
                                job_id=job_id,
                                require_project_media_baseline=require_project_media_baseline,
                            )
                            break
                        except Exception as exc:
                            last_exc = exc
                            normalized_detail = str(exc or "").lower()
                            retryable = self._is_retryable_flow_agent_ui_error(normalized_detail)
                            if not retryable or attempt >= tries - 1:
                                raise
                            if job_id:
                                if self._is_stale_flow_agent_context_error(normalized_detail):
                                    retry_note = (
                                        f"Flow Agent còn hội thoại/ngữ cảnh cũ khi tạo x{run_count}; "
                                        "app đã đóng tab Agent cũ và thử lại trên tab sạch."
                                    )
                                else:
                                    retry_note = f"Flow Agent báo bận/reCAPTCHA khi tạo x{run_count}; app nghỉ rồi thử lại 1 lần."
                                await self.store.append_log(
                                    job_id,
                                    retry_note,
                                )
                            await asyncio.sleep(self._flow_agent_ui_retry_delay_s(normalized_detail))

                    if not batch_generated and last_exc is not None:
                        raise last_exc
                    if len(batch_generated) < run_count:
                        if not batch_generated:
                            raise RuntimeError(f"Flow Agent chua tao duoc anh nao trong luot x{run_count}.")
                        if job_id:
                            await self.store.append_log(
                                job_id,
                                (
                                    f"Flow Agent chi tao duoc {len(batch_generated)}/{run_count} anh trong luot x{run_count}; "
                                    f"app se upload {len(batch_generated)} anh da co roi chuyen sang card tiep theo."
                                ),
                            )
                        generated.extend(batch_generated[:run_count])
                        break
                    generated.extend(batch_generated[:run_count])
                    if len(generated) < target_count:
                        if job_id:
                            await self._sleep_between_flow_agent_batches(job_id, run_index + 2, len(run_counts))
                        else:
                            min_s, max_s = self._flow_agent_batch_pause_range_s()
                            if max_s > 0:
                                await asyncio.sleep(float(random.randint(min_s, max_s)))

                return generated[:target_count]

            prompt = request.prompt
            if flow_agent_enabled:
                prompt = self._flow_agent_multi_image_prompt(request.prompt, target_count)
                if job_id:
                    await self.store.append_log(
                        job_id,
                        f"Flow Agent tạo {target_count} ảnh trong 1 lần bằng setting x{target_count}; app không tách 4 lượt.",
                    )

            tries = 3 if flow_agent_enabled else 1
            last_exc: Exception | None = None
            generated: List[Any] = []
            for attempt in range(tries):
                try:
                    generated = await self._generate_single_reference_image_via_ui(
                        client,
                        prompt,
                        model=request.model,
                        workflow_id=source_workflow_id,
                        reference_media_name=reference_media_names[0] if reference_media_names else "",
                        reference_image_path=local_reference_path,
                        aspect=request.aspect,
                        count=target_count,
                        timeout_s=max(30, int(request.timeout_s or self.store.snapshot().config.generation_timeout_s or 300)),
                        flow_agent_enabled=flow_agent_enabled,
                        flow_agent_auto_approve=self._flow_agent_auto_approve_enabled_for_request(request),
                        job_id=job_id,
                        require_project_media_baseline=require_project_media_baseline,
                    )
                    break
                except Exception as exc:
                    last_exc = exc
                    detail = str(exc or "")
                    normalized_detail = detail.lower()
                    retryable = self._is_retryable_flow_agent_ui_error(normalized_detail)
                    if not flow_agent_enabled or not retryable or attempt >= tries - 1:
                        raise
                    if job_id:
                        if self._is_stale_flow_agent_context_error(normalized_detail):
                            retry_note = (
                                f"Flow Agent còn hội thoại/ngữ cảnh cũ khi tạo x{target_count}; "
                                "app đã đóng tab Agent cũ và thử lại trên tab sạch."
                            )
                        else:
                            retry_note = f"Flow Agent báo bận/reCAPTCHA khi tạo x{target_count}; app nghỉ rồi thử lại 1 lần đủ bộ."
                        await self.store.append_log(
                            job_id,
                            retry_note,
                        )
                    await asyncio.sleep(self._flow_agent_ui_retry_delay_s(normalized_detail))

            if not generated and last_exc is not None:
                raise last_exc
            if flow_agent_enabled and len(generated) < target_count:
                if generated:
                    if job_id:
                        await self.store.append_log(
                            job_id,
                            (
                                f"Flow Agent chi tao duoc {len(generated)}/{target_count} anh trong luot x{target_count}; "
                                f"app se upload {len(generated)} anh da co roi chuyen sang card tiep theo."
                            ),
                        )
                    return generated[:target_count]
                raise RuntimeError(
                    f"Flow Agent chỉ tạo được {len(generated)}/{target_count} ảnh trong lượt x{target_count}. "
                    "App đã dừng trước khi upload lên Trello để tránh bộ ảnh thiếu."
                )
            return generated[:target_count]
        return await client.generate_image(
            request.prompt,
            model=self._image_ui_model_label(request.model),
            aspect=request.aspect,
            count=max(1, min(self.FLOW_AGENT_MAX_OUTPUT_COUNT, int(request.count or 1))),
            timeout_s=max(30, int(request.timeout_s or self.store.snapshot().config.generation_timeout_s or 300)),
        )

    def _is_stale_flow_agent_context_error(self, detail: str) -> bool:
        normalized = str(detail or "").lower()
        return any(
            marker in normalized
            for marker in (
                "old context",
                "hoi thoai cu",
                "ngữ cảnh cũ",
                "ngu canh project cu",
                "context project cu",
                "old flow agent conversation",
                "tac nhan flow dang mo lai",
                "agent context",
            )
        )

    def _is_retryable_flow_agent_ui_error(self, detail: str) -> bool:
        normalized = str(detail or "").lower()
        return (
            self._is_stale_flow_agent_context_error(normalized)
            or self._is_flow_agent_try_again_error(normalized)
            or any(
                marker in normalized
                for marker in (
                    "invalid argument",
                    "recaptcha",
                    "403",
                    "timeout",
                    "timed out",
                    "thoi gian cho",
                    "chua tra ve anh",
                    "agent failed",
                    "tac nhan flow that bai",
                )
            )
        )

    def _flow_agent_ui_retry_delay_s(self, detail: str) -> float:
        normalized = str(detail or "").lower()
        if self._is_stale_flow_agent_context_error(normalized):
            return 4.0
        if self._is_flow_agent_try_again_error(normalized):
            return 8.0
        if "agent failed" in normalized or "tac nhan flow that bai" in normalized:
            return 20.0
        return 45.0 if ("recaptcha" in normalized or "403" in normalized) else 25.0

